#!/usr/bin/env python3
"""CES operator console (EC278, extended EC279-EC327): privilege-separated action entry.

A thin *operator interface*, not a permission broker. Modern calls use the
existing EC241/243 allowlisted router in a separate isolated Python process;
legacy calls use the original R150 PowerShell script with its own checks. This
module never synthesizes credentials, alters request JSON, or converts a
partial/unverified result to success.
"""
from __future__ import annotations

import argparse
import json
import os
from pathlib import Path
import re
import shutil
import subprocess
import sys
import tempfile
from typing import Any

