    if (type(registrar_id) is not str or
        re.fullmatch(r'[a-z][a-z0-9_-]{1,31}',registrar_id) is None or
        not sha64(registrar_public_hex)):
        _fail('EC319_EXTERNALLY_TRUSTED_REGISTRAR_ID_AND_KEY_REQUIRED')
