def audit_relocation_copies(action: str, mode: str, *,
                            plan_file: str, expected_plan_sha256: str,
                            map_file: str, expected_map_sha256: str,
                            pretty: bool = False) -> int:
    """EC334 isolated read-only audit of private relocated first-hop bytes.

    This deliberately cannot call the inventory writer or prefix-map writer.
    Matching relocated bytes does NOT replay historical path-sensitive old
    signatures, prove complete nested sources or grant remote CAS authority.
    """
    if (action, mode) != ('DeliveryAudit', 'VerifyRelocatedFirstHopSourceCopies'):
        _fail('EC334_ONLY_DELIVERYAUDIT_VERIFY_RELOCATED_FIRST_HOP_SOURCE_COPIES',
              status='permission_denied')
    if (not SOURCE_RELOCATION_INVENTORY.is_file() or
            SOURCE_RELOCATION_INVENTORY.is_symlink()):
        _fail('EC334_FIXED_ISOLATED_RELOCATION_AUDITOR_MISSING',
              status='unavailable')
    for label, path, digest in (
        ('PLAN', plan_file, expected_plan_sha256),
        ('MAP', map_file, expected_map_sha256),
    ):
        if not (type(path) is str and os.path.isabs(path) and
                os.path.normpath(path) == path and not path.startswith('//') and
                len(path) <= 4000 and '\\' not in path and '\x00' not in path and
                type(digest) is str and
                re.fullmatch('[0-9a-f]{64}', digest) is not None and
                digest != '0' * 64):
            _fail('EC334_' + label + '_NORMALIZED_ABSOLUTE_AND_EXTERNAL_PIN_REQUIRED')
    if plan_file == map_file:
        _fail('EC334_PLAN_AND_MAP_MUST_BE_DISTINCT')
    cmd = [sys.executable, '-I', '-B', str(SOURCE_RELOCATION_INVENTORY),
           'verify-copies', '--plan-file', plan_file,
           '--expected-plan-sha256', expected_plan_sha256,
           '--map-file', map_file, '--expected-map-sha256', expected_map_sha256]
    rc, doc = _command(cmd, timeout=7200, max_output=16000)
    false = (
        'path_mapping_rewrites_original_signed_or_hashed_bytes',
        'destination_replay_of_full_ec294_to_ec333_original_signatures_performed',
        'first_hop_inventory_proves_all_nested_historical_originals_present',
        'unsigned_inventory_or_mapping_is_signed_or_institutionally_authorized',
        'provided_sha_proves_independent_out_of_band_custody',
        'copy_check_proves_external_cas_worm_actual_nonexecution_or_global_winner',
        'actual_external_business_store_write_performed',
        'all_source_paths_equivalent_for_signature_context_after_relocation',
    )
    if rc == 2:
        if (doc.get('schema') != 'ces.ec334.offline_copy_integrity_preflight.v1' or
            doc.get('command') != 'verify-copies' or
            doc.get('status') !=
                'first_hop_relocated_private_copy_bytes_match_unsigned_pinned_inventory_unresolved' or
            type(doc.get('exit_code')) is not int or doc['exit_code'] != 2 or
            doc.get('inventory_original_raw_sha256') != expected_plan_sha256 or
            doc.get('mapping_original_raw_sha256') != expected_map_sha256 or
            type(doc.get('source_count')) is not int or
            not 3 <= doc['source_count'] <= 1024 or
            type(doc.get('total_source_byte_length')) is not int or
            not 3 <= doc['total_source_byte_length'] <= 192000000 or
            type(doc.get('distinct_original_raw_sha_count')) is not int or
            not 1 <= doc['distinct_original_raw_sha_count'] <= doc['source_count'] or
            doc.get('destination_bytes_match_every_first_hop_original') is not True or
            doc.get('source_side_full_signed_original_replay_required_for_plan_creation') is not True or
            doc.get('copy_check_is_first_hop_only_and_never_signature_rebinding') is not True or
            doc.get('original_and_destination_anchors_require_real_external_trust') is not True or
            any(doc.get(key) is not False for key in false)):
            _fail('EC334_ISOLATED_SOURCE_COPY_REPLY_UNGROUNDED_OR_CLAIMS_AUTHORITY',
                  status='unavailable')
    elif rc in (3, 4, 5):
        if (doc.get('schema') != 'ces.ec334.offline_copy_integrity_preflight_denial.v1' or
            doc.get('command') != 'verify-copies' or
            doc.get('exit_code') != rc or
            STATUS_EXITS.get(doc.get('status')) != rc or
            doc.get('destination_bytes_match_every_first_hop_original') is not False or
            doc.get('source_side_full_signed_original_replay_required_for_plan_creation') is not True or
            doc.get('copy_check_is_first_hop_only_and_never_signature_rebinding') is not True or
            any(doc.get(key) is not False for key in false)):
            _fail('EC334_ISOLATED_SOURCE_COPY_DENIAL_NOT_GROUNDED',
                  status='unavailable')
    else:
        _fail('EC334_ISOLATED_SOURCE_COPY_PROCESS_EXIT_INVALID',
              status='unavailable')
    _emit(doc, pretty=pretty)
    return rc



