def audit_checkpoint_disclosures(action:str,mode:str,*,pretty:bool=False,**inputs)->int:
    if (action,mode)!=('DeliveryAudit','AuditSignedCheckpointDisclosures'):
        _fail('EC355_ONLY_DELIVERYAUDIT_SIGNED_CHECKPOINT_DISCLOSURES_READONLY',
              status='permission_denied')
    if (not AIRGAP_CHECKPOINT_DISCLOSURE.is_file() or
            AIRGAP_CHECKPOINT_DISCLOSURE.is_symlink()):
        _fail('EC355_FIXED_DISCLOSURE_VERIFIER_UNAVAILABLE',status='unavailable')
    if set(inputs)!=set((*EC355_KEYS,*(k for k,_ in EC355_REPEATS))):
        _fail('EC355_FULL_EC354_AND_DISCLOSURE_ORIGINAL_INPUTS_REQUIRED')
    valid_path=lambda v: type(v) is str and os.path.isabs(v) and os.path.normpath(v)==v and not v.startswith('//') and '\\' not in v and '\x00' not in v and len(v)<=4000
    valid_sha=lambda v: type(v) is str and re.fullmatch('[0-9a-f]{64}',v) is not None and v!='0'*64
    valid_utc=lambda v: type(v) is str and re.fullmatch(r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ',v) is not None
    if not all(valid_utc(inputs[k]) for k in (
            'dual_evaluation_utc','tsa_evaluation_utc','provenance_evaluation_utc',
            'registry_evaluation_utc','publication_evaluation_utc','gossip_evaluation_utc',
            'checkpoint_disclosure_evaluation_utc')):
        _fail('EC355_SEVEN_STRICT_EVALUATION_UTC_VALUES_REQUIRED')
    if any(not valid_path(inputs[k]) or not valid_sha(inputs[h]) for k,h in (
            ('publication_bundle_file','expected_publication_bundle_sha256'),
            ('gossip_bundle_file','expected_gossip_bundle_sha256'),
            ('checkpoint_disclosure_bundle_file','expected_checkpoint_disclosure_bundle_sha256'))):
        _fail('EC355_THREE_WHOLE_SHA_PINNED_BUNDLES_REQUIRED')
    for k in EC352_KEYS:
        if k.endswith('_utc'):continue
        if type(inputs[k]) not in (str,int):_fail('EC355_PARENT_SCALAR_TYPE_INVALID')
    for k,flag in EC355_REPEATS:
        if (type(inputs[k]) is not list or len(inputs[k])>32 or
                any(type(v) is not str for v in inputs[k])):
            _fail('EC355_PARENT_REPEATS_INVALID')
        if k.endswith('_files') and any(not valid_path(v) for v in inputs[k]):
            _fail('EC355_PARENT_PATH_INVALID')
        if k.endswith('_shas') and any(not valid_sha(v) for v in inputs[k]):
            _fail('EC355_PARENT_SHA_INVALID')
    argv=[sys.executable,'-I','-B',str(AIRGAP_CHECKPOINT_DISCLOSURE),
          'audit-checkpoint-disclosures']
    for k in EC355_KEYS:argv.extend(['--'+k.replace('_','-'),str(inputs[k])])
    for k,flag in EC355_REPEATS:
        for v in inputs[k]:argv.extend([flag,str(v)])
    rc,doc=_command(argv,timeout=7200,max_output=650000)
    base={'schema','command','status','exit_code','offline_unresolved_exit_code',
          'actual_ec354_through_ec337_original_signatures_replayed',*EC355_NEGATIVES}
    if rc==2:
        extra={'case_id','parent_ec354_canonical_result_sha256',
               'parent_gossip_bundle_original_sha256','disclosure_bundle_original_sha256',
               'checkpoint_disclosure_evaluation_utc_as_caller_claim',
               'signed_unfurnished_view_count','signed_request_count','signed_receipt_count',
               'disclosure_claim_evidence','request_sha_predecessor_forks_visible',
               'signed_receipt_equivocation_visible','any_two_target_requests_missing',
               'any_signed_offer_unavailable_or_no_response',
               'any_genuine_new_signed_log_and_witness_pair_verified',
               'verified_same_log_conflict_or_unproved_ancestry_visible',
               'stale_claimed_disclosure_time_visible',
               'both_roles_furnished_same_original_for_all_claims',
               'channel_evidence','outcome_counts',
               'physical_external_identity_custody_utc_global_heads_unproven'}
        claims=doc.get('disclosure_claim_evidence') if type(doc) is dict else None
        rows=doc.get('channel_evidence') if type(doc) is dict else None
        counts=doc.get('outcome_counts') if type(doc) is dict else None
        claimed_keys={'gossip_reply_original_sha256','gossip_challenge_original_sha256',
                      'log_id','claimed_checkpoint_original_sha256','claimed_tree_size',
                      'claimed_root_hash_sha256','challenger_auditor_id',
                      'original_responder_auditor_id','gossip_reply_utc_claim',
                      'parent_challenged_checkpoint_original_sha256',
                      'parent_challenged_tree_size','parent_challenged_root_hash_sha256',
                      'disclosure_requests','both_roles_separately_requested',
                      'valid_original_responder_byte_handoffs',
                      'valid_independent_peer_byte_handoffs',
                      'same_original_observed_by_both_signed_roles',
                      'total_signed_receipt_count'}
        request_keys={'request_original_sha256','requested_role','requested_auditor_id',
                      'previous_request_original_sha256','issued_utc_as_claim',
                      'signed_responses'}
        response_keys={'receipt_original_sha256','respondent_auditor_id','response_kind',
                       'responded_utc_as_claim','verified_furnished_original'}
        original_keys={'checkpoint_original_sha256','checkpoint_length',
                       'witness_original_sha256','witness_length',
                       'witnessed_utc_as_self_claim','claimed_time_order_anomaly',
                       'relation_to_verified_ec353_challenge'}
        relations={'verified_signed_checkpoint_witness_but_append_only_unproven',
                   'verified_matching_same_size_root',
                   'verified_same_log_same_size_conflicting_roots',
                   'verified_rfc6962_append_only_relative_to_challenged_parent'}
        valid=(type(doc) is dict and set(doc)==base|extra and
               doc.get('schema')=='ces.ec355.offline_signed_checkpoint_disclosure_unresolved.v1' and
               doc.get('command')=='audit-checkpoint-disclosures' and
               doc.get('exit_code')==2 and doc.get('offline_unresolved_exit_code')==2 and
               doc.get('actual_ec354_through_ec337_original_signatures_replayed') is True and
               doc.get('physical_external_identity_custody_utc_global_heads_unproven') is True and
               valid_sha(doc.get('parent_ec354_canonical_result_sha256')) and
               doc.get('parent_gossip_bundle_original_sha256')==inputs['expected_gossip_bundle_sha256'] and
               doc.get('disclosure_bundle_original_sha256')==inputs['expected_checkpoint_disclosure_bundle_sha256'] and
               doc.get('checkpoint_disclosure_evaluation_utc_as_caller_claim')==inputs['checkpoint_disclosure_evaluation_utc'] and
               type(claims) is list and len(claims)<=12 and
               doc.get('signed_unfurnished_view_count')==len(claims) and
               type(doc.get('signed_request_count')) is int and 0<=doc['signed_request_count']<=24 and
               type(doc.get('signed_receipt_count')) is int and 0<=doc['signed_receipt_count']<=36 and
               all(type(doc.get(k)) is bool for k in (
                   'request_sha_predecessor_forks_visible','signed_receipt_equivocation_visible',
                   'any_two_target_requests_missing','any_signed_offer_unavailable_or_no_response',
                   'any_genuine_new_signed_log_and_witness_pair_verified',
                   'verified_same_log_conflict_or_unproved_ancestry_visible',
                   'stale_claimed_disclosure_time_visible',
                   'both_roles_furnished_same_original_for_all_claims')) and
               type(rows) is list and len(rows)==2 and
               all(type(r) is dict and set(r)=={'tsa_channel_id','parent_ec354_outcome','outcome'}
                   and r['parent_ec354_outcome'] in EC354_OUTCOMES and r['outcome'] in EC355_OUTCOMES
                   for r in rows) and
               type(counts) is dict and set(counts)==set(EC355_OUTCOMES) and
               all(type(v) is int and 0<=v<=2 for v in counts.values()) and
               sum(counts.values())==2 and
               all(counts[k]==sum(r['outcome']==k for r in rows) for k in counts) and
               doc.get('status')==next(k for k in EC355_OUTCOMES if counts[k])+'_unresolved' and
               all(doc.get(k) is False for k in EC355_NEGATIVES))
        if valid:
            for claim in claims:
                if (type(claim) is not dict or set(claim)!=claimed_keys or
                    not all(valid_sha(claim.get(k)) for k in (
                        'gossip_reply_original_sha256','gossip_challenge_original_sha256',
                        'claimed_checkpoint_original_sha256','claimed_root_hash_sha256',
                        'parent_challenged_checkpoint_original_sha256',
                        'parent_challenged_root_hash_sha256')) or
                    not all(type(claim.get(k)) is str for k in (
                        'log_id','challenger_auditor_id','original_responder_auditor_id')) or
                    not all(type(claim.get(k)) is int and 1<=claim[k]<=64 for k in (
                        'claimed_tree_size','parent_challenged_tree_size')) or
                    not valid_utc(claim.get('gossip_reply_utc_claim')) or
                    type(claim.get('disclosure_requests')) is not list or
                    not all(type(claim.get(k)) is bool for k in (
                        'both_roles_separately_requested','same_original_observed_by_both_signed_roles')) or
                    not all(type(claim.get(k)) is int and 0<=claim[k]<=36 for k in (
                        'valid_original_responder_byte_handoffs',
                        'valid_independent_peer_byte_handoffs','total_signed_receipt_count'))):
                    valid=False;break
                for req in claim['disclosure_requests']:
                    if (type(req) is not dict or set(req)!=request_keys or
                        not valid_sha(req.get('request_original_sha256')) or
                        req.get('requested_role') not in ('original_responder','independent_peer') or
                        type(req.get('requested_auditor_id')) is not str or
                        not valid_utc(req.get('issued_utc_as_claim')) or
                        not (req.get('previous_request_original_sha256')=='GENESIS' or
                             valid_sha(req.get('previous_request_original_sha256'))) or
                        type(req.get('signed_responses')) is not list or
                        len(req['signed_responses'])>2):
                        valid=False;break
                    for reply in req['signed_responses']:
                        if (type(reply) is not dict or set(reply)!=response_keys or
                            not valid_sha(reply.get('receipt_original_sha256')) or
                            reply.get('respondent_auditor_id')!=req['requested_auditor_id'] or
                            reply.get('response_kind') not in (
                                'furnished_originals','offer_only','unavailable_claim') or
                            not valid_utc(reply.get('responded_utc_as_claim'))):
                            valid=False;break
                        original=reply.get('verified_furnished_original')
                        if original is None:
                            if reply['response_kind']=='furnished_originals':valid=False;break
                        elif (reply['response_kind']!='furnished_originals' or
                              type(original) is not dict or set(original)!=original_keys or
                              not valid_sha(original.get('checkpoint_original_sha256')) or
                              original.get('checkpoint_original_sha256')!=claim['claimed_checkpoint_original_sha256'] or
                              not valid_sha(original.get('witness_original_sha256')) or
                              not valid_utc(original.get('witnessed_utc_as_self_claim')) or
                              original.get('relation_to_verified_ec353_challenge') not in relations or
                              type(original.get('claimed_time_order_anomaly')) is not bool or
                              not all(type(original.get(k)) is int and 1<=original[k]<=12000 for k in (
                                  'checkpoint_length','witness_length'))):
                            valid=False;break
                if not valid:break
        if valid:
            valid=(doc['signed_request_count']==sum(len(c['disclosure_requests']) for c in claims) and
                   doc['signed_receipt_count']==sum(c['total_signed_receipt_count'] for c in claims) and
                   [c['gossip_reply_original_sha256'] for c in claims]==sorted(set(
                       c['gossip_reply_original_sha256'] for c in claims)))
        if not valid:_fail('EC355_FIXED_CHILD_REPLY_INVALID_OR_OVERCLAIMS',status='unavailable')
    elif rc in (3,4,5):
        if (type(doc) is not dict or set(doc)!=base|{'reason_code'} or
            doc.get('schema')!='ces.ec355.offline_signed_checkpoint_disclosure_denial.v1' or
            doc.get('command')!='audit-checkpoint-disclosures' or
            doc.get('exit_code')!=rc or STATUS_EXITS.get(doc.get('status'))!=rc or
            doc.get('offline_unresolved_exit_code')!=2 or
            doc.get('actual_ec354_through_ec337_original_signatures_replayed') is not False or
            type(doc.get('reason_code')) is not str or
            re.fullmatch('[A-Z][A-Z0-9_]{2,170}',doc['reason_code']) is None or
            any(doc.get(k) is not False for k in EC355_NEGATIVES)):
            _fail('EC355_FIXED_CHILD_DENIAL_INVALID',status='unavailable')
    else:_fail('EC355_FIXED_CHILD_EXIT_UNEXPECTED',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc


# EC356 is a fixed Python -I/-B read-only verifier. Every caller-furnished
# original and both independently provided root public-key SHA pins are bound.
# No arbitrary module, remote URL, signer, write mode or request file is accepted.
AIRGAP_TWO_CHANNEL_CUSTODY = ROOT / 'scripts' / 'ces_cas_two_channel_custody.py'
EC356_KEYS = (*EC355_KEYS,'two_channel_custody_evaluation_utc','custody_bundle_file',
              'expected_custody_bundle_sha256','root_a_public_key_file',
              'expected_root_a_public_key_sha256','root_b_public_key_file',
              'expected_root_b_public_key_sha256')
EC356_REPEATS = EC355_REPEATS
EC356_OUTCOMES = (
    'ec356_parent_signed_disclosures_or_transparency_unresolved',
    'ec356_no_verified_ec355_furnished_originals_to_custody',
    'ec356_both_separately_pinned_channel_roots_not_furnished',
    'ec356_missing_two_channel_genuine_original_acknowledgements',
    'ec356_signed_acknowledgement_forks_or_equivocation_visible',
    'ec356_institution_claim_collision_or_stale_signed_custody_visible',
    'ec356_no_matching_original_pair_across_distinct_channels_and_ec355_roles',
    'ec356_two_root_authorized_channels_signed_same_original_bytes_external_provenance_unproven',
)
EC356_NEGATIVES = (
    'caller_pinned_root_keys_prove_real_out_of_band_institution_authentication',
    'different_root_or_channel_signatures_prove_separate_legal_entities',
    'different_original_paths_prove_separate_physical_custody_sites',
    'signed_sha_only_or_unavailable_claim_proves_bytes_custodied',
    'self_declared_custody_time_proves_trusted_utc_or_tsa',
    'two_channel_quorum_proves_global_head_or_hidden_fork_absence',
    'channel_quorum_repairs_conflicting_ec355_or_ec354_ancestry',
    'two_channel_quorum_proves_official_external_accreditation',
    'audit_fetches_urls_or_uses_system_or_remote_trust_store',
    'audit_signs_creates_keys_or_writes_provider_cas_worm',
    'ec317_ec318_production_and_final_user_acceptance_proven',
)


def audit_two_channel_custody(action:str,mode:str,*,pretty:bool=False,**inputs)->int:
    if (action,mode)!=('DeliveryAudit','AuditTwoChannelCustody'):
        _fail('EC356_ONLY_DELIVERYAUDIT_TWO_CHANNEL_CUSTODY_READONLY',
              status='permission_denied')
    if (not AIRGAP_TWO_CHANNEL_CUSTODY.is_file() or
            AIRGAP_TWO_CHANNEL_CUSTODY.is_symlink()):
        _fail('EC356_FIXED_CUSTODY_VERIFIER_UNAVAILABLE',status='unavailable')
    if set(inputs)!=set((*EC356_KEYS,*(k for k,_ in EC356_REPEATS))):
        _fail('EC356_FULL_EC355_AND_CUSTODY_ORIGINAL_INPUTS_REQUIRED')
    path_ok=lambda x: type(x) is str and os.path.isabs(x) and os.path.normpath(x)==x and not x.startswith('//') and '\\' not in x and '\x00' not in x and len(x)<=4000
    sha_ok=lambda x: type(x) is str and re.fullmatch('[0-9a-f]{64}',x) is not None and x!='0'*64
    utc_ok=lambda x: type(x) is str and re.fullmatch(r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ',x) is not None
    if any(not utc_ok(inputs[k]) for k in (
           'dual_evaluation_utc','tsa_evaluation_utc','provenance_evaluation_utc',
           'registry_evaluation_utc','publication_evaluation_utc','gossip_evaluation_utc',
           'checkpoint_disclosure_evaluation_utc','two_channel_custody_evaluation_utc')):
        _fail('EC356_EIGHT_STRICT_EVALUATION_UTC_VALUES_REQUIRED')
    for k,h in (('publication_bundle_file','expected_publication_bundle_sha256'),
                ('gossip_bundle_file','expected_gossip_bundle_sha256'),
                ('checkpoint_disclosure_bundle_file','expected_checkpoint_disclosure_bundle_sha256'),
                ('custody_bundle_file','expected_custody_bundle_sha256'),
                ('root_a_public_key_file','expected_root_a_public_key_sha256'),
                ('root_b_public_key_file','expected_root_b_public_key_sha256')):
        if not path_ok(inputs[k]) or not sha_ok(inputs[h]):
            _fail('EC356_SIX_SHA_PINNED_BUNDLE_AND_ROOT_ORIGINALS_REQUIRED')
    if (inputs['root_a_public_key_file']==inputs['root_b_public_key_file'] or
        inputs['expected_root_a_public_key_sha256']==inputs['expected_root_b_public_key_sha256']):
        _fail('EC356_DISTINCT_EXTERNALLY_CALLER_PINNED_ROOTS_REQUIRED',
              status='permission_denied')
    for k in EC352_KEYS:
        if k.endswith('_utc'):continue
        if type(inputs[k]) not in (str,int):_fail('EC356_PARENT_SCALAR_TYPE_INVALID')
    for k,flag in EC356_REPEATS:
        if (type(inputs[k]) is not list or len(inputs[k])>32 or
             any(type(v) is not str for v in inputs[k])):
            _fail('EC356_PARENT_REPEATS_INVALID')
        if k.endswith('_files') and any(not path_ok(v) for v in inputs[k]):
            _fail('EC356_PARENT_PATH_INVALID')
        if k.endswith('_shas') and any(not sha_ok(v) for v in inputs[k]):
            _fail('EC356_PARENT_SHA_INVALID')
    argv=[sys.executable,'-I','-B',str(AIRGAP_TWO_CHANNEL_CUSTODY),
          'audit-two-channel-custody']
    for k in EC356_KEYS:argv.extend(['--'+k.replace('_','-'),str(inputs[k])])
    for k,flag in EC356_REPEATS:
        for v in inputs[k]:argv.extend([flag,str(v)])
    rc,doc=_command(argv,timeout=7200,max_output=700000)
    base={'schema','command','status','exit_code','offline_unresolved_exit_code',
          'actual_ec355_through_ec337_signed_originals_replayed',*EC356_NEGATIVES}
    if rc==2:
        extra={'case_id','parent_ec355_canonical_result_sha256',
               'parent_disclosure_bundle_original_sha256','custody_bundle_original_sha256',
               'two_channel_custody_evaluation_utc_as_caller_claim',
               'externally_caller_pinned_root_key_sha256','channel_establishments',
               'signed_acknowledgement_count','genuine_furnished_parent_receipt_count',
               'claim_custody_evidence','signed_ack_sha_predecessor_forks_visible',
               'signed_ack_equivocation_visible',
               'incompatible_signed_original_sha_pairs_visible',
               'claimed_institution_or_site_identity_collision_visible',
               'stale_custody_self_claimed_utc_visible',
               'two_channel_cross_role_exact_original_quorum_for_all_claims',
               'out_of_band_root_custody_source_and_real_external_independence_unproven',
               'channel_evidence','outcome_counts'}
        rows=doc.get('channel_evidence') if type(doc) is dict else None
        counts=doc.get('outcome_counts') if type(doc) is dict else None
        channels=doc.get('channel_establishments') if type(doc) is dict else None
        claims=doc.get('claim_custody_evidence') if type(doc) is dict else None
        roots=doc.get('externally_caller_pinned_root_key_sha256') if type(doc) is dict else None
        valid=(type(doc) is dict and set(doc)==base|extra and
               doc.get('schema')=='ces.ec356.offline_two_channel_custody_unresolved.v1' and
               doc.get('command')=='audit-two-channel-custody' and
               doc.get('exit_code')==2 and doc.get('offline_unresolved_exit_code')==2 and
               doc.get('actual_ec355_through_ec337_signed_originals_replayed') is True and
               doc.get('out_of_band_root_custody_source_and_real_external_independence_unproven') is True and
               sha_ok(doc.get('parent_ec355_canonical_result_sha256')) and
               doc.get('parent_disclosure_bundle_original_sha256')==inputs['expected_checkpoint_disclosure_bundle_sha256'] and
               doc.get('custody_bundle_original_sha256')==inputs['expected_custody_bundle_sha256'] and
               doc.get('two_channel_custody_evaluation_utc_as_caller_claim')==inputs['two_channel_custody_evaluation_utc'] and
               type(roots) is dict and roots=={
                   'a':inputs['expected_root_a_public_key_sha256'],
                   'b':inputs['expected_root_b_public_key_sha256']} and
               type(rows) is list and len(rows)==2 and
               all(type(r) is dict and set(r)=={'tsa_channel_id','parent_ec355_outcome','outcome'}
                   and r['parent_ec355_outcome'] in EC355_OUTCOMES and r['outcome'] in EC356_OUTCOMES
                   for r in rows) and
               type(counts) is dict and set(counts)==set(EC356_OUTCOMES) and
               all(type(v) is int and 0<=v<=2 for v in counts.values()) and
               sum(counts.values())==2 and
               all(counts[k]==sum(r['outcome']==k for r in rows) for k in counts) and
               doc.get('status')==next(k for k in EC356_OUTCOMES if counts[k])+'_unresolved' and
               type(channels) is list and len(channels)<=2 and
               type(claims) is list and len(claims)<=12 and
               type(doc.get('signed_acknowledgement_count')) is int and
               0<=doc['signed_acknowledgement_count']<=48 and
               type(doc.get('genuine_furnished_parent_receipt_count')) is int and
               0<=doc['genuine_furnished_parent_receipt_count']<=36 and
               all(type(doc.get(k)) is bool for k in (
                   'signed_ack_sha_predecessor_forks_visible',
                   'signed_ack_equivocation_visible','incompatible_signed_original_sha_pairs_visible',
                   'claimed_institution_or_site_identity_collision_visible',
                   'stale_custody_self_claimed_utc_visible',
                   'two_channel_cross_role_exact_original_quorum_for_all_claims')) and
               all(doc.get(k) is False for k in EC356_NEGATIVES))
        channel_fields={'slot','institution_id','channel_id','claimed_organization',
                        'claimed_physical_site_id','root_public_key_original_sha256',
                        'channel_public_key_original_sha256',
                        'root_reference_original_sha256',
                        'channel_authorization_original_sha256'}
        claim_fields={'gossip_reply_original_sha256','log_id',
                      'parent_same_original_observed_by_both_signed_roles',
                      'channel_a_acknowledgements','channel_b_acknowledgements',
                      'two_root_authorized_channels_same_original_different_ec355_roles',
                      'matching_original_pair','incompatible_signed_original_pairs_present'}
        ack_fields={'ack_original_sha256','acknowledgement_id',
                    'previous_ack_original_sha256','nonce_hex','channel_slot','channel_id',
                    'institution_id','gossip_reply_original_sha256','requested_role',
                    'custody_status','acknowledged_utc_as_self_claim',
                    'ec355_request_original_sha256','ec355_receipt_original_sha256',
                    'verified_originals'}
        original_fields={'checkpoint_sha256','witness_sha256','checkpoint_length',
                         'witness_length','ec355_requested_role','ec355_request_original_sha256',
                         'ec355_receipt_original_sha256','relation_to_challenged_parent'}
        if valid:
            valid=(len({x['slot'] for x in channels})==len(channels) and
                   all(type(x) is dict and set(x)==channel_fields and
                       x['slot'] in ('a','b') and
                       x['root_public_key_original_sha256']==roots[x['slot']] and
                       all(sha_ok(x[k]) for k in ('channel_public_key_original_sha256',
                             'root_reference_original_sha256',
                             'channel_authorization_original_sha256'))
                       for x in channels))
        if valid:
            tally=0
            for c in claims:
                if (type(c) is not dict or set(c)!=claim_fields or
                     not sha_ok(c.get('gossip_reply_original_sha256')) or
                     type(c.get('parent_same_original_observed_by_both_signed_roles')) is not bool or
                     type(c.get('two_root_authorized_channels_same_original_different_ec355_roles')) is not bool or
                     type(c.get('incompatible_signed_original_pairs_present')) is not bool):
                    valid=False;break
                for slot in ('a','b'):
                    acklist=c.get('channel_'+slot+'_acknowledgements')
                    if type(acklist) is not list or len(acklist)>2:valid=False;break
                    tally+=len(acklist)
                    for a in acklist:
                        if (type(a) is not dict or set(a)!=ack_fields or
                             a['channel_slot']!=slot or
                             a['gossip_reply_original_sha256']!=c['gossip_reply_original_sha256'] or
                             not sha_ok(a['ack_original_sha256']) or
                             not sha_ok(a['ec355_request_original_sha256']) or
                             not sha_ok(a['ec355_receipt_original_sha256']) or
                             a['custody_status'] not in (
                                 'custodied_originals','sha_claim_only','unavailable_claim') or
                             not utc_ok(a['acknowledged_utc_as_self_claim'])):
                            valid=False;break
                        original=a['verified_originals']
                        if original is None:
                            if a['custody_status']=='custodied_originals':valid=False;break
                        elif (a['custody_status']!='custodied_originals' or
                              type(original) is not dict or set(original)!=original_fields or
                              not sha_ok(original['checkpoint_sha256']) or
                              not sha_ok(original['witness_sha256']) or
                              not all(type(original[k]) is int and 1<=original[k]<=12000
                                  for k in ('checkpoint_length','witness_length'))):
                            valid=False;break
                    if not valid:break
                if not valid:break
            if valid:valid=tally==doc['signed_acknowledgement_count']
        if not valid:_fail('EC356_FIXED_CHILD_REPLY_INVALID_OR_OVERCLAIMS',
                           status='unavailable')
    elif rc in (3,4,5):
        if (type(doc) is not dict or set(doc)!=base|{'reason_code'} or
            doc.get('schema')!='ces.ec356.offline_two_channel_custody_denial.v1' or
            doc.get('command')!='audit-two-channel-custody' or
            doc.get('exit_code')!=rc or STATUS_EXITS.get(doc.get('status'))!=rc or
            doc.get('offline_unresolved_exit_code')!=2 or
            doc.get('actual_ec355_through_ec337_signed_originals_replayed') is not False or
            type(doc.get('reason_code')) is not str or
            re.fullmatch('[A-Z][A-Z0-9_]{2,170}',doc['reason_code']) is None or
            any(doc.get(k) is not False for k in EC356_NEGATIVES)):
            _fail('EC356_FIXED_CHILD_DENIAL_INVALID',status='unavailable')
    else:_fail('EC356_FIXED_CHILD_EXIT_UNEXPECTED',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc


# EC357: fixed isolated read-only offline verification of two caller-pinned
# imported source-signature reviews over EC356 genuinely replayed originals.
# Source key possession + signed declarations NEVER establish external authority,
# legal independence, real physical custody, trusted time or global completeness.
AIRGAP_INSTITUTION_PROVENANCE = ROOT / 'scripts' / 'ces_cas_institution_provenance.py'
