def audit_directory_publication_custody(action:str,mode:str,*,pretty:bool=False,**inputs)->int:
    if (action,mode)!=('DeliveryAudit','AuditDirectoryPublicationCustody'):
        _fail('EC362_ONLY_FIXED_DELIVERYAUDIT_DIRECTORY_PUBLICATION_CUSTODY_READONLY',
              status='permission_denied')
    if (not AIRGAP_DIRECTORY_PUBLICATION_CUSTODY.is_file() or
            AIRGAP_DIRECTORY_PUBLICATION_CUSTODY.is_symlink()):
        _fail('EC362_FIXED_ISOLATED_AUDITOR_UNAVAILABLE',status='unavailable')
    if set(inputs)!=set((*EC362_REQUIRED,*EC362_OPTIONAL,
                         *(k for k,_ in EC362_REPEATS))):
        _fail('EC362_EXACT_PARENT_AND_NEW_ARGUMENT_NAMES_REQUIRED')
    path_ok=lambda x:(type(x) is str and os.path.isabs(x) and
        os.path.normpath(x)==x and not x.startswith('//') and
        '\\' not in x and '\x00' not in x and len(x)<=4000)
    sha_ok=lambda x:(type(x) is str and
        re.fullmatch('[0-9a-f]{64}',x) is not None and x!='0'*64)
    utc_ok=lambda x:(type(x) is str and re.fullmatch(
        r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ',x) is not None)
    for key in EC362_REQUIRED:
        if key.endswith('_evaluation_utc') and not utc_ok(inputs[key]):
            _fail('EC362_PARENT_OR_NEW_EVALUATION_UTC_INVALID')
    for key in EC361_REQUIRED:
        if key.endswith('_evaluation_utc'):continue
        if inputs[key] is None:
            _fail('EC362_PARENT_REQUIRED_VALUE_MISSING')
    for key in EC362_OPTIONAL:
        v=inputs[key]
        if v is None:continue
        if key.endswith('_file') and not path_ok(v):
            _fail('EC362_PINNED_FILE_PATH_INVALID')
        if key.endswith('_sha256') and not sha_ok(v):
            _fail('EC362_SHA_PIN_INVALID')
    for stem in ('source_a_custody_public_key','source_b_custody_public_key',
                 'source_a_publication_manifest','source_b_publication_manifest'):
        pa=inputs.get(stem+'_file')
        digest=inputs.get('expected_'+stem+'_sha256')
        if (pa is None)!=(digest is None):
            _fail('EC362_EXTERNAL_FILE_SHA_PIN_PAIR_REQUIRED')
    for slot in ('a','b'):
        n=inputs['minimum_source_'+slot+'_publication_sequence']
        if n is not None and (type(n) is not int or not 0<=n<=2**31-1):
            _fail('EC362_PUBLICATION_SEQUENCE_FLOOR_INVALID')
    for key in ('minimum_consistent_directory_tree_size',
                'minimum_directory_tree_size'):
        n=inputs[key]
        if n is not None and (type(n) is not int or not 1<=n<=64):
            _fail('EC362_PARENT_DIRECTORY_SIZE_FLOOR_INVALID')
    for key,flag in EC362_REPEATS:
        v=inputs[key]
        if type(v) is not list or len(v)>32 or any(type(x) is not str for x in v):
            _fail('EC362_PARENT_REPEATS_INVALID')
        if key.endswith('_files') and any(not path_ok(x) for x in v):
            _fail('EC362_PARENT_REPEATED_PATH_INVALID')
        if key.endswith('_shas') and any(not sha_ok(x) for x in v):
            _fail('EC362_PARENT_REPEATED_SHA_INVALID')
    # A signer may not serve both source roles, or borrow a previous known role.
    new_shas=[inputs['expected_source_'+slot+'_custody_public_key_sha256']
              for slot in ('a','b') if inputs[
                'expected_source_'+slot+'_custody_public_key_sha256'] is not None]
    old_shas={inputs[k] for k in EC361_OPTIONAL
              if k.endswith('_public_key_sha256') and inputs[k] is not None}
    if len(new_shas)!=len(set(new_shas)) or any(s in old_shas for s in new_shas):
        _fail('EC362_SOURCE_SIGNER_ROLE_COLLISION',status='permission_denied')
    args=[sys.executable,'-I','-B',str(AIRGAP_DIRECTORY_PUBLICATION_CUSTODY),
          'audit-directory-publication-custody']
    for key in EC362_REQUIRED:
        args.extend(['--'+key.replace('_','-'),str(inputs[key])])
    for key in EC362_OPTIONAL:
        if inputs[key] is not None:
            args.extend(['--'+key.replace('_','-'),str(inputs[key])])
    for key,flag in EC362_REPEATS:
        for v in inputs[key]:args.extend([flag,str(v)])
    rc,doc=_command(args,timeout=7200,max_output=1000000)
    base={'schema','command','status','exit_code','offline_unresolved_exit_code',
          'actual_ec361_through_ec337_signed_originals_replayed',*EC362_NEGATIVES}
    if rc==2:
        extras={'case_id','parent_ec361_canonical_result_sha256',
          'parent_ec360_canonical_result_sha256',
          'parent_selected_checkpoint_original_sha256',
          'parent_consistency_bundle_original_sha256',
          'publication_copy_evaluation_utc_as_caller_claim',
          'signed_publication_source_reviews','signed_source_count',
          'ec361_parent_locally_coherent',
          'external_sources_or_copy_pins_missing',
          'publication_source_identity_or_role_collision',
          'original_copies_or_caller_sha_pins_mismatch',
          'independently_presented_signed_checkpoint_conflict',
          'caller_publication_floor_or_newer_head_rollback',
          'source_signed_utc_claim_stale_or_future',
          'both_distinct_custodian_signatures_verified_locally',
          'each_four_original_copies_exactly_agree_with_parent',
          'two_offline_signed_publication_copies_locally_coherent',
          'public_custody_official_dissemination_and_global_latest_unproven',
          'channel_evidence','outcome_counts'}
        flags=('ec361_parent_locally_coherent',
          'external_sources_or_copy_pins_missing',
          'publication_source_identity_or_role_collision',
          'original_copies_or_caller_sha_pins_mismatch',
          'independently_presented_signed_checkpoint_conflict',
          'caller_publication_floor_or_newer_head_rollback',
          'source_signed_utc_claim_stale_or_future',
          'both_distinct_custodian_signatures_verified_locally',
          'each_four_original_copies_exactly_agree_with_parent',
          'two_offline_signed_publication_copies_locally_coherent')
        row_fields={'slot','claimed_source_id_unverified',
          'custodian_public_key_sha256','signed_manifest_original_sha256',
          'manifest_sequence_as_signed_claim','minimum_sequence_as_caller_pin',
          'advertised_checkpoint_sha256','advertised_tree_size_as_signed_claim',
          'advertised_root_sha256_as_signed_claim',
          'copies_exactly_match_parent_original_sha',
          'all_four_copy_shas_separately_caller_pinned','signed_clock_anomaly'}
        reviews=doc.get('signed_publication_source_reviews') if type(doc) is dict else None
        ch=doc.get('channel_evidence') if type(doc) is dict else None
        counts=doc.get('outcome_counts') if type(doc) is dict else None
        good=(type(doc) is dict and set(doc)==base|extras and
          doc.get('schema')=='ces.ec362.offline_directory_publication_custody_unresolved.v1' and
          doc.get('command')=='audit-directory-publication-custody' and
          doc.get('exit_code')==2 and doc.get('offline_unresolved_exit_code')==2 and
          doc.get('actual_ec361_through_ec337_signed_originals_replayed') is True and
          doc.get('public_custody_official_dissemination_and_global_latest_unproven') is True and
          sha_ok(doc.get('parent_ec361_canonical_result_sha256')) and
          sha_ok(doc.get('parent_ec360_canonical_result_sha256')) and
          doc.get('parent_selected_checkpoint_original_sha256')==
              inputs['expected_latest_consistent_directory_checkpoint_sha256'] and
          doc.get('parent_consistency_bundle_original_sha256')==
              inputs['expected_consistency_bundle_sha256'] and
          doc.get('publication_copy_evaluation_utc_as_caller_claim')==
              inputs['publication_copy_evaluation_utc'] and
          all(type(doc.get(k)) is bool for k in flags) and
          type(doc.get('signed_source_count')) is int and
          0<=doc['signed_source_count']<=2 and
          type(reviews) is list and len(reviews)==doc['signed_source_count'] and
          len({r.get('slot') for r in reviews if type(r) is dict})==len(reviews) and
          all(type(r) is dict and set(r)==row_fields and
              r['slot'] in ('a','b') and
              type(r['claimed_source_id_unverified']) is str and
              all(sha_ok(r[k]) for k in (
                    'custodian_public_key_sha256','signed_manifest_original_sha256',
                    'advertised_checkpoint_sha256','advertised_root_sha256_as_signed_claim')) and
              r['custodian_public_key_sha256']==inputs[
                  'expected_source_'+r['slot']+'_custody_public_key_sha256'] and
              r['signed_manifest_original_sha256']==inputs[
                  'expected_source_'+r['slot']+'_publication_manifest_sha256'] and
              type(r['manifest_sequence_as_signed_claim']) is int and
              0<=r['manifest_sequence_as_signed_claim']<=2**31-1 and
              r['minimum_sequence_as_caller_pin']==inputs[
                  'minimum_source_'+r['slot']+'_publication_sequence'] and
              type(r['advertised_tree_size_as_signed_claim']) is int and
              1<=r['advertised_tree_size_as_signed_claim']<=64 and
              type(r['copies_exactly_match_parent_original_sha']) is dict and
              set(r['copies_exactly_match_parent_original_sha'])=={
                  'checkpoint','consistency_bundle','observer_a_receipt','observer_b_receipt'} and
              all(type(x) is bool for x in r['copies_exactly_match_parent_original_sha'].values()) and
              type(r['all_four_copy_shas_separately_caller_pinned']) is bool and
              type(r['signed_clock_anomaly']) is bool for r in reviews) and
          type(ch) is list and len(ch)==2 and
          all(type(r) is dict and set(r)=={
              'tsa_channel_id','parent_ec361_outcome','outcome'} and
              r['parent_ec361_outcome'] in EC361_OUTCOMES and
              r['outcome'] in EC362_OUTCOMES for r in ch) and
          type(counts) is dict and set(counts)==set(EC362_OUTCOMES) and
          all(type(v) is int and 0<=v<=2 for v in counts.values()) and
          sum(counts.values())==2 and
          all(counts[k]==sum(r['outcome']==k for r in ch) for k in counts) and
          doc.get('status')==next((k for k in EC362_OUTCOMES if counts[k]),None)+'_unresolved' and
          all(doc.get(k) is False for k in EC362_NEGATIVES))
        if good and doc['both_distinct_custodian_signatures_verified_locally']:
            good=(len(reviews)==2 and len({r['custodian_public_key_sha256']
                                         for r in reviews})==2)
        if good and doc['each_four_original_copies_exactly_agree_with_parent']:
            good=(len(reviews)==2 and all(
                all(r['copies_exactly_match_parent_original_sha'].values()) for r in reviews))
        if good and doc['two_offline_signed_publication_copies_locally_coherent']:
            good=(doc['ec361_parent_locally_coherent'] and
                doc['both_distinct_custodian_signatures_verified_locally'] and
                doc['each_four_original_copies_exactly_agree_with_parent'] and
                len(reviews)==2 and all(r['all_four_copy_shas_separately_caller_pinned']
                                        for r in reviews) and
                not any(doc[k] for k in flags[1:7]) and
                counts[EC362_OUTCOMES[-1]]==2)
        if good and counts[EC362_OUTCOMES[-1]]:
            good=doc['two_offline_signed_publication_copies_locally_coherent']
        if not good:_fail('EC362_CHILD_REPLY_SCHEMA_OR_UNJUSTIFIED_SUCCESS_REJECTED',
                          status='unavailable')
    elif rc in (3,4,5):
        good=(type(doc) is dict and set(doc)==base|{'reason_code'} and
          doc.get('schema')=='ces.ec362.offline_directory_publication_custody_denial.v1' and
          doc.get('command')=='audit-directory-publication-custody' and
          doc.get('exit_code')==rc and STATUS_EXITS.get(doc.get('status'))==rc and
          doc.get('actual_ec361_through_ec337_signed_originals_replayed') is False and
          doc.get('offline_unresolved_exit_code')==2 and
          type(doc.get('reason_code')) is str and
          re.fullmatch('[A-Z][A-Z0-9_]{2,170}',doc['reason_code']) is not None and
          all(doc.get(k) is False for k in EC362_NEGATIVES))
        if not good:_fail('EC362_FIXED_CHILD_DENIAL_INVALID',status='unavailable')
    else:
        _fail('EC362_FIXED_CHILD_EXIT_CODE_UNEXPECTED',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc


