def audit_directory_authority(action:str,mode:str,*,pretty:bool=False,**inputs)->int:
    if (action,mode)!=('DeliveryAudit','AuditDirectoryAuthority'):
        _fail('EC365_ONLY_FIXED_DELIVERYAUDIT_AUDITDIRECTORYAUTHORITY_READONLY',
              status='permission_denied')
    if (not AIRGAP_DIRECTORY_AUTHORITY.is_file() or
        AIRGAP_DIRECTORY_AUTHORITY.is_symlink()):
        _fail('EC365_FIXED_ISOLATED_DIRECTORY_AUDITOR_UNAVAILABLE',
              status='unavailable')
    if set(inputs)!=set((*EC365_REQUIRED,*EC365_OPTIONAL,
                         *(k for k,_ in EC365_REPEATS))):
        _fail('EC365_EXACT_PARENT_AND_NEW_INPUT_KEYS_REQUIRED')
    path_ok=lambda v:(type(v) is str and os.path.isabs(v) and
        os.path.normpath(v)==v and not v.startswith('//') and
        '\\' not in v and '\x00' not in v and len(v)<=4000)
    sha_ok=lambda v:(type(v) is str and
        re.fullmatch('[0-9a-f]{64}',v) is not None and v!='0'*64)
    utc_ok=lambda v:(type(v) is str and re.fullmatch(
        r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ',v) is not None)
    for k in EC365_REQUIRED:
        v=inputs[k]
        if v is None:_fail('EC365_REQUIRED_TRUE_PARENT_OR_EVALUATION_FIELD_MISSING')
        if k.endswith('_evaluation_utc') and not utc_ok(v):
            _fail('EC365_EVALUATION_UTC_FORMAT_INVALID')
    for k in EC365_OPTIONAL:
        v=inputs[k]
        if v is None:continue
        if k.endswith('_file') and not path_ok(v):
            _fail('EC365_ORIGINAL_ABSOLUTE_PATH_REQUIRED')
        if k.endswith('_sha256') and not sha_ok(v):
            _fail('EC365_EXTERNAL_SHA_PIN_INVALID')
        if k.startswith('minimum_'):
            if k=='minimum_retained_historical_epoch_count':lower,cap=1,2
            elif k=='minimum_retained_directory_root_generation':lower,cap=1,2
            elif 'tree_size' in k:lower,cap=1,64
            else:lower,cap=0,2**31-1
            if type(v) is not int or not lower<=v<=cap:
                _fail('EC365_RETAINED_FLOOR_INVALID')
    for stem in ('directory_authority_bundle','cross_epoch_bundle'):
        if (inputs.get(stem+'_file') is None)!=(inputs.get('expected_'+stem+'_sha256') is None):
            _fail('EC365_ORIGINAL_FILE_AND_CALLER_SHA_PAIR_REQUIRED')
    for k,flag in EC365_REPEATS:
        values=inputs[k]
        if (k,flag) in EC365_NEW_REPEATS:
            limit=5 if k=='signed_directory_handoff_shas' else 3
        elif (k,flag) in EC364_NEW_REPEATS:
            limit=2 if k=='historical_ec362_snapshot_shas' else 8
        else:
            limit=32 if (k,flag) in EC362_REPEATS else (
                4 if 'historical_manifest' in k else 16)
        if type(values) is not list or len(values)>limit or any(
            type(v) is not str for v in values):
            _fail('EC365_REPEAT_BOUNDS_INVALID')
        if k.endswith('_shas') and (any(not sha_ok(v) for v in values) or
            (k=='signed_directory_handoff_shas' and len(set(values))!=len(values))):
            _fail('EC365_EXTERNAL_REPEAT_HASH_INVALID')
        if k.endswith('_files') and any(not path_ok(v) for v in values):
            _fail('EC365_INHERITED_REPEAT_PATH_INVALID')
    argv=[sys.executable,'-I','-B',str(AIRGAP_DIRECTORY_AUTHORITY),
          'audit-directory-authority']
    for k in EC365_REQUIRED:argv.extend(['--'+k.replace('_','-'),str(inputs[k])])
    for k in EC365_OPTIONAL:
        if inputs[k] is not None:argv.extend(['--'+k.replace('_','-'),str(inputs[k])])
    for k,flag in EC365_REPEATS:
        for v in inputs[k]:argv.extend([flag,str(v)])
    rc,doc=_command(argv,timeout=7200,max_output=1000000)
    base={'schema','command','status','exit_code','offline_unresolved_exit_code',
          'actual_ec364_through_ec337_signed_originals_replayed',*EC365_NEGATIVES}
    if rc==2:
        extra={'case_id','parent_ec364_canonical_result_sha256',
          'parent_ec364_locally_coherent',
          'directory_lineage_evaluation_utc_as_caller_claim',
          'directory_authority_bundle_original_sha256',
          'caller_minimum_retained_root_generation',
          'caller_minimum_retained_latest_tree_size',
          'true_directory_root_generation','retained_initial_root_sha256',
          'retained_current_root_sha256','epoch_lineage_reviews',
          'signed_directory_handoff_reviews',
          'true_signed_directory_handoff_originals_verified',
          'actual_cross_root_rfc6962_proofs_verified',*EC365_FLAGS,
          'locally_authorized_directory_signer_transition',
          'official_identity_legal_independence_physical_custody_trusted_utc_and_global_head_unproven',
          'channel_evidence','outcome_counts'}
        epoch_keys={'epoch_index','actual_directory_key_original_sha256',
          'signed_checkpoint_original_sha256','signed_tree_size',
          'signed_merkle_root_sha256','signed_claimed_directory_id',
          'true_parent_ec361_canonical_result_sha256',
          'source_a_manifest_original_sha256','source_b_manifest_original_sha256'}
        event_keys={'from_epoch_index','to_epoch_index',
          'handoff_original_sha256','event_kind','from_root_sha256',
          'to_root_sha256','from_root_generation','to_root_generation',
          'true_old_and_new_directory_signatures_verified',
          'signed_kind_and_generation_match_actual_replay',
          'signed_claimed_clock_anomaly'}
        e=doc.get('epoch_lineage_reviews') if type(doc) is dict else None
        h=doc.get('signed_directory_handoff_reviews') if type(doc) is dict else None
        channels=doc.get('channel_evidence') if type(doc) is dict else None
        counts=doc.get('outcome_counts') if type(doc) is dict else None
        good=(type(doc) is dict and set(doc)==base|extra and
          doc.get('schema')=='ces.ec365.offline_directory_authority_lineage_unresolved.v1' and
          doc.get('command')=='audit-directory-authority' and
          doc.get('exit_code')==2 and doc.get('offline_unresolved_exit_code')==2 and
          doc.get('actual_ec364_through_ec337_signed_originals_replayed') is True and
          doc.get('directory_lineage_evaluation_utc_as_caller_claim')==
            inputs['directory_lineage_evaluation_utc'] and
          sha_ok(doc.get('parent_ec364_canonical_result_sha256')) and
          doc.get('directory_authority_bundle_original_sha256')==
            inputs.get('expected_directory_authority_bundle_sha256') and
          type(doc.get('parent_ec364_locally_coherent')) is bool and
          type(doc.get('case_id')) is str and
          type(e) is list and 1<=len(e)<=3 and
          all(type(row) is dict and set(row)==epoch_keys and
            row['epoch_index']==i and
            all(sha_ok(row[k]) for k in epoch_keys if k.endswith('sha256')) and
            type(row['signed_tree_size']) is int and
            1<=row['signed_tree_size']<=64 and
            type(row['signed_claimed_directory_id']) is str and
            row['signed_claimed_directory_id'] for i,row in enumerate(e)) and
          type(h) is list and len(h)<=5 and
          all(type(row) is dict and set(row)==event_keys and
            type(row['from_epoch_index']) is int and
            0<=row['from_epoch_index']<len(e)-1 and
            row['to_epoch_index']==row['from_epoch_index']+1 and
            row['event_kind'] in ('carry','delegate_and_retire','terminal_retirement') and
            all(sha_ok(row[k]) for k in ('handoff_original_sha256',
                       'from_root_sha256','to_root_sha256')) and
            row['true_old_and_new_directory_signatures_verified'] is True and
            type(row['signed_kind_and_generation_match_actual_replay']) is bool and
            type(row['signed_claimed_clock_anomaly']) is bool for row in h) and
          type(doc.get('true_directory_root_generation')) is int and
          doc['true_directory_root_generation']==sum(
            e[i]['actual_directory_key_original_sha256']!=
            e[i+1]['actual_directory_key_original_sha256']
            for i in range(len(e)-1)) and
          type(doc.get('true_signed_directory_handoff_originals_verified')) is int and
          doc['true_signed_directory_handoff_originals_verified']==len(h) and
          type(doc.get('actual_cross_root_rfc6962_proofs_verified')) is int and
          0<=doc['actual_cross_root_rfc6962_proofs_verified']<=len(e)-1 and
          all(type(doc.get(k)) is bool for k in EC365_FLAGS) and
          type(doc.get('locally_authorized_directory_signer_transition')) is bool and
          doc.get('official_identity_legal_independence_physical_custody_trusted_utc_and_global_head_unproven') is True and
          type(channels) is list and len(channels)==2 and
          all(type(row) is dict and set(row)=={
               'tsa_channel_id','parent_ec364_outcome','outcome'} and
            row.get('parent_ec364_outcome') in EC364_OUTCOMES and
            row.get('outcome') in EC365_OUTCOMES for row in channels) and
          type(counts) is dict and set(counts)==set(EC365_OUTCOMES) and
          all(type(v) is int and 0<=v<=2 for v in counts.values()) and
          sum(counts.values())==2 and
          all(counts[o]==sum(row['outcome']==o for row in channels)
              for o in EC365_OUTCOMES) and
          doc.get('status')==next((o for o in EC365_OUTCOMES
              if counts[o]),None)+'_unresolved' and
          all(doc.get(k) is False for k in EC365_NEGATIVES))
        if good:
            good=(doc['retained_initial_root_sha256']==inputs.get(
                    'expected_retained_initial_directory_root_sha256') and
                  doc['retained_current_root_sha256']==inputs.get(
                    'expected_retained_current_directory_root_sha256') and
                  doc['caller_minimum_retained_root_generation']==inputs.get(
                    'minimum_retained_directory_root_generation') and
                  doc['caller_minimum_retained_latest_tree_size']==inputs.get(
                    'minimum_retained_latest_directory_tree_size') and
                  all(row['from_root_sha256']==e[row['from_epoch_index']][
                    'actual_directory_key_original_sha256'] and
                    row['to_root_sha256']==e[row['to_epoch_index']][
                    'actual_directory_key_original_sha256'] for row in h))
        if good and doc['locally_authorized_directory_signer_transition']:
            good=(len(e)>=2 and doc['true_directory_root_generation']>=1 and
                  doc['true_signed_directory_handoff_originals_verified']==len(e)-1 and
                  doc['actual_cross_root_rfc6962_proofs_verified']==len(e)-1 and
                  not any(doc[k] for k in EC365_FLAGS) and
                  counts[EC365_OUTCOMES[-1]]==2)
        if good and counts[EC365_OUTCOMES[-1]]:
            good=doc['locally_authorized_directory_signer_transition']
        if not good:
            _fail('EC365_FIXED_CHILD_REPLY_SHAPE_OR_UNJUSTIFIED_AUTHORIZATION',
                  status='unavailable')
    elif rc in (3,4,5):
        good=(type(doc) is dict and set(doc)==base|{'reason_code'} and
          doc.get('schema')=='ces.ec365.offline_directory_authority_lineage_denial.v1' and
          doc.get('command')=='audit-directory-authority' and
          doc.get('exit_code')==rc and STATUS_EXITS.get(doc.get('status'))==rc and
          doc.get('actual_ec364_through_ec337_signed_originals_replayed') is False and
          doc.get('offline_unresolved_exit_code')==2 and
          type(doc.get('reason_code')) is str and
          re.fullmatch('[A-Z][A-Z0-9_]{2,170}',doc['reason_code']) is not None and
          all(doc.get(k) is False for k in EC365_NEGATIVES))
        if not good:_fail('EC365_FIXED_CHILD_DENIAL_INVALID',status='unavailable')
    else:_fail('EC365_FIXED_CHILD_EXIT_CODE_UNEXPECTED',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc


