def audit_detached_receiver(action:str,mode:str,*,pretty:bool=False,**inputs)->int:
    if (action,mode)!=('DeliveryAudit','AuditDetachedReceiver'):
        _fail('EC369_ONLY_DELIVERYAUDIT_AUDITDETACHEDRECEIVER_READONLY',
              status='permission_denied')
    if not AIRGAP_DETACHED_RECEIVER.is_file() or AIRGAP_DETACHED_RECEIVER.is_symlink():
        _fail('EC369_FIXED_CHILD_NOT_AVAILABLE',status='unavailable')
    if set(inputs)!=set(EC369_SCALARS)|{k for k,_ in EC369_REPEATS}:
        _fail('EC369_DETACHED_EXACT_INPUT_FIELDS_REQUIRED')
    path_ok=lambda v:(type(v) is str and os.path.isabs(v) and
        os.path.normpath(v)==v and len(v)<=4000 and not v.startswith('//') and
        '\\' not in v and '\x00' not in v)
    sha_ok=lambda v:(type(v) is str and re.fullmatch('[0-9a-f]{64}',v) is not None
        and v!='0'*64)
    id_ok=lambda v:(type(v) is str and re.fullmatch(
        '[A-Za-z][A-Za-z0-9_.:-]{0,95}',v) is not None)
    for k in EC369_SCALARS:
        v=inputs[k]
        if k.endswith('_utc'):
            if type(v) is not str or re.fullmatch(
                r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ',v) is None:
                _fail('EC369_FIXED_STRICT_UTC_REQUIRED')
        elif k.endswith('_file'):
            if not path_ok(v):_fail('EC369_FIXED_ABSOLUTE_COPY_PATH_REQUIRED')
        elif k.endswith('_sha256'):
            if not sha_ok(v):_fail('EC369_FIXED_INDEPENDENT_SHA_PIN_REQUIRED')
        elif k.startswith('minimum_'):
            if type(v) is not int or not 0<=v<=3:_fail('EC369_FIXED_SEQUENCE_FLOOR_BOUNDS')
        elif k in ('claimed_sender_id','claimed_receiver_id'):
            if not id_ok(v):_fail('EC369_FIXED_IDENTITY_FORMAT_REQUIRED')
    if (inputs['claimed_sender_id']==inputs['claimed_receiver_id'] or
        inputs['expected_sender_public_key_sha256']==
             inputs['expected_receiver_public_key_sha256']):
        _fail('EC369_FIXED_DISTINCT_SENDER_RECEIVER_REQUIRED',status='permission_denied')
    for key,flag in EC369_REPEATS:
        rows=inputs[key]
        cap=2 if key in ('institution_root_public_key_shas','witness_public_key_shas',
            'institution_claimed_ids','witness_claimed_ids',
            'expected_source_status_head_shas','expected_source_attestation_head_shas',
            'expected_witness_head_shas') else 4
        if type(rows) is not list:
            _fail('EC369_FIXED_BOUNDED_SIGNED_STREAM_OR_DUAL_ROLE_REQUIRED')
        if (cap==2 and len(rows)!=2) or (cap!=2 and not 1<=len(rows)<=cap):
            _fail('EC369_FIXED_BOUNDED_SIGNED_STREAM_OR_DUAL_ROLE_REQUIRED')
        if key.endswith('_ids'):
            if any(not id_ok(x) for x in rows) or len(set(rows))!=2:
                _fail('EC369_FIXED_DUAL_CLAIMED_IDS_INVALID')
        else:
            if any(x is not None and not sha_ok(x) for x in rows) or (
                key!='expected_source_attestation_head_shas' and any(x is None for x in rows)):
                _fail('EC369_FIXED_EXTERNAL_SHA_STREAM_INVALID')
            if key in ('institution_root_public_key_shas','witness_public_key_shas') and len(set(rows))!=2:
                _fail('EC369_FIXED_DISTINCT_SOURCE_OR_WITNESS_KEYS_REQUIRED')
            if key.startswith('signed_') and len(set(rows))!=len(rows):
                _fail('EC369_FIXED_SIGNED_ORIGINAL_SHA_STREAM_DUPLICATED')
    if (len(inputs['signed_sender_dispatch_shas'])!=len(inputs['signed_receiver_ack_shas']) or
        len(inputs['signed_challenge_shas'])!=len(inputs['signed_answer_shas'])):
        _fail('EC369_FIXED_PAIR_COUNTS_MUST_MATCH')
    argv=[sys.executable,'-I','-B',str(AIRGAP_DETACHED_RECEIVER),'audit-detached-receiver']
    for k in EC369_SCALARS:argv.extend(['--'+k.replace('_','-'),str(inputs[k])])
    for k,flag in EC369_REPEATS:
        for x in inputs[k]:argv.extend([flag,'none' if x is None else str(x)])
    rc,doc=_command(argv,timeout=180,max_output=100000)
    base={'schema','command','status','exit_code','offline_unresolved_exit_code',
          'original_sender_source_paths_required_or_read',
          'ec365_through_ec337_historical_parent_or_directory_checkpoint_replay_performed',
          *EC369_NEGATIVES}
    if rc==2:
        fields={
          'detached_evaluation_utc_as_caller_claim','signed_copy_map_original_sha256',
          'detached_bundle_original_sha256',
          'parent_ec367_canonical_result_sha256_as_external_pin',
          'actual_portable_inventory_canonical_sha256',
          'actual_copied_source_original_count',
          'true_copied_institution_status_ed25519_signature_count',
          'true_copied_institution_provenance_ed25519_signature_count',
          'true_copied_witness_ed25519_signature_count',
          'true_copied_sender_dispatch_ed25519_signature_count',
          'true_copied_receiver_ack_ed25519_signature_count',
          'true_disclosure_challenge_ed25519_signature_count',
          'true_disclosure_answer_ed25519_signature_count',
          'verified_copy_source_terminal_status_original_shas',
          'actual_source_status_head_shas','actual_source_attestation_head_shas',
          'actual_witness_head_shas',
          'actual_sender_dispatch_head_sha256','actual_receiver_ack_head_sha256',
          'latest_receiver_signed_receipt_state',
          'actual_disclosure_challenge_head_sha256',
          'actual_disclosure_answer_head_sha256',
          'locally_detached_signed_copy_inventory_and_dual_receipt_consistent',
          *EC369_FLAGS}
        count_fields=[k for k in fields if k.endswith('_count')]
        signed_status=doc.get('verified_copy_source_terminal_status_original_shas')
        heads=('actual_source_status_head_shas','actual_source_attestation_head_shas',
               'actual_witness_head_shas')
        good=(type(doc) is dict and set(doc)==base|fields and
          doc.get('schema')=='ces.ec369.detached_receiver_signed_original_replay_unresolved.v1' and
          doc.get('command')=='audit-detached-receiver' and doc.get('exit_code')==2 and
          doc.get('offline_unresolved_exit_code')==2 and
          type(doc.get('status')) is str and
          doc.get('original_sender_source_paths_required_or_read') is False and
          doc.get('ec365_through_ec337_historical_parent_or_directory_checkpoint_replay_performed') is False and
          all(doc.get(n) is False for n in EC369_NEGATIVES) and
          all(type(doc.get(n)) is bool for n in EC369_FLAGS) and
          type(doc.get('locally_detached_signed_copy_inventory_and_dual_receipt_consistent')) is bool and
          all(type(doc.get(k)) is int and 0<=doc[k]<=52 for k in count_fields) and
          doc.get('detached_evaluation_utc_as_caller_claim')==inputs['detached_evaluation_utc'] and
          doc.get('detached_bundle_original_sha256')==inputs['expected_detached_bundle_sha256'] and
          doc.get('signed_copy_map_original_sha256')==inputs['expected_signed_copy_map_sha256'] and
          doc.get('parent_ec367_canonical_result_sha256_as_external_pin')==
             inputs['expected_parent_ec367_canonical_result_sha256'] and
          sha_ok(doc.get('actual_portable_inventory_canonical_sha256')) and
          type(signed_status) is list and len(signed_status)<=12 and
          all(sha_ok(x) for x in signed_status) and len(signed_status)==len(set(signed_status)) and
          all(type(doc.get(k)) is list and len(doc[k])==2 and
              all(x is None or sha_ok(x) for x in doc[k]) for k in heads) and
          all(doc.get(k) is None or sha_ok(doc[k]) for k in (
              'actual_sender_dispatch_head_sha256','actual_receiver_ack_head_sha256',
              'actual_disclosure_challenge_head_sha256','actual_disclosure_answer_head_sha256')) and
          doc.get('latest_receiver_signed_receipt_state') in (
              None,'accepted','withheld','disputed') and
          doc.get('true_copied_sender_dispatch_ed25519_signature_count')==
             doc.get('true_copied_receiver_ack_ed25519_signature_count') and
          doc.get('true_disclosure_challenge_ed25519_signature_count')==
             doc.get('true_disclosure_answer_ed25519_signature_count') and
          doc.get('status')==next((EC369_OUTCOMES[i] for i,k in enumerate(EC369_FLAGS)
                                    if doc[k]),EC369_OUTCOMES[-1])+'_unresolved')
        if good and doc['locally_detached_signed_copy_inventory_and_dual_receipt_consistent']:
            good=(not any(doc[x] for x in EC369_FLAGS) and
              doc['actual_portable_inventory_canonical_sha256']==inputs[
                  'expected_portable_inventory_sha256'] and
              doc['actual_sender_dispatch_head_sha256']==inputs[
                  'expected_retained_sender_dispatch_head_sha256'] and
              doc['actual_receiver_ack_head_sha256']==inputs[
                  'expected_retained_receiver_ack_head_sha256'] and
              doc['actual_disclosure_challenge_head_sha256']==inputs[
                  'expected_retained_challenge_head_sha256'] and
              doc['actual_disclosure_answer_head_sha256']==inputs[
                  'expected_retained_answer_head_sha256'] and
              doc['latest_receiver_signed_receipt_state']=='accepted' and
              doc['actual_source_status_head_shas']==inputs[
                  'expected_source_status_head_shas'] and
              doc['actual_source_attestation_head_shas']==inputs[
                  'expected_source_attestation_head_shas'] and
              doc['actual_witness_head_shas']==inputs['expected_witness_head_shas'])
        if not good:_fail('EC369_FIXED_CHILD_REPLY_INVALID_OR_OVERCLAIMS',status='unavailable')
    elif rc in (3,4,5):
        good=(type(doc) is dict and set(doc)==base|{'reason_code'} and
          doc.get('schema')=='ces.ec369.detached_receiver_signed_original_replay_denial.v1' and
          doc.get('command')=='audit-detached-receiver' and doc.get('exit_code')==rc and
          STATUS_EXITS.get(doc.get('status'))==rc and
          doc.get('original_sender_source_paths_required_or_read') is False and
          doc.get('ec365_through_ec337_historical_parent_or_directory_checkpoint_replay_performed') is False and
          doc.get('offline_unresolved_exit_code')==2 and
          type(doc.get('reason_code')) is str and
          re.fullmatch('[A-Z][A-Z0-9_]{2,170}',doc['reason_code']) is not None and
          all(doc.get(n) is False for n in EC369_NEGATIVES))
        if not good:_fail('EC369_FIXED_CHILD_DENIAL_INVALID',status='unavailable')
    else:_fail('EC369_FIXED_CHILD_EXIT_CODE_UNEXPECTED',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc

