def audit_publication_accountability(action:str,mode:str,*,pretty:bool=False,**inputs)->int:
    if (action,mode)!=('DeliveryAudit','AuditPublicationAccountability'):
        _fail('EC370_ONLY_DELIVERYAUDIT_AUDITPUBLICATIONACCOUNTABILITY_READONLY',
              status='permission_denied')
    if (not AIRGAP_PUBLICATION_ACCOUNTABILITY.is_file() or
            AIRGAP_PUBLICATION_ACCOUNTABILITY.is_symlink()):
        _fail('EC370_FIXED_CHILD_NOT_AVAILABLE',status='unavailable')
    all_scalars=(*EC369_SCALARS,*EC370_NEW_SCALARS)
    all_repeats=(*EC369_REPEATS,*EC370_NEW_REPEATS)
    if set(inputs)!=set(all_scalars)|{k for k,_ in all_repeats}:
        _fail('EC370_FIXED_EXACT_PARENT_AND_PUBLICATION_ARGUMENTS_REQUIRED')
    sha_ok=lambda s:(type(s) is str and
                     re.fullmatch('[0-9a-f]{64}',s) is not None and s!='0'*64)
    path_ok=lambda s:(type(s) is str and os.path.isabs(s) and
                      os.path.normpath(s)==s and len(s)<=4000 and
                      not s.startswith('//') and '\\' not in s and '\x00' not in s)
    id_ok=lambda s:(type(s) is str and
                    re.fullmatch('[A-Za-z][A-Za-z0-9_.:-]{0,95}',s) is not None)
    for k in all_scalars:
        v=inputs[k]
        if k.endswith('_utc'):
            if type(v) is not str or re.fullmatch(
                r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ',v) is None:
                _fail('EC370_FIXED_STRICT_EVALUATION_UTC_REQUIRED')
        elif k.endswith('_file'):
            if not path_ok(v):_fail('EC370_FIXED_PINNED_ABSOLUTE_FILE_REQUIRED')
        elif k.endswith('_sha256'):
            if not sha_ok(v):_fail('EC370_FIXED_OUTSIDE_SHA_PIN_REQUIRED')
        elif k.startswith('minimum_'):
            cap=4 if k=='minimum_retained_published_challenge_count' else 3
            if type(v) is not int or not 0<=v<=cap:
                _fail('EC370_FIXED_BOUNDED_SEQUENCE_AND_COUNT_FLOOR_REQUIRED')
        elif k.startswith('claimed_'):
            if not id_ok(v):_fail('EC370_FIXED_STRICT_SIGNER_ID_REQUIRED')
    roles=[inputs['claimed_sender_id'],inputs['claimed_receiver_id'],
           inputs['claimed_publisher_id'],inputs['claimed_publication_observer_id'],
           *inputs['institution_claimed_ids'],*inputs['witness_claimed_ids']]
    roots=[inputs['expected_sender_public_key_sha256'],
           inputs['expected_receiver_public_key_sha256'],
           inputs['expected_publisher_public_key_sha256'],
           inputs['expected_publication_observer_public_key_sha256'],
           *inputs['institution_root_public_key_shas'],
           *inputs['witness_public_key_shas']]
    if any(not id_ok(v) for v in roles) or len(set(roles))!=len(roles) or (
            any(not sha_ok(v) for v in roots) or len(set(roots))!=len(roots)):
        _fail('EC370_FIXED_EIGHT_DISTINCT_SIGNER_ROOTS_REQUIRED',
              status='permission_denied')
    for k,flag in all_repeats:
        arr=inputs[k]
        small=k in ('institution_root_public_key_shas','witness_public_key_shas',
                    'institution_claimed_ids','witness_claimed_ids',
                    'expected_source_status_head_shas',
                    'expected_source_attestation_head_shas','expected_witness_head_shas')
        if type(arr) is not list or not (len(arr)==2 if small else 1<=len(arr)<=4):
            _fail('EC370_FIXED_BOUNDED_OUTSIDE_SHA_STREAM_REQUIRED')
        if k.endswith('_ids'):
            if any(not id_ok(v) for v in arr) or len(set(arr))!=2:
                _fail('EC370_FIXED_DUAL_EXTERNAL_IDENTIFIERS_REQUIRED')
        else:
            if any(not sha_ok(v) and not (
                v is None and k=='expected_source_attestation_head_shas') for v in arr):
                _fail('EC370_FIXED_STRICT_ORIGINAL_SHA_PIN_REQUIRED')
            if (k.startswith('signed_') or 'public_key' in k) and len(set(arr))!=len(arr):
                _fail('EC370_FIXED_SIGNED_STREAM_DUPLICATE_SHA_DENIED')
    if (len(inputs['signed_publisher_notice_shas'])!=len(
            inputs['signed_publication_observer_shas']) or
        len(inputs['signed_sender_dispatch_shas'])!=len(
            inputs['signed_receiver_ack_shas']) or
        len(inputs['signed_challenge_shas'])!=len(inputs['signed_answer_shas'])):
        _fail('EC370_FIXED_DUAL_SIGNED_STREAM_COUNTS_REQUIRED')
    argv=[sys.executable,'-I','-B',str(AIRGAP_PUBLICATION_ACCOUNTABILITY),
          'audit-publication-accountability']
    for k in all_scalars:argv.extend(['--'+k.replace('_','-'),str(inputs[k])])
    for k,flag in all_repeats:
        for value in inputs[k]:argv.extend([flag,'none' if value is None else str(value)])
    rc,doc=_command(argv,timeout=180,max_output=50000)
    base={'schema','command','status','exit_code','offline_unresolved_exit_code',
          'original_sender_source_paths_required_or_read',
          'ec365_through_ec337_historical_parent_replay_performed',
          *EC370_NEGATIVES}
    if rc==2:
        extra={'publication_bundle_original_sha256','detached_bundle_original_sha256',
          'signed_copy_map_original_sha256',
          'verified_detached_audit_result_canonical_sha256',
          'current_full_publication_inventory_canonical_sha256',
          'actual_publisher_notice_shas','actual_publication_observer_shas',
          'actual_publisher_notice_head_sha256',
          'actual_publication_observer_head_sha256',
          'true_verified_publisher_notice_ed25519_count',
          'true_verified_publication_observer_ed25519_count',
          'true_verified_competing_publisher_ed25519_count',
          'true_verified_competing_observer_ed25519_count',
          'latest_publisher_signed_state','latest_publication_observer_signed_state',
          'latest_publisher_signed_handoff_count',
          'latest_publisher_signed_disclosure_count',
          'inherited_ec369_detached_locally_consistent',
          'inherited_ec369_unresolved_status',
          'locally_two_party_publication_and_full_inventory_consistent',
          *EC370_FLAGS}
        good=(type(doc) is dict and set(doc)==base|extra and
          doc.get('schema')=='ces.ec370.detached_publication_accountability_unresolved.v1' and
          doc.get('command')=='audit-publication-accountability' and
          doc.get('exit_code')==rc and doc.get('offline_unresolved_exit_code')==2 and
          doc.get('original_sender_source_paths_required_or_read') is False and
          doc.get('ec365_through_ec337_historical_parent_replay_performed') is False and
          all(doc.get(v) is False for v in EC370_NEGATIVES) and
          all(type(doc.get(v)) is bool for v in EC370_FLAGS) and
          type(doc.get('inherited_ec369_detached_locally_consistent')) is bool and
          type(doc.get('locally_two_party_publication_and_full_inventory_consistent')) is bool and
          type(doc.get('inherited_ec369_unresolved_status')) is str and
          re.fullmatch('ec369_[a-z0-9_]+_unresolved',
                       doc['inherited_ec369_unresolved_status']) is not None and
          all(sha_ok(doc.get(v)) for v in (
              'publication_bundle_original_sha256',
              'detached_bundle_original_sha256',
              'signed_copy_map_original_sha256',
              'verified_detached_audit_result_canonical_sha256',
              'current_full_publication_inventory_canonical_sha256',
              'actual_publisher_notice_head_sha256',
              'actual_publication_observer_head_sha256')) and
          doc.get('publication_bundle_original_sha256')==inputs[
                'expected_publication_bundle_sha256'] and
          doc.get('detached_bundle_original_sha256')==inputs[
                'expected_detached_bundle_sha256'] and
          doc.get('signed_copy_map_original_sha256')==inputs[
                'expected_signed_copy_map_sha256'] and
          all(type(doc.get(k)) is list and 1<=len(doc[k])<=4 and
              all(sha_ok(v) for v in doc[k]) and len(set(doc[k]))==len(doc[k])
              for k in ('actual_publisher_notice_shas','actual_publication_observer_shas')) and
          all(type(doc.get(k)) is int and 0<=doc[k]<=4 for k in (
              'true_verified_publisher_notice_ed25519_count',
              'true_verified_publication_observer_ed25519_count',
              'true_verified_competing_publisher_ed25519_count',
              'true_verified_competing_observer_ed25519_count',
              'latest_publisher_signed_handoff_count',
              'latest_publisher_signed_disclosure_count')) and
          doc.get('latest_publisher_signed_state') in ('published','withheld','disputed') and
          doc.get('latest_publication_observer_signed_state') in (
              'confirmed','withheld','disputed') and
          doc.get('status')==next((EC370_OUTCOMES[i] for i,k in enumerate(EC370_FLAGS)
                                    if doc[k]),EC370_OUTCOMES[-1])+'_unresolved')
        if good:
            good=(doc['true_verified_publisher_notice_ed25519_count']==len(
                      doc['actual_publisher_notice_shas']) and
                  doc['true_verified_publication_observer_ed25519_count']==len(
                      doc['actual_publication_observer_shas']) and
                  doc['actual_publisher_notice_head_sha256']==doc[
                      'actual_publisher_notice_shas'][-1] and
                  doc['actual_publication_observer_head_sha256']==doc[
                      'actual_publication_observer_shas'][-1] and
                  (not doc['locally_two_party_publication_and_full_inventory_consistent']
                   or (not any(doc[x] for x in EC370_FLAGS) and
                       doc['inherited_ec369_detached_locally_consistent'] and
                       doc['latest_publisher_signed_state']=='published' and
                       doc['latest_publication_observer_signed_state']=='confirmed' and
                       doc['actual_publisher_notice_shas']==inputs[
                            'signed_publisher_notice_shas'] and
                       doc['actual_publication_observer_shas']==inputs[
                            'signed_publication_observer_shas'] and
                       doc['actual_publisher_notice_head_sha256']==inputs[
                            'expected_retained_publisher_notice_head_sha256'] and
                       doc['actual_publication_observer_head_sha256']==inputs[
                            'expected_retained_publication_observer_head_sha256'] and
                       doc['current_full_publication_inventory_canonical_sha256']==inputs[
                            'expected_latest_publication_inventory_sha256'] and
                       doc['latest_publisher_signed_disclosure_count']>=inputs[
                            'minimum_retained_published_challenge_count'])))
        if not good:_fail('EC370_FIXED_CHILD_REPLY_INVALID_OR_OVERCLAIMS',status='unavailable')
    elif rc in (3,4,5):
        good=(type(doc) is dict and set(doc)==base|{'reason_code'} and
          doc.get('schema')=='ces.ec370.detached_publication_accountability_denial.v1' and
          doc.get('command')=='audit-publication-accountability' and
          doc.get('exit_code')==rc and STATUS_EXITS.get(doc.get('status'))==rc and
          doc.get('offline_unresolved_exit_code')==2 and
          doc.get('original_sender_source_paths_required_or_read') is False and
          doc.get('ec365_through_ec337_historical_parent_replay_performed') is False and
          type(doc.get('reason_code')) is str and
          re.fullmatch('[A-Z][A-Z0-9_]{2,170}',doc['reason_code']) is not None and
          all(doc.get(k) is False for k in EC370_NEGATIVES))
        if not good:_fail('EC370_FIXED_CHILD_DENIAL_INVALID',status='unavailable')
    else:_fail('EC370_FIXED_CHILD_EXIT_CODE_UNEXPECTED',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc



# EC371: detached receiver-held historical directory signatures, no old-parent
# completeness or actual historical authority upgrade. Same fixed -I/-B child
# boundary as EC370, additional original SHA streams and strict response shape.
AIRGAP_HISTORICAL_DIRECTORY_ARCHIVE = ROOT / 'scripts' / 'ces_cas_historical_directory_archive.py'
EC371_NEW_SCALARS = (
 'historical_archive_bundle_file','expected_historical_archive_bundle_sha256',
 'claimed_historical_directory_lineage_id',
 'expected_retained_historical_checkpoint_head_sha256',
 'minimum_retained_historical_tree_size',
 'minimum_retained_historical_root_generation',
 'expected_retained_historical_inventory_sha256',
)
EC371_NEW_REPEATS = (
 ('historical_directory_root_shas','--historical-directory-root-sha256'),
 ('historical_signed_checkpoint_shas','--historical-signed-checkpoint-sha256'),
 ('historical_source_a_manifest_shas','--historical-source-a-manifest-sha256'),
 ('historical_source_b_manifest_shas','--historical-source-b-manifest-sha256'),
 ('historical_dual_handoff_shas','--historical-dual-handoff-sha256'),
)
EC371_FLAGS = (
 'inherited_detached_publication_signatures_or_disclosures_unresolved',
 'historical_archive_independent_pins_or_floor_mismatch',
 'historical_signed_directory_checkpoint_fork_or_newer_head_visible',
 'historical_source_signed_publication_fork_or_newer_manifest_visible',
 'historical_rfc6962_append_only_proof_missing_or_invalid',
 'historical_double_signed_directory_handoff_missing_or_fork_visible',
 'historical_signed_directory_retirement_or_role_conflict_visible',
 'historical_source_publication_head_or_clock_anomaly_visible',
 'historical_archive_only_partially_recovers_ec365_to_ec337',
)
EC371_OUTCOMES = (
 'ec371_inherited_detached_publication_has_unresolved_dispute',
 'ec371_independently_retained_historical_originals_or_floors_mismatch',
 'ec371_genuine_historical_signed_directory_fork_or_new_head',
 'ec371_genuine_historical_signed_source_manifest_fork_or_newer_head',
 'ec371_historical_signed_directory_rfc6962_proof_missing_or_invalid',
 'ec371_genuine_historical_dual_handoff_missing_or_conflicting',
 'ec371_directory_retirement_or_signer_lineage_conflict',
 'ec371_historical_source_publication_or_clock_conflict',
 'ec371_historical_directory_origins_only_partially_recovered',
)
EC371_NEGATIVES = (
 'full_ec365_to_ec337_historical_parent_audit_replayed',
 'archive_canonical_sha_matches_the_actual_ec365_result_bytes',
 'old_ec361_to_ec337_parent_directories_and_revocations_replayed',
 'source_manifest_unopened_other_copy_roles_verified',
 'historical_copies_prove_globally_complete_directory_or_absence_of_hidden_forks',
 'caller_pinned_directory_keys_are_official_legal_authorities',
 'signed_self_claimed_utc_is_trusted_timestamp',
 'new_archive_repairs_ec370_ec369_signed_withholding_revocation_or_dispute',
 'sender_original_source_paths_opened_or_restored',
 'new_signatures_private_keys_network_remote_provider_cas_worm_or_powershell_used',
 'old_ec317_ec318_deep_mock_removed_or_final_acceptance_proven',
)


def audit_historical_directory_archive(action:str, mode:str,*,pretty:bool=False,**inputs)->int:
    if (action,mode)!=('DeliveryAudit','AuditHistoricalDirectoryArchive'):
        _fail('EC371_ONLY_DELIVERYAUDIT_AUDITHISTORICALDIRECTORYARCHIVE_READONLY',
              status='permission_denied')
    if (not AIRGAP_HISTORICAL_DIRECTORY_ARCHIVE.is_file() or
            AIRGAP_HISTORICAL_DIRECTORY_ARCHIVE.is_symlink()):
        _fail('EC371_FIXED_CHILD_NOT_AVAILABLE',status='unavailable')
    scalars=(*EC369_SCALARS,*EC370_NEW_SCALARS,*EC371_NEW_SCALARS)
    repeats=(*EC369_REPEATS,*EC370_NEW_REPEATS,*EC371_NEW_REPEATS)
    if set(inputs)!=set(scalars)|{k for k,_ in repeats}:
        _fail('EC371_FIXED_EXACT_FULL_DETACHED_AND_HISTORICAL_INPUTS_REQUIRED')
    sha_ok=lambda x:(type(x) is str and
              re.fullmatch('[0-9a-f]{64}',x) is not None and x!='0'*64)
    path_ok=lambda x:(type(x) is str and os.path.isabs(x) and
              os.path.normpath(x)==x and len(x)<=4000 and
              not x.startswith('//') and '\\' not in x and '\x00' not in x)
    id_ok=lambda x:(type(x) is str and
              re.fullmatch('[A-Za-z][A-Za-z0-9_.:-]{0,95}',x) is not None)
    for key in scalars:
        value=inputs[key]
        if key.endswith('_utc'):
            if type(value) is not str or re.fullmatch(
                r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ',value) is None:
                _fail('EC371_FIXED_STRICT_UTC_REQUIRED')
        elif key.endswith('_file'):
            if not path_ok(value):_fail('EC371_FIXED_ABSOLUTE_SAFE_FILE_REQUIRED')
        elif key.endswith('_sha256'):
            if not sha_ok(value):_fail('EC371_FIXED_CALLER_SHA256_REQUIRED')
        elif key.startswith('minimum_'):
            cap=(64 if key=='minimum_retained_historical_tree_size' else
                 2 if key=='minimum_retained_historical_root_generation' else
                 4 if key=='minimum_retained_published_challenge_count' else 3)
            if type(value) is not int or not 0<=value<=cap:
                _fail('EC371_FIXED_BOUNDED_RETAINED_FLOORS_REQUIRED')
        elif key.startswith('claimed_'):
            if not id_ok(value):_fail('EC371_FIXED_STRICT_ID_REQUIRED')
    known_ids=[inputs['claimed_sender_id'],inputs['claimed_receiver_id'],
               inputs['claimed_publisher_id'],inputs['claimed_publication_observer_id'],
               *inputs['institution_claimed_ids'],*inputs['witness_claimed_ids']]
    known_keys=[inputs['expected_sender_public_key_sha256'],
                inputs['expected_receiver_public_key_sha256'],
                inputs['expected_publisher_public_key_sha256'],
                inputs['expected_publication_observer_public_key_sha256'],
                *inputs['institution_root_public_key_shas'],
                *inputs['witness_public_key_shas']]
    if any(not id_ok(x) for x in known_ids) or len(set(known_ids))!=len(known_ids) or (
        any(not sha_ok(x) for x in known_keys) or len(set(known_keys))!=len(known_keys)):
        _fail('EC371_FIXED_EIGHT_DISTINCT_INHERITED_SIGNERS_REQUIRED',
              status='permission_denied')
    for key,_ in repeats:
        seq=inputs[key]
        old_two=key in ('institution_root_public_key_shas','witness_public_key_shas',
                       'institution_claimed_ids','witness_claimed_ids',
                       'expected_source_status_head_shas',
                       'expected_source_attestation_head_shas',
                       'expected_witness_head_shas')
        is_new=key.startswith('historical_')
        low=(0 if key=='historical_dual_handoff_shas' else 2 if old_two else 1)
        high=(2 if key=='historical_dual_handoff_shas' else
              2 if old_two else 3 if is_new else 4)
        if type(seq) is not list or not low<=len(seq)<=high:
            _fail('EC371_FIXED_BOUNDED_ORIGINAL_SHA_STREAM_REQUIRED')
        if key.endswith('_ids'):
            if any(not id_ok(v) for v in seq) or len(set(seq))!=2:
                _fail('EC371_FIXED_STRICT_DUAL_IDS_REQUIRED')
        else:
            if any(not sha_ok(v) and not (
                 v is None and key=='expected_source_attestation_head_shas')
                   for v in seq):
                _fail('EC371_FIXED_ORIGINAL_SHA_STREAM_VALUE_INVALID')
            if (key.startswith('signed_') or key=='historical_dual_handoff_shas' or
                key in ('institution_root_public_key_shas','witness_public_key_shas')) and (
                len(set(seq))!=len(seq)):
                _fail('EC371_FIXED_DUPLICATED_SIGNER_OR_STREAM_SHA_DENIED')
    n=len(inputs['historical_directory_root_shas'])
    if (any(len(inputs[k])!=n for k in (
           'historical_signed_checkpoint_shas',
           'historical_source_a_manifest_shas',
           'historical_source_b_manifest_shas')) or
        len(inputs['historical_dual_handoff_shas'])>n-1 or
        len(inputs['signed_publisher_notice_shas'])!=len(
            inputs['signed_publication_observer_shas']) or
        len(inputs['signed_sender_dispatch_shas'])!=len(
            inputs['signed_receiver_ack_shas']) or
        len(inputs['signed_challenge_shas'])!=len(inputs['signed_answer_shas'])):
        _fail('EC371_FIXED_INCONSISTENT_SIGNED_ORIGINAL_STREAM_LENGTHS')
    argv=[sys.executable,'-I','-B',str(AIRGAP_HISTORICAL_DIRECTORY_ARCHIVE),
          'audit-historical-directory-archive']
    for key in scalars:argv.extend(['--'+key.replace('_','-'),str(inputs[key])])
    for key,flag in repeats:
        for value in inputs[key]:
            argv.extend([flag,'none' if value is None else str(value)])
    rc,doc=_command(argv,timeout=180,max_output=55000)
    base={'schema','command','status','exit_code','offline_unresolved_exit_code',
          'sender_origin_path_required_or_read',
          'ec365_to_ec337_full_parent_original_replay_performed',
          *EC371_NEGATIVES}
    if rc==2:
        extras={'historical_archive_bundle_original_sha256',
          'verified_live_parent_ec370_result_canonical_sha256',
          'claimed_parent_ec365_canonical_result_sha256',
          'receiver_verified_historical_inventory_canonical_sha256',
          'original_directory_root_sha256_stream',
          'original_signed_checkpoint_sha256_stream',
          'true_verified_directory_checkpoint_ed25519_count',
          'true_verified_source_custodian_ed25519_count',
          'true_verified_old_new_dual_handoff_pair_count',
          'true_verified_rfc6962_directory_append_edges',
          'genuinely_signed_competing_directory_checkpoints',
          'genuinely_signed_competing_source_manifests',
          'genuinely_dual_signed_competing_handoffs',
          'last_historical_tree_size','last_historical_root_generation',
          'local_pinned_historical_directory_signature_and_proof_consistency',
          'inherited_ec370_locally_two_party_publication_consistent',
          *EC371_FLAGS}
        good=(type(doc) is dict and set(doc)==base|extras and
           doc.get('schema')=='ces.ec371.receiver_historical_directory_originals_unresolved.v1' and
           doc.get('command')=='audit-historical-directory-archive' and
           doc.get('exit_code')==2 and doc.get('offline_unresolved_exit_code')==2 and
           doc.get('sender_origin_path_required_or_read') is False and
           doc.get('ec365_to_ec337_full_parent_original_replay_performed') is False and
           all(doc.get(x) is False for x in EC371_NEGATIVES) and
           all(type(doc.get(x)) is bool for x in EC371_FLAGS) and
           doc.get(EC371_FLAGS[-1]) is True and
           type(doc.get('local_pinned_historical_directory_signature_and_proof_consistency')) is bool and
           type(doc.get('inherited_ec370_locally_two_party_publication_consistent')) is bool and
           all(sha_ok(doc.get(x)) for x in (
             'historical_archive_bundle_original_sha256',
             'verified_live_parent_ec370_result_canonical_sha256',
             'claimed_parent_ec365_canonical_result_sha256',
             'receiver_verified_historical_inventory_canonical_sha256')) and
           doc.get('historical_archive_bundle_original_sha256')==inputs[
             'expected_historical_archive_bundle_sha256'] and
           doc.get('claimed_parent_ec365_canonical_result_sha256')==inputs[
             'expected_parent_ec365_canonical_result_sha256'] and
           type(doc.get('original_directory_root_sha256_stream')) is list and
           type(doc.get('original_signed_checkpoint_sha256_stream')) is list and
           1<=len(doc['original_directory_root_sha256_stream'])<=3 and
           len(doc['original_signed_checkpoint_sha256_stream'])==len(
             doc['original_directory_root_sha256_stream']) and
           all(sha_ok(x) for x in doc['original_directory_root_sha256_stream']+
                           doc['original_signed_checkpoint_sha256_stream']) and
           all(type(doc.get(x)) is int and 0<=doc[x]<=64 for x in (
             'true_verified_directory_checkpoint_ed25519_count',
             'true_verified_source_custodian_ed25519_count',
             'true_verified_old_new_dual_handoff_pair_count',
             'true_verified_rfc6962_directory_append_edges',
             'genuinely_signed_competing_directory_checkpoints',
             'genuinely_signed_competing_source_manifests',
             'genuinely_dual_signed_competing_handoffs',
             'last_historical_tree_size','last_historical_root_generation')) and
           doc.get('status')==next((EC371_OUTCOMES[i] for i,k in enumerate(
                                 EC371_FLAGS) if doc[k]),EC371_OUTCOMES[-1])+'_unresolved')
        if good:
            n=len(doc['original_directory_root_sha256_stream'])
            good=(doc['true_verified_directory_checkpoint_ed25519_count']==
                    n+doc['genuinely_signed_competing_directory_checkpoints'] and
                  doc['true_verified_source_custodian_ed25519_count']==2*n and
                  doc['true_verified_old_new_dual_handoff_pair_count']<=
                    n-1+doc['genuinely_dual_signed_competing_handoffs'] and
                  doc['true_verified_rfc6962_directory_append_edges']<=n-1 and
                  doc['last_historical_tree_size']>=1 and
                  doc['last_historical_root_generation']<=n-1 and
                  doc['local_pinned_historical_directory_signature_and_proof_consistency']==(
                    not any(doc[k] for k in EC371_FLAGS[:-1])))
        if good and doc['local_pinned_historical_directory_signature_and_proof_consistency']:
            good=(doc['inherited_ec370_locally_two_party_publication_consistent'] and
                  doc['original_directory_root_sha256_stream']==inputs[
                      'historical_directory_root_shas'] and
                  doc['original_signed_checkpoint_sha256_stream']==inputs[
                      'historical_signed_checkpoint_shas'] and
                  doc['original_signed_checkpoint_sha256_stream'][-1]==inputs[
                      'expected_retained_historical_checkpoint_head_sha256'] and
                  doc['receiver_verified_historical_inventory_canonical_sha256']==inputs[
                      'expected_retained_historical_inventory_sha256'] and
                  doc['last_historical_tree_size']>=inputs[
                      'minimum_retained_historical_tree_size'] and
                  doc['last_historical_root_generation']>=inputs[
                      'minimum_retained_historical_root_generation'] and
                  doc['true_verified_rfc6962_directory_append_edges']==n-1)
        if not good:_fail('EC371_FIXED_CHILD_SUCCESS_SHAPE_OR_CLAIMS_INVALID',
                          status='unavailable')
    elif rc in (3,4,5):
        good=(type(doc) is dict and set(doc)==base|{'reason_code'} and
          doc.get('schema')=='ces.ec371.receiver_historical_directory_originals_denial.v1' and
          doc.get('command')=='audit-historical-directory-archive' and
          doc.get('exit_code')==rc and STATUS_EXITS.get(doc.get('status'))==rc and
          doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec365_to_ec337_full_parent_original_replay_performed') is False and
          all(doc.get(k) is False for k in EC371_NEGATIVES) and
          type(doc.get('reason_code')) is str and
          re.fullmatch('[A-Z][A-Z0-9_]{2,170}',doc['reason_code']) is not None)
        if not good:_fail('EC371_FIXED_CHILD_DENIAL_SHAPE_INVALID',status='unavailable')
    else:_fail('EC371_FIXED_CHILD_EXIT_CODE_INVALID',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc

# EC372: receiver-only actual EC360 authority root, witness and signed revocation
# originals; live EC371 historical directory audit is mandatory, no fake old
# EC365->EC337 parent success and never open sender original or copy labels.
AIRGAP_HISTORICAL_AUTHORITY_ARCHIVE = ROOT / 'scripts' / 'ces_cas_historical_authority_archive.py'
EC372_NEW_SCALARS = (
 'historical_authority_bundle_file',
 'expected_historical_authority_bundle_sha256',
 'expected_retained_historical_authority_inventory_sha256',
)
EC372_NEW_REPEATS = (
 ('historical_authority_a_root_shas','--historical-authority-a-root-sha256'),
 ('historical_authority_b_root_shas','--historical-authority-b-root-sha256'),
 ('historical_authority_a_head_shas','--historical-authority-a-head-sha256'),
 ('historical_authority_b_head_shas','--historical-authority-b-head-sha256'),
 ('minimum_authority_a_revocation_sequences','--minimum-authority-a-revocation-sequence'),
 ('minimum_authority_b_revocation_sequences','--minimum-authority-b-revocation-sequence'),
 ('minimum_authority_a_publication_sequences','--minimum-authority-a-publication-sequence'),
 ('minimum_authority_b_publication_sequences','--minimum-authority-b-publication-sequence'),
)
EC372_FLAGS = (
 'inherited_ec371_directory_custody_or_current_receiver_dispute_unresolved',
 'external_authority_inventory_root_head_or_sequence_floor_mismatch',
 'historical_root_signed_issuer_revoked_or_inventory_coverage_gap',
 'historical_root_signed_revocation_fork_or_regression',
 'historical_scope_or_witnessed_jurisdiction_exclusion',
 'historical_authority_role_collision_or_unproven_cross_epoch_rotation',
 'historical_source_custody_sequence_or_ancestor_claim_disagreement',
 'historical_authority_signature_clock_claim_untrusted',
 'historical_authority_originals_only_partially_recover_ec365_to_ec337',
)
EC372_OUTCOMES = (
 'ec372_inherited_receiver_directory_publication_dispute',
 'ec372_outside_authority_inventory_or_rollback_floor_disagrees',
 'ec372_genuine_root_signed_issuer_revoked_or_not_listed',
 'ec372_signed_revocation_fork_or_history_regression',
 'ec372_delegation_excludes_scope_or_witnessed_jurisdiction',
 'ec372_signer_collision_or_unproved_authority_rotation',
 'ec372_source_publication_sequence_or_ancestor_conflict',
 'ec372_signed_time_claim_untrusted',
 'ec372_partial_old_root_and_source_authority_originals_only',
)
EC372_NEGATIVES = (
 'actual_ec365_to_ec337_complete_original_parent_replay_performed',
 'actual_ec360_to_ec359_authority_parent_result_regenerated',
 'signed_ec359_issuer_and_owner_ancestry_fully_authenticated',
 'signed_delegations_revocations_directory_inclusion_proofs_replayed',
 'source_manifest_unopened_sender_or_other_old_copy_roles_verified',
 'historical_root_signed_inventory_proves_global_complete_revocation',
 'caller_pinned_roots_witnesses_or_issuers_are_official_legal_roles',
 'claimed_utc_or_physical_custody_is_independently_trusted',
 'inherited_ec371_or_ec370_disputes_revocations_repaired',
 'sender_origin_path_required_opened_or_restored',
 'new_signatures_private_keys_network_provider_cas_worm_or_powershell_used',
 'old_deep_mock_removed_or_final_user_acceptance_proven',
)


def audit_historical_authority_archive(action:str,mode:str,*,pretty:bool=False,**inputs)->int:
    if (action,mode)!=('DeliveryAudit','AuditHistoricalAuthorityArchive'):
        _fail('EC372_ONLY_DELIVERYAUDIT_AUDITHISTORICALAUTHORITYARCHIVE_READONLY',
              status='permission_denied')
    if (not AIRGAP_HISTORICAL_AUTHORITY_ARCHIVE.is_file() or
        AIRGAP_HISTORICAL_AUTHORITY_ARCHIVE.is_symlink()):
        _fail('EC372_FIXED_CHILD_NOT_AVAILABLE',status='unavailable')
    scalars=(*EC369_SCALARS,*EC370_NEW_SCALARS,*EC371_NEW_SCALARS,
             *EC372_NEW_SCALARS)
    repeats=(*EC369_REPEATS,*EC370_NEW_REPEATS,*EC371_NEW_REPEATS,
             *EC372_NEW_REPEATS)
    if set(inputs)!=set(scalars)|{k for k,_ in repeats}:
        _fail('EC372_FIXED_EXACT_INPUTS_REQUIRED')
    sha_ok=lambda s:(type(s) is str and
          re.fullmatch('[0-9a-f]{64}',s) is not None and s!='0'*64)
    path_ok=lambda p:(type(p) is str and os.path.isabs(p) and
          os.path.normpath(p)==p and len(p)<=4000 and
          not p.startswith('//') and '\\' not in p and '\x00' not in p)
    id_ok=lambda s:(type(s) is str and
           re.fullmatch('[A-Za-z][A-Za-z0-9_.:-]{0,95}',s) is not None)
    for name in scalars:
        value=inputs[name]
        if name.endswith('_utc'):
            if type(value) is not str or re.fullmatch(
                    r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ',value) is None:
                _fail('EC372_FIXED_STRICT_UTC_REQUIRED')
        elif name.endswith('_file'):
            if not path_ok(value):_fail('EC372_FIXED_NORMAL_ABSOLUTE_FILE_REQUIRED')
        elif name.endswith('_sha256'):
            if not sha_ok(value):_fail('EC372_FIXED_EXTERNAL_SHA256_REQUIRED')
        elif name.startswith('minimum_'):
            cap=(64 if name=='minimum_retained_historical_tree_size' else
                 2 if name=='minimum_retained_historical_root_generation' else
                 4 if name=='minimum_retained_published_challenge_count' else 3)
            if type(value) is not int or not 0<=value<=cap:
                _fail('EC372_FIXED_INHERITED_SEQUENCE_FLOOR_BOUNDS')
        elif name.startswith('claimed_'):
            if not id_ok(value):_fail('EC372_FIXED_STRICT_ID_REQUIRED')
    ids=[inputs['claimed_sender_id'],inputs['claimed_receiver_id'],
         inputs['claimed_publisher_id'],inputs['claimed_publication_observer_id'],
         *inputs['institution_claimed_ids'],*inputs['witness_claimed_ids']]
    shas=[inputs['expected_sender_public_key_sha256'],
          inputs['expected_receiver_public_key_sha256'],
          inputs['expected_publisher_public_key_sha256'],
          inputs['expected_publication_observer_public_key_sha256'],
          *inputs['institution_root_public_key_shas'],
          *inputs['witness_public_key_shas']]
    if (any(not id_ok(x) for x in ids) or len(set(ids))!=8 or
        any(not sha_ok(x) for x in shas) or len(set(shas))!=8):
        _fail('EC372_FIXED_EIGHT_DISTINCT_INHERITED_ROOTS_REQUIRED',
              status='permission_denied')
    n=len(inputs['historical_directory_root_shas'])
    if not 1<=n<=3:_fail('EC372_FIXED_ONE_TO_THREE_HISTORIC_EPOCHS_REQUIRED')
    old_two={'institution_root_public_key_shas','witness_public_key_shas',
             'institution_claimed_ids','witness_claimed_ids',
             'expected_source_status_head_shas',
             'expected_source_attestation_head_shas','expected_witness_head_shas'}
    for key,_ in repeats:
        values=inputs[key]
        if key.startswith(('historical_authority_','minimum_authority_')):
            low=high=n
        else:
            low=(0 if key=='historical_dual_handoff_shas' else
                 2 if key in old_two else 1)
            high=(2 if key=='historical_dual_handoff_shas' else
                  2 if key in old_two else
                  3 if key.startswith('historical_') else 4)
        if type(values) is not list or not low<=len(values)<=high:
            _fail('EC372_FIXED_BOUNDED_SHA_STREAM_OR_FLOOR_REQUIRED')
        if key.endswith('_ids'):
            if len(set(values))!=2 or any(not id_ok(x) for x in values):
                _fail('EC372_FIXED_SIGNER_IDS_INVALID')
        elif key.startswith('minimum_authority_'):
            limit=(4 if 'revocation' in key else 2147483647)
            if any(type(x) is not int or not 0<=x<=limit for x in values):
                _fail('EC372_FIXED_BOUND_HISTORICAL_SEQUENCE_FLOOR_INVALID')
        else:
            if any(not sha_ok(x) and not (
                 x is None and key=='expected_source_attestation_head_shas')
                   for x in values):
                _fail('EC372_FIXED_ORIGINAL_SHA_STREAM_VALUE_INVALID')
            if (key.startswith('signed_') or
                key=='historical_dual_handoff_shas' or
                key in ('institution_root_public_key_shas','witness_public_key_shas')) and (
                len(set(values))!=len(values)):
                _fail('EC372_FIXED_DUPLICATE_SIGNED_ORIGINAL_OR_ROOT_SHA')
    if (any(len(inputs[key])!=n for key in (
            'historical_signed_checkpoint_shas','historical_source_a_manifest_shas',
            'historical_source_b_manifest_shas')) or
        len(inputs['historical_dual_handoff_shas'])>n-1 or
        len(inputs['signed_publisher_notice_shas'])!=len(
            inputs['signed_publication_observer_shas']) or
        len(inputs['signed_sender_dispatch_shas'])!=len(
            inputs['signed_receiver_ack_shas']) or
        len(inputs['signed_challenge_shas'])!=len(inputs['signed_answer_shas'])):
        _fail('EC372_FIXED_INHERITED_SHA_STREAM_COUNT_MISMATCH')
    argv=[sys.executable,'-I','-B',str(AIRGAP_HISTORICAL_AUTHORITY_ARCHIVE),
          'audit-historical-authority-archive']
    for key in scalars:argv.extend(['--'+key.replace('_','-'),str(inputs[key])])
    for key,flag in repeats:
        for value in inputs[key]:
            argv.extend([flag,'none' if value is None else str(value)])
    rc,doc=_command(argv,timeout=180,max_output=59000)
    base={'schema','command','status','exit_code','offline_unresolved_exit_code',
          'sender_origin_path_required_or_read',
          'ec365_to_ec337_full_parent_original_replay_performed',
          *EC372_NEGATIVES}
    if rc==2:
        extras={'historical_authority_bundle_original_sha256',
         'verified_live_parent_ec371_canonical_result_sha256',
         'receiver_verified_historical_authority_inventory_sha256',
         'verified_original_root_signed_delegation_count',
         'verified_original_witness_signed_origin_count',
         'verified_original_root_signed_revocation_snapshot_count',
         'replayed_historical_ec362_signed_source_manifest_count',
         'historical_authority_source_epoch_review_count',
         'historical_authority_source_epoch_reviews',
         'local_pinned_historical_authority_slice_consistent',*EC372_FLAGS}
        good=(type(doc) is dict and set(doc)==base|extras and
              doc.get('schema')=='ces.ec372.receiver_historical_authority_revocation_unresolved.v1' and
              doc.get('command')=='audit-historical-authority-archive' and
              doc.get('exit_code')==2 and doc.get('offline_unresolved_exit_code')==2 and
              doc.get('sender_origin_path_required_or_read') is False and
              doc.get('ec365_to_ec337_full_parent_original_replay_performed') is False and
              all(doc.get(k) is False for k in EC372_NEGATIVES) and
              all(type(doc.get(k)) is bool for k in EC372_FLAGS) and
              doc.get(EC372_FLAGS[-1]) is True and
              type(doc.get('local_pinned_historical_authority_slice_consistent')) is bool and
              all(sha_ok(doc.get(k)) for k in (
                  'historical_authority_bundle_original_sha256',
                  'verified_live_parent_ec371_canonical_result_sha256',
                  'receiver_verified_historical_authority_inventory_sha256')) and
              doc.get('historical_authority_bundle_original_sha256')==inputs[
                  'expected_historical_authority_bundle_sha256'] and
              doc.get('status')==next((EC372_OUTCOMES[i] for i,k in enumerate(
                  EC372_FLAGS) if doc[k]),EC372_OUTCOMES[-1])+'_unresolved' and
              doc.get('local_pinned_historical_authority_slice_consistent') == (
                    not any(doc[k] for k in EC372_FLAGS[:-1])) and
              doc.get('historical_authority_source_epoch_review_count')==2*n and
              doc.get('verified_original_root_signed_delegation_count')==2*n and
              doc.get('verified_original_witness_signed_origin_count')==2*n and
              doc.get('replayed_historical_ec362_signed_source_manifest_count')==2*n and
              type(doc.get('verified_original_root_signed_revocation_snapshot_count')) is int and
              0<=doc['verified_original_root_signed_revocation_snapshot_count']<=10*n and
              type(doc.get('historical_authority_source_epoch_reviews')) is list and
              len(doc['historical_authority_source_epoch_reviews'])==2*n)
        fields={'epoch_index','slot','root_sha','issuer_sha','selected_head',
                'selected_sequence','signed_source_manifest_sha','revoked',
                'coverage','fork','rollback','scope_missing',
                'publication_rollback','clock'}
        if good:
            for i,row in enumerate(doc['historical_authority_source_epoch_reviews']):
                if type(row) is not dict or set(row)!=fields or (
                    type(row['epoch_index']) is not int or row['epoch_index']!=i//2 or
                    row['slot']!=('a' if i%2==0 else 'b') or
                    not sha_ok(row['root_sha']) or not sha_ok(row['issuer_sha']) or
                    (row['selected_head'] is not None and not sha_ok(row['selected_head'])) or
                    (row['selected_sequence'] is not None and (
                      type(row['selected_sequence']) is not int or
                      not 0<=row['selected_sequence']<=4)) or
                    not sha_ok(row['signed_source_manifest_sha']) or
                    any(type(row[x]) is not bool for x in (
                         'revoked','coverage','fork','rollback','scope_missing',
                         'publication_rollback','clock'))):
                    good=False;break
        if good and doc['local_pinned_historical_authority_slice_consistent']:
            for i,row in enumerate(doc['historical_authority_source_epoch_reviews']):
                slot=row['slot'];idx=i//2
                if (row['root_sha']!=inputs['historical_authority_'+slot+'_root_shas'][idx] or
                    row['selected_head']!=inputs['historical_authority_'+slot+'_head_shas'][idx] or
                    row['signed_source_manifest_sha']!=inputs[
                        'historical_source_'+slot+'_manifest_shas'][idx] or
                    row['selected_sequence']<inputs[
                        'minimum_authority_'+slot+'_revocation_sequences'][idx]):
                    good=False;break
            if doc['receiver_verified_historical_authority_inventory_sha256']!=inputs[
                    'expected_retained_historical_authority_inventory_sha256']:
                good=False
        if not good:_fail('EC372_FIXED_CHILD_REPORT_SHAPE_OR_CLAIMS_INVALID',
                          status='unavailable')
    elif rc in (3,4,5):
        good=(type(doc) is dict and set(doc)==base|{'reason_code'} and
             doc.get('schema')=='ces.ec372.receiver_historical_authority_revocation_denial.v1' and
             doc.get('command')=='audit-historical-authority-archive' and
             doc.get('exit_code')==rc and STATUS_EXITS.get(doc.get('status'))==rc and
             doc.get('offline_unresolved_exit_code')==2 and
             doc.get('sender_origin_path_required_or_read') is False and
             doc.get('ec365_to_ec337_full_parent_original_replay_performed') is False and
             all(doc.get(k) is False for k in EC372_NEGATIVES) and
             type(doc.get('reason_code')) is str and
             re.fullmatch('[A-Z][A-Z0-9_]{2,170}',doc['reason_code']) is not None)
        if not good:_fail('EC372_FIXED_CHILD_DENIAL_SHAPE_INVALID',status='unavailable')
    else:_fail('EC372_FIXED_CHILD_EXIT_CODE_INVALID',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc



# EC373: actual historic EC360 RFC6962 inclusion at the already EC371-signed,
# EC362-custodian-advertised head, plus original EC359 issuer Ed25519 ancestry.
# Fixed, isolated, read-only route. Historical EC358->EC337 remains a claim.
AIRGAP_HISTORICAL_INCLUSION_ARCHIVE = ROOT / 'scripts' / 'ces_cas_historical_inclusion_archive.py'
EC373_NEW_SCALARS = (
 'historical_inclusion_bundle_file',
 'expected_historical_inclusion_bundle_sha256',
 'expected_retained_historical_inclusion_inventory_sha256',
)
EC373_NEW_REPEATS = (
 ('historical_distribution_a_head_shas','--historical-distribution-a-head-sha256'),
 ('historical_distribution_b_head_shas','--historical-distribution-b-head-sha256'),
 ('minimum_historical_distribution_a_sequences','--minimum-historical-distribution-a-sequence'),
 ('minimum_historical_distribution_b_sequences','--minimum-historical-distribution-b-sequence'),
 ('minimum_historical_inclusion_tree_sizes','--minimum-historical-inclusion-tree-size'),
)
EC373_FLAGS = (
 'inherited_ec372_ec371_ec370_ec369_receiver_or_authority_dispute_unresolved',
 'external_historical_inclusion_inventory_or_distribution_head_floor_mismatch',
 'historical_genuine_directory_inclusion_proof_invalid',
 'historical_issuer_signed_distribution_fork_revoke_rotate_or_rollback',
 'historical_issuer_owner_scope_or_authentic_ancestor_disagreement',
 'historical_signed_distribution_utc_is_untrusted',
 'historical_source_issuer_distribution_or_directory_history_disagrees',
 'historical_inclusion_and_distribution_only_partially_recover_ec359_to_ec337',
)
EC373_OUTCOMES = (
 'ec373_inherited_receiver_historical_authority_or_directory_dispute',
 'ec373_external_inclusion_inventory_or_distribution_floor_mismatch',
 'ec373_real_rfc6962_signed_checkpoint_inclusion_invalid',
 'ec373_genuine_ec359_issuer_signed_fork_revoke_rotate_or_rollback',
 'ec373_owner_issuer_signed_ancestor_or_scope_disagreement',
 'ec373_ec359_signed_distribution_clock_claim_untrusted',
 'ec373_historical_issuer_distribution_or_directory_cross_epoch_conflict',
 'ec373_partial_historical_inclusion_and_issuer_originals_only',
)
EC373_NEGATIVES = (
 'complete_ec365_to_ec337_historical_parent_originals_replayed',
 'ec360_or_ec359_canonical_result_reproduced_from_original_inputs',
 'ec358_through_ec337_owner_authorization_originals_authenticated',
 'historical_directory_inclusion_proves_global_log_or_hidden_fork_absence',
 'historical_signed_distribution_proves_issuer_legal_identity',
 'original_ec362_sender_and_other_old_source_copy_labels_opened',
 'root_signed_revocations_repaired_or_overridden_by_ec359_records',
 'official_caller_pinned_directory_root_or_witness_status_authenticated',
 'trusted_utc_physical_custody_or_external_publication_verified',
 'private_signing_remote_network_cas_worm_provider_or_powershell_used',
 'old_deep_historical_mock_removed_or_final_acceptance_proven',
)


def audit_historical_inclusion_archive(action:str,mode:str,*,pretty:bool=False,**inputs)->int:
    if (action,mode)!=('DeliveryAudit','AuditHistoricalInclusionArchive'):
        _fail('EC373_ONLY_DELIVERYAUDIT_AUDITHISTORICALINCLUSIONARCHIVE_READONLY',
              status='permission_denied')
    if (not AIRGAP_HISTORICAL_INCLUSION_ARCHIVE.is_file() or
        AIRGAP_HISTORICAL_INCLUSION_ARCHIVE.is_symlink()):
        _fail('EC373_FIXED_CHILD_NOT_AVAILABLE',status='unavailable')
    scalars=(*EC369_SCALARS,*EC370_NEW_SCALARS,*EC371_NEW_SCALARS,
             *EC372_NEW_SCALARS,*EC373_NEW_SCALARS)
    repeats=(*EC369_REPEATS,*EC370_NEW_REPEATS,*EC371_NEW_REPEATS,
             *EC372_NEW_REPEATS,*EC373_NEW_REPEATS)
    if set(inputs)!=set(scalars)|{k for k,_ in repeats}:
        _fail('EC373_FIXED_EXACT_INPUTS_REQUIRED')
    sha_ok=lambda s:(type(s) is str and
         re.fullmatch('[0-9a-f]{64}',s) is not None and s!='0'*64)
    path_ok=lambda s:(type(s) is str and os.path.isabs(s) and
         os.path.normpath(s)==s and len(s)<=4000 and
         not s.startswith('//') and '\\' not in s and '\x00' not in s)
    id_ok=lambda s:(type(s) is str and
         re.fullmatch('[A-Za-z][A-Za-z0-9_.:-]{0,95}',s) is not None)
    for key in scalars:
        v=inputs[key]
        if key.endswith('_utc'):
            if type(v) is not str or re.fullmatch(
                    r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ',v) is None:
                _fail('EC373_FIXED_STRICT_EVALUATION_UTC_REQUIRED')
        elif key.endswith('_file'):
            if not path_ok(v):_fail('EC373_FIXED_ABSOLUTE_NORMALIZED_FILE_REQUIRED')
        elif key.endswith('_sha256'):
            if not sha_ok(v):_fail('EC373_FIXED_SHA256_REQUIRED')
        elif key.startswith('minimum_'):
            cap=(64 if key=='minimum_retained_historical_tree_size' else
                 2 if key=='minimum_retained_historical_root_generation' else
                 4 if key=='minimum_retained_published_challenge_count' else 3)
            if type(v) is not int or not 0<=v<=cap:
                _fail('EC373_FIXED_OLD_SEQUENCE_FLOOR_OUT_OF_BOUNDS')
        elif key.startswith('claimed_'):
            if not id_ok(v):_fail('EC373_FIXED_STRICT_ID_REQUIRED')
    n=len(inputs['historical_directory_root_shas'])
    if not 1<=n<=3:_fail('EC373_FIXED_HISTORIC_EPOCH_COUNT_INVALID')
    two={'institution_root_public_key_shas','witness_public_key_shas',
         'institution_claimed_ids','witness_claimed_ids',
         'expected_source_status_head_shas','expected_source_attestation_head_shas',
         'expected_witness_head_shas'}
    for key,_ in repeats:
        seq=inputs[key]
        if key in two:lo=hi=2
        elif key=='historical_dual_handoff_shas':lo=0;hi=n-1
        elif key.startswith('historical_') or key.startswith('minimum_authority_') or key.startswith('minimum_historical_'):
            lo=hi=n
        else:lo=1;hi=4
        if type(seq) is not list or not lo<=len(seq)<=hi:
            _fail('EC373_FIXED_HISTORICAL_SHA_SEQUENCE_LENGTH_INVALID')
        if key.endswith('_ids'):
            if any(not id_ok(x) for x in seq) or len(set(seq))!=len(seq):
                _fail('EC373_FIXED_SIGNED_SOURCE_IDS_INVALID')
        elif key.startswith('minimum_'):
            upper=(4 if 'revocation' in key else
                   5 if 'distribution' in key else
                   64 if 'tree_size' in key else 2147483647)
            lower=1 if 'tree_size' in key else 0
            if any(type(x) is not int or not lower<=x<=upper for x in seq):
                _fail('EC373_FIXED_HISTORICAL_SEQUENCE_FLOOR_INVALID')
        elif any(not sha_ok(x) and not (x is None and key==
                            'expected_source_attestation_head_shas') for x in seq):
            _fail('EC373_FIXED_HISTORICAL_ORIGINAL_SHA_INVALID')
        if (key.startswith('signed_') or key=='historical_dual_handoff_shas') and (
                len(set(seq))!=len(seq)):
            _fail('EC373_FIXED_DUPLICATE_SIGNED_HISTORY_DENIED')
    for name in ('historical_signed_checkpoint_shas','historical_source_a_manifest_shas',
                 'historical_source_b_manifest_shas','historical_authority_a_root_shas',
                 'historical_authority_b_root_shas','historical_authority_a_head_shas',
                 'historical_authority_b_head_shas'):
        if len(inputs[name])!=n:_fail('EC373_FIXED_HISTORIC_EPOCH_SHA_COUNT_MISMATCH')
    for key in ('institution_root_public_key_shas','witness_public_key_shas'):
        if len(set(inputs[key]))!=2:_fail('EC373_FIXED_DUAL_SIGNER_KEY_COLLISION')
    argv=[sys.executable,'-I','-B',str(AIRGAP_HISTORICAL_INCLUSION_ARCHIVE),
          'audit-historical-inclusion-archive']
    for key in scalars:argv.extend(['--'+key.replace('_','-'),str(inputs[key])])
    for key,flag in repeats:
        for v in inputs[key]:argv.extend([flag,'none' if v is None else str(v)])
    rc,doc=_command(argv,timeout=180,max_output=76000)
    base={'schema','command','status','exit_code','offline_unresolved_exit_code',
          'sender_origin_path_required_or_read',
          'ec365_to_ec337_full_parent_original_replay_performed',*EC373_NEGATIVES}
    if rc==2:
        extra={'historical_inclusion_bundle_original_sha256',
          'verified_live_parent_ec372_canonical_result_sha256',
          'receiver_verified_historical_inclusion_inventory_sha256',
          'verified_exact_ec371_signed_checkpoint_count',
          'recomputed_actual_rfc6962_inclusion_proof_count',
          'attempted_rfc6962_inclusion_proof_count',
          'replayed_genuine_ec359_issuer_signed_record_count',
          'historical_inclusion_epoch_reviews',
          'historical_issuer_source_epoch_reviews',
          'local_pinned_historical_inclusion_and_issuer_slice_consistent',*EC373_FLAGS}
        good=(type(doc) is dict and set(doc)==base|extra and
              doc.get('schema')=='ces.ec373.receiver_historical_inclusion_issuer_ancestry_unresolved.v1' and
              doc.get('command')=='audit-historical-inclusion-archive' and
              doc.get('exit_code')==2 and doc.get('offline_unresolved_exit_code')==2 and
              doc.get('sender_origin_path_required_or_read') is False and
              doc.get('ec365_to_ec337_full_parent_original_replay_performed') is False and
              all(doc.get(k) is False for k in EC373_NEGATIVES) and
              all(type(doc.get(k)) is bool for k in EC373_FLAGS) and
              doc.get(EC373_FLAGS[-1]) is True and
              type(doc.get('local_pinned_historical_inclusion_and_issuer_slice_consistent')) is bool and
              doc.get('local_pinned_historical_inclusion_and_issuer_slice_consistent') ==
                  (not any(doc[k] for k in EC373_FLAGS[:-1])) and
              doc.get('status')==next((EC373_OUTCOMES[i] for i,k in enumerate(EC373_FLAGS)
                                         if doc[k]),EC373_OUTCOMES[-1])+'_unresolved' and
              all(sha_ok(doc.get(key)) for key in (
                   'historical_inclusion_bundle_original_sha256',
                   'verified_live_parent_ec372_canonical_result_sha256',
                   'receiver_verified_historical_inclusion_inventory_sha256')) and
              doc.get('historical_inclusion_bundle_original_sha256')==inputs[
                   'expected_historical_inclusion_bundle_sha256'] and
              doc.get('verified_exact_ec371_signed_checkpoint_count')==n and
              type(doc.get('historical_inclusion_epoch_reviews')) is list and
              len(doc['historical_inclusion_epoch_reviews'])==n and
              type(doc.get('historical_issuer_source_epoch_reviews')) is list and
              len(doc['historical_issuer_source_epoch_reviews'])==2*n and
              type(doc.get('attempted_rfc6962_inclusion_proof_count')) is int and
              2*n<=doc['attempted_rfc6962_inclusion_proof_count']<=12*n and
              type(doc.get('recomputed_actual_rfc6962_inclusion_proof_count')) is int and
              0<=doc['recomputed_actual_rfc6962_inclusion_proof_count']<=doc[
                  'attempted_rfc6962_inclusion_proof_count'] and
              type(doc.get('replayed_genuine_ec359_issuer_signed_record_count')) is int and
              2*n<=doc['replayed_genuine_ec359_issuer_signed_record_count']<=12*n)
        if good:
            for i,row in enumerate(doc['historical_inclusion_epoch_reviews']):
                if (type(row) is not dict or set(row)!={
                    'epoch_index','checkpoint_sha','tree_size',
                    'inclusion_proofs_attempted','unique_included_original_shas'} or
                    type(row['epoch_index']) is not int or row['epoch_index']!=i or
                    row['checkpoint_sha']!=inputs['historical_signed_checkpoint_shas'][i] or
                    type(row['tree_size']) is not int or not 1<=row['tree_size']<=64 or
                    type(row['inclusion_proofs_attempted']) is not int or
                    not 2<=row['inclusion_proofs_attempted']<=12 or
                    type(row['unique_included_original_shas']) is not list or
                    len(row['unique_included_original_shas'])!=row['inclusion_proofs_attempted'] or
                    row['unique_included_original_shas']!=sorted(set(
                        row['unique_included_original_shas'])) or
                    not all(sha_ok(s) for s in row['unique_included_original_shas'])):
                    good=False;break
            if good:
                for i,row in enumerate(doc['historical_issuer_source_epoch_reviews']):
                    slot='a' if i%2==0 else 'b';epoch=i//2
                    if (type(row) is not dict or set(row)!={
                      'epoch_index','slot','issuer_sha','owner_sha','selected_head',
                      'selected_sequence','selected_operation','fork_or_terminal','rollback','clock'} or
                        row['epoch_index']!=epoch or row['slot']!=slot or
                        not sha_ok(row['issuer_sha']) or not sha_ok(row['owner_sha']) or
                        not sha_ok(row['selected_head']) or
                        type(row['selected_sequence']) is not int or
                        not 0<=row['selected_sequence']<=5 or
                        row['selected_operation'] not in ('authorize','revoke','rotate') or
                        any(type(row[key]) is not bool for key in (
                            'fork_or_terminal','rollback','clock'))):
                        good=False;break
                    if doc['local_pinned_historical_inclusion_and_issuer_slice_consistent'] and (
                       row['selected_head']!=inputs[
                           'historical_distribution_'+slot+'_head_shas'][epoch] or
                       row['selected_sequence']<inputs[
                           'minimum_historical_distribution_'+slot+'_sequences'][epoch]):
                        good=False;break
        if good and doc['local_pinned_historical_inclusion_and_issuer_slice_consistent']:
            good=(doc['recomputed_actual_rfc6962_inclusion_proof_count']==doc[
                     'attempted_rfc6962_inclusion_proof_count'] and
                  doc['receiver_verified_historical_inclusion_inventory_sha256']==inputs[
                     'expected_retained_historical_inclusion_inventory_sha256'] and
                  all(r['tree_size']>=inputs['minimum_historical_inclusion_tree_sizes'][i]
                      for i,r in enumerate(doc['historical_inclusion_epoch_reviews'])))
        if not good:_fail('EC373_FIXED_CHILD_REPORT_SHAPE_OR_BOUND_INCONSISTENT',
                           status='unavailable')
    elif rc in (3,4,5):
        good=(type(doc) is dict and set(doc)==base|{'reason_code'} and
          doc.get('schema')=='ces.ec373.receiver_historical_inclusion_issuer_ancestry_denial.v1' and
          doc.get('command')=='audit-historical-inclusion-archive' and
          doc.get('exit_code')==rc and STATUS_EXITS.get(doc.get('status'))==rc and
          doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec365_to_ec337_full_parent_original_replay_performed') is False and
          all(doc.get(k) is False for k in EC373_NEGATIVES) and
          type(doc.get('reason_code')) is str and
          re.fullmatch('[A-Z][A-Z0-9_]{2,170}',doc['reason_code']) is not None)
        if not good:_fail('EC373_FIXED_CHILD_DENIAL_SHAPE_INVALID',status='unavailable')
    else:_fail('EC373_FIXED_CHILD_EXIT_CODE_INVALID',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc



