def audit_historical_owner_archive(action:str,mode:str,*,pretty:bool=False,**inputs)->int:
    if (action,mode)!=('DeliveryAudit','AuditHistoricalOwnerArchive'):
        _fail('EC374_ONLY_DELIVERYAUDIT_AUDITHISTORICALOWNERARCHIVE_READONLY',
              status='permission_denied')
    if (not AIRGAP_HISTORICAL_OWNER_ARCHIVE.is_file() or
        AIRGAP_HISTORICAL_OWNER_ARCHIVE.is_symlink()):
        _fail('EC374_FIXED_CHILD_NOT_AVAILABLE',status='unavailable')
    scalars=(*EC369_SCALARS,*EC370_NEW_SCALARS,*EC371_NEW_SCALARS,
             *EC372_NEW_SCALARS,*EC373_NEW_SCALARS,*EC374_NEW_SCALARS)
    repeats=(*EC369_REPEATS,*EC370_NEW_REPEATS,*EC371_NEW_REPEATS,
             *EC372_NEW_REPEATS,*EC373_NEW_REPEATS,*EC374_NEW_REPEATS)
    if set(inputs)!=set(scalars)|{k for k,_ in repeats}:
        _fail('EC374_FIXED_EXACT_INPUTS_REQUIRED')
    sha_ok=lambda s:type(s) is str and re.fullmatch('[0-9a-f]{64}',s) is not None and s!='0'*64
    path_ok=lambda s:type(s) is str and os.path.isabs(s) and os.path.normpath(s)==s and len(s)<=4000 and not s.startswith('//') and '\\' not in s and '\x00' not in s
    id_ok=lambda s:type(s) is str and re.fullmatch('[A-Za-z][A-Za-z0-9_.:-]{0,95}',s) is not None
    for key in scalars:
        val=inputs[key]
        if key.endswith('_utc'):
            if type(val) is not str or re.fullmatch(r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ',val) is None:
                _fail('EC374_FIXED_EVALUATION_UTC_INVALID')
        elif key.endswith('_file'):
            if not path_ok(val):_fail('EC374_FIXED_ABSOLUTE_NORMALIZED_PATH_REQUIRED')
        elif key.endswith('_sha256'):
            if not sha_ok(val):_fail('EC374_FIXED_SHA256_REQUIRED')
        elif key.startswith('minimum_'):
            cap=(64 if key=='minimum_retained_historical_tree_size' else
                 2 if key=='minimum_retained_historical_root_generation' else
                 4 if key=='minimum_retained_published_challenge_count' else 3)
            if type(val) is not int or not 0<=val<=cap:
                _fail('EC374_FIXED_INHERITED_SEQUENCE_FLOOR_INVALID')
        elif key.startswith('claimed_'):
            if not id_ok(val):_fail('EC374_FIXED_CLAIMED_ID_INVALID')
    n=len(inputs['historical_directory_root_shas'])
    if not 1<=n<=3:_fail('EC374_FIXED_HISTORIC_EPOCH_COUNT_INVALID')
    two={'institution_root_public_key_shas','witness_public_key_shas',
         'institution_claimed_ids','witness_claimed_ids',
         'expected_source_status_head_shas','expected_source_attestation_head_shas',
         'expected_witness_head_shas'}
    for key,_ in repeats:
        seq=inputs[key]
        if key in two:lo=hi=2
        elif key=='historical_dual_handoff_shas':lo=0;hi=n-1
        elif key.startswith('historical_') or key.startswith('minimum_authority_') or key.startswith('minimum_historical_'):
            lo=hi=n
        else:lo=1;hi=4
        if type(seq) is not list or not lo<=len(seq)<=hi:
            _fail('EC374_FIXED_HISTORY_SHA_STREAM_LENGTH_INVALID')
        if key.endswith('_ids'):
            if any(not id_ok(x) for x in seq) or len(set(seq))!=len(seq):
                _fail('EC374_FIXED_SOURCE_IDS_INVALID')
        elif key.startswith('minimum_'):
            upper=(7 if 'owner_' in key else
                   4 if 'revocation' in key else
                   5 if 'distribution' in key else
                   64 if 'tree_size' in key else 2147483647)
            lower=1 if 'tree_size' in key else 0
            if any(type(x) is not int or not lower<=x<=upper for x in seq):
                _fail('EC374_FIXED_HISTORIC_SEQUENCE_FLOOR_INVALID')
        elif any(not sha_ok(x) and not (x is None and key==
                 'expected_source_attestation_head_shas') for x in seq):
            _fail('EC374_FIXED_HISTORIC_SHA_STREAM_INVALID')
        if (key.startswith('signed_') or key=='historical_dual_handoff_shas') and len(set(seq))!=len(seq):
            _fail('EC374_FIXED_DUPLICATE_SIGNED_HISTORY_DENIED')
    for key in ('historical_signed_checkpoint_shas','historical_source_a_manifest_shas',
                'historical_source_b_manifest_shas','historical_authority_a_root_shas',
                'historical_authority_b_root_shas','historical_authority_a_head_shas',
                'historical_authority_b_head_shas'):
        if len(inputs[key])!=n:_fail('EC374_FIXED_OLD_EPOCH_COVERAGE_MISMATCH')
    for key in ('institution_root_public_key_shas','witness_public_key_shas'):
        if len(set(inputs[key]))!=2:_fail('EC374_FIXED_DUAL_ROLE_KEY_COLLISION')
    argv=[sys.executable,'-I','-B',str(AIRGAP_HISTORICAL_OWNER_ARCHIVE),
          'audit-historical-owner-archive']
    for key in scalars:argv.extend(['--'+key.replace('_','-'),str(inputs[key])])
    for key,flag in repeats:
        for value in inputs[key]:argv.extend([flag,'none' if value is None else str(value)])
    rc,doc=_command(argv,timeout=180,max_output=78000)
    base={'schema','command','status','exit_code','offline_unresolved_exit_code',
          'sender_origin_path_required_or_read',
          'ec365_to_ec337_full_parent_original_replay_performed',*EC374_NEGATIVES}
    if rc==2:
        extra={'historical_owner_epoch_bundle_original_sha256',
            'verified_live_parent_ec373_canonical_result_sha256',
            'receiver_verified_historical_owner_inventory_sha256',
            'verified_real_ec357_source_review_signature_count',
            'verified_real_ec358_owner_epoch_event_count',
            'verified_owner_source_epoch_review_count',
            'historical_owner_source_epoch_reviews',
            'local_pinned_historical_owner_reviewer_slice_consistent',*EC374_FLAGS}
        good=(type(doc) is dict and set(doc)==base|extra and
            doc.get('schema')=='ces.ec374.receiver_historical_owner_reviewer_signed_originals_unresolved.v1' and
            doc.get('command')=='audit-historical-owner-archive' and
            doc.get('exit_code')==2 and doc.get('offline_unresolved_exit_code')==2 and
            doc.get('sender_origin_path_required_or_read') is False and
            doc.get('ec365_to_ec337_full_parent_original_replay_performed') is False and
            all(doc.get(k) is False for k in EC374_NEGATIVES) and
            all(type(doc.get(k)) is bool for k in EC374_FLAGS) and
            doc.get(EC374_FLAGS[-1]) is True and
            type(doc.get('local_pinned_historical_owner_reviewer_slice_consistent')) is bool and
            doc['local_pinned_historical_owner_reviewer_slice_consistent']==(
                not any(doc[k] for k in EC374_FLAGS[:-1])) and
            doc.get('status')==next((EC374_OUTCOMES[i] for i,k in enumerate(EC374_FLAGS)
                     if doc[k]),EC374_OUTCOMES[-1])+'_unresolved' and
            all(sha_ok(doc.get(k)) for k in (
               'historical_owner_epoch_bundle_original_sha256',
               'verified_live_parent_ec373_canonical_result_sha256',
               'receiver_verified_historical_owner_inventory_sha256')) and
            doc['historical_owner_epoch_bundle_original_sha256']==inputs[
                    'expected_historical_owner_epoch_bundle_sha256'] and
            doc.get('verified_real_ec357_source_review_signature_count')==2*n and
            doc.get('verified_owner_source_epoch_review_count')==2*n and
            type(doc.get('verified_real_ec358_owner_epoch_event_count')) is int and
            2*n<=doc['verified_real_ec358_owner_epoch_event_count']<=16*n and
            type(doc.get('historical_owner_source_epoch_reviews')) is list and
            len(doc['historical_owner_source_epoch_reviews'])==2*n)
        fields={'epoch_index','slot','owner_sha','source_reviewer_sha',
                'selected_head','selected_epoch','selected_operation',
                'selected_reviewer_sha','fork','revoked','reviewer_mismatch','clock'}
        if good:
            for j,row in enumerate(doc['historical_owner_source_epoch_reviews']):
                slot='a' if j%2==0 else 'b';i=j//2
                if (type(row) is not dict or set(row)!=fields or
                    type(row['epoch_index']) is not int or row['epoch_index']!=i or
                    row['slot']!=slot or
                    any(not sha_ok(row[x]) for x in ('owner_sha','source_reviewer_sha','selected_head')) or
                    type(row['selected_epoch']) is not int or not 0<=row['selected_epoch']<=7 or
                    row['selected_operation'] not in ('issue','rotate','revoke') or
                    (row['selected_reviewer_sha'] is not None and not sha_ok(row['selected_reviewer_sha'])) or
                    any(type(row[x]) is not bool for x in ('fork','revoked','reviewer_mismatch','clock'))):
                    good=False;break
                if doc['local_pinned_historical_owner_reviewer_slice_consistent'] and (
                    row['selected_head']!=inputs['historical_owner_'+slot+'_head_shas'][i] or
                    row['selected_epoch']<inputs['minimum_historical_owner_'+slot+'_epochs'][i] or
                    row['source_reviewer_sha']!=inputs['historical_reviewer_'+slot+'_key_shas'][i] or
                    row['selected_reviewer_sha']!=row['source_reviewer_sha']):
                    good=False;break
        if good and doc['local_pinned_historical_owner_reviewer_slice_consistent']:
            good=doc['receiver_verified_historical_owner_inventory_sha256']==inputs[
                         'expected_retained_historical_owner_inventory_sha256']
        if not good:_fail('EC374_FIXED_CHILD_REPORT_SHAPE_OR_CLAIMS_INVALID',status='unavailable')
    elif rc in (3,4,5):
        good=(type(doc) is dict and set(doc)==base|{'reason_code'} and
            doc.get('schema')=='ces.ec374.receiver_historical_owner_reviewer_signed_originals_denial.v1' and
            doc.get('command')=='audit-historical-owner-archive' and
            doc.get('exit_code')==rc and STATUS_EXITS.get(doc.get('status'))==rc and
            doc.get('offline_unresolved_exit_code')==2 and
            doc.get('sender_origin_path_required_or_read') is False and
            doc.get('ec365_to_ec337_full_parent_original_replay_performed') is False and
            all(doc.get(x) is False for x in EC374_NEGATIVES) and
            type(doc.get('reason_code')) is str and
            re.fullmatch('[A-Z][A-Z0-9_]{2,170}',doc['reason_code']) is not None)
        if not good:_fail('EC374_FIXED_CHILD_DENIAL_SHAPE_INVALID',status='unavailable')
    else:_fail('EC374_FIXED_CHILD_EXIT_CODE_INVALID',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc



