    if set(inputs)!=set(scalars)|{k for k,_ in repeats}:
        _fail('EC375_FIXED_EXACT_INPUTS_REQUIRED')
    sha_ok=lambda v:type(v) is str and re.fullmatch('[0-9a-f]{64}',v) is not None and v!='0'*64
    path_ok=lambda v:type(v) is str and os.path.isabs(v) and os.path.normpath(v)==v and len(v)<=4000 and not v.startswith('//') and '\\' not in v and '\x00' not in v
    id_ok=lambda v:type(v) is str and re.fullmatch('[A-Za-z][A-Za-z0-9_.:-]{0,95}',v) is not None
    for key in scalars:
        value=inputs[key]
        if key.endswith('_utc'):
            if type(value) is not str or re.fullmatch(r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ',value) is None:
                _fail('EC375_FIXED_EVALUATION_UTC_INVALID')
        elif key.endswith('_file'):
            if not path_ok(value):_fail('EC375_FIXED_ABSOLUTE_NORMALIZED_PATH_REQUIRED')
        elif key.endswith('_sha256'):
            if not sha_ok(value):_fail('EC375_FIXED_SHA256_REQUIRED')
        elif key.startswith('minimum_'):
            upper=(64 if key=='minimum_retained_historical_tree_size' else
                   2 if key=='minimum_retained_historical_root_generation' else
                   4 if key=='minimum_retained_published_challenge_count' else 3)
            if type(value) is not int or not 0<=value<=upper:
                _fail('EC375_FIXED_INHERITED_SEQUENCE_FLOOR_INVALID')
        elif key.startswith('claimed_'):
            if not id_ok(value):_fail('EC375_FIXED_CLAIMED_ID_INVALID')
    n=len(inputs['historical_directory_root_shas'])
    if not 1<=n<=3:_fail('EC375_FIXED_HISTORIC_EPOCH_COUNT_INVALID')
    two={'institution_root_public_key_shas','witness_public_key_shas',
         'institution_claimed_ids','witness_claimed_ids',
         'expected_source_status_head_shas','expected_source_attestation_head_shas',
         'expected_witness_head_shas'}
    for key,_ in repeats:
        seq=inputs[key]
        if key in two:lo=hi=2
        elif key=='historical_dual_handoff_shas':lo=0;hi=n-1
        elif key.startswith('historical_') or key.startswith('minimum_authority_') or key.startswith('minimum_historical_'):
            lo=hi=n
        else:lo=1;hi=4
        if type(seq) is not list or not lo<=len(seq)<=hi:
            _fail('EC375_FIXED_SHA_HISTORY_LENGTH_INVALID')
        if key.endswith('_ids'):
            if any(not id_ok(item) for item in seq) or len(set(seq))!=len(seq):
                _fail('EC375_FIXED_SOURCE_IDS_INVALID')
        elif key.startswith('minimum_'):
            upper=(24 if 'custody_' in key else 7 if 'owner_' in key else
                   4 if 'revocation' in key else 5 if 'distribution' in key else
                   64 if 'tree_size' in key else 2147483647)
            lower=1 if 'tree_size' in key else 0
            if any(type(item) is not int or not lower<=item<=upper for item in seq):
                _fail('EC375_FIXED_SEQUENCE_FLOOR_INVALID')
        elif any(not sha_ok(item) and not (item is None and
                 key=='expected_source_attestation_head_shas') for item in seq):
            _fail('EC375_FIXED_SHA_STREAM_INVALID')
        if (key.startswith('signed_') or key=='historical_dual_handoff_shas') and len(set(seq))!=len(seq):
            _fail('EC375_FIXED_DUPLICATE_SIGNED_HISTORY_DENIED')
    for key in ('institution_root_public_key_shas','witness_public_key_shas'):
        if len(set(inputs[key]))!=2:_fail('EC375_FIXED_DUAL_SIGNER_KEY_REUSE')
    argv=[sys.executable,'-I','-B',str(AIRGAP_HISTORICAL_CUSTODY_ARCHIVE),
          'audit-historical-custody-archive']
    for key in scalars:argv.extend(['--'+key.replace('_','-'),str(inputs[key])])
    for key,flag in repeats:
        for item in inputs[key]:argv.extend([flag,'none' if item is None else str(item)])
    rc,doc=_command(argv,timeout=180,max_output=92000)
    base={'schema','command','status','exit_code','offline_unresolved_exit_code',
          'sender_origin_path_required_or_read',
          'ec365_to_ec337_full_parent_original_replay_performed',*EC375_NEGATIVES}
    if rc==2:
        extra={'historical_custody_archive_bundle_original_sha256',
          'verified_live_parent_ec374_canonical_result_sha256',
          'receiver_verified_historical_custody_inventory_sha256',
          'verified_real_ec356_root_signed_reference_count',
          'verified_real_ec356_root_signed_channel_authorization_count',
          'verified_real_ec356_channel_signed_acknowledgement_count',
          'verified_real_old_ec356_original_copy_pair_count',
          'historical_custody_source_epoch_reviews',
          'local_pinned_historical_custody_signatures_and_source_inventory_consistent',
          *EC375_FLAGS}
        good=(type(doc) is dict and set(doc)==base|extra and
            doc.get('schema')=='ces.ec375.receiver_historic_ec356_signed_custody_ec357_bridge_unresolved.v1' and
            doc.get('command')=='audit-historical-custody-archive' and
            doc.get('exit_code')==2 and doc.get('offline_unresolved_exit_code')==2 and
            doc.get('sender_origin_path_required_or_read') is False and
            doc.get('ec365_to_ec337_full_parent_original_replay_performed') is False and
            all(doc.get(x) is False for x in EC375_NEGATIVES) and
            all(type(doc.get(x)) is bool for x in EC375_FLAGS) and
            doc.get(EC375_FLAGS[-1]) is True and
            type(doc.get('local_pinned_historical_custody_signatures_and_source_inventory_consistent')) is bool and
            doc['local_pinned_historical_custody_signatures_and_source_inventory_consistent']==(
                not any(doc[x] for x in EC375_FLAGS[:-1])) and
            doc.get('status')==next((EC375_OUTCOMES[i] for i,x in enumerate(EC375_FLAGS)
                             if doc[x]),EC375_OUTCOMES[-1])+'_unresolved' and
            all(sha_ok(doc.get(x)) for x in (
                'historical_custody_archive_bundle_original_sha256',
                'verified_live_parent_ec374_canonical_result_sha256',
                'receiver_verified_historical_custody_inventory_sha256')) and
            doc['historical_custody_archive_bundle_original_sha256']==inputs[
                         'expected_historical_custody_archive_bundle_sha256'] and
            doc.get('verified_real_ec356_root_signed_reference_count')==2*n and
            doc.get('verified_real_ec356_root_signed_channel_authorization_count')==2*n and
            type(doc.get('verified_real_ec356_channel_signed_acknowledgement_count')) is int and
            2*n<=doc['verified_real_ec356_channel_signed_acknowledgement_count']<=48*n and
            type(doc.get('verified_real_old_ec356_original_copy_pair_count')) is int and
            0<=doc['verified_real_old_ec356_original_copy_pair_count']<=48*n and
            type(doc.get('historical_custody_source_epoch_reviews')) is list and
            len(doc['historical_custody_source_epoch_reviews'])==2*n)
        fields={'epoch_index','slot','root_public_key_sha','channel_public_key_sha',
                'selected_ack_head_sha','verified_signed_ack_count',
                'actual_copied_pair_count','ec357_signed_inventory_row_count',
                'signed_root_review_missing_or_conflicting',
                'signed_inventory_missing_or_conflicting','signed_ack_fork'}
        if good:
            for j,row in enumerate(doc['historical_custody_source_epoch_reviews']):
                slot='a' if j%2==0 else 'b';i=j//2
                if (type(row) is not dict or set(row)!=fields or
                    type(row['epoch_index']) is not int or row['epoch_index']!=i or
                    row['slot']!=slot or
                    any(not sha_ok(row[k]) for k in (
                       'root_public_key_sha','channel_public_key_sha','selected_ack_head_sha')) or
                    any(type(row[k]) is not int or not 0<=row[k]<=24 for k in (
                       'verified_signed_ack_count','actual_copied_pair_count',
                       'ec357_signed_inventory_row_count')) or
                    any(type(row[k]) is not bool for k in (
                       'signed_root_review_missing_or_conflicting',
                       'signed_inventory_missing_or_conflicting','signed_ack_fork'))):
                    good=False;break
                if doc['local_pinned_historical_custody_signatures_and_source_inventory_consistent'] and (
                     row['root_public_key_sha']!=inputs['historical_custody_'+slot+'_root_key_shas'][i] or
                     row['selected_ack_head_sha']!=inputs['historical_custody_'+slot+'_ack_head_shas'][i] or
                     row['verified_signed_ack_count']<inputs[
                           'minimum_historical_custody_'+slot+'_ack_counts'][i]):
                    good=False;break
        if good and doc['local_pinned_historical_custody_signatures_and_source_inventory_consistent']:
            good=(doc['receiver_verified_historical_custody_inventory_sha256']==inputs[
                    'expected_retained_historical_custody_inventory_sha256'])
        if not good:_fail('EC375_FIXED_CHILD_REPORT_SHAPE_OR_CLAIMS_INVALID',status='unavailable')
    elif rc in (3,4,5):
        good=(type(doc) is dict and set(doc)==base|{'reason_code'} and
              doc.get('schema')=='ces.ec375.receiver_historic_ec356_signed_custody_denial.v1' and
              doc.get('command')=='audit-historical-custody-archive' and
              doc.get('exit_code')==rc and STATUS_EXITS.get(doc.get('status'))==rc and
              doc.get('offline_unresolved_exit_code')==2 and
              doc.get('sender_origin_path_required_or_read') is False and
              doc.get('ec365_to_ec337_full_parent_original_replay_performed') is False and
              all(doc.get(x) is False for x in EC375_NEGATIVES) and
              type(doc.get('reason_code')) is str and
              re.fullmatch('[A-Z][A-Z0-9_]{2,170}',doc['reason_code']) is not None)
        if not good:_fail('EC375_FIXED_CHILD_DENIAL_SHAPE_INVALID',status='unavailable')
    else:_fail('EC375_FIXED_CHILD_EXIT_CODE_INVALID',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc



