def audit_historical_source_archive(action:str,mode:str,*,pretty:bool=False,**inputs)->int:
    if (action,mode)!=('DeliveryAudit','AuditHistoricalSourceArchive'):
        _fail('EC379_ONLY_DELIVERYAUDIT_AUDITHISTORICALSOURCEARCHIVE_READONLY',
              status='permission_denied')
    if (not AIRGAP_HISTORICAL_SOURCE_ARCHIVE.is_file() or
        AIRGAP_HISTORICAL_SOURCE_ARCHIVE.is_symlink()):
        _fail('EC379_FIXED_READONLY_CHILD_UNAVAILABLE',status='unavailable')
    scalars=(*EC369_SCALARS,*EC370_NEW_SCALARS,*EC371_NEW_SCALARS,
             *EC372_NEW_SCALARS,*EC373_NEW_SCALARS,*EC374_NEW_SCALARS,
             *EC375_NEW_SCALARS,*EC376_NEW_SCALARS,*EC377_NEW_SCALARS,
             *EC378_NEW_SCALARS,*EC379_NEW_SCALARS)
    repeats=(*EC369_REPEATS,*EC370_NEW_REPEATS,*EC371_NEW_REPEATS,
             *EC372_NEW_REPEATS,*EC373_NEW_REPEATS,*EC374_NEW_REPEATS,
             *EC375_NEW_REPEATS,*EC376_NEW_REPEATS,*EC377_NEW_REPEATS,
             *EC378_NEW_REPEATS,*EC379_NEW_REPEATS)
    if set(inputs)!=set(scalars)|{k for k,_ in repeats}:
        _fail('EC379_EXACT_LIVE_EC378_PARENT_AND_NEW_RECEIVER_INPUTS_REQUIRED')
    sha_ok=lambda v:type(v) is str and re.fullmatch('[0-9a-f]{64}',v) is not None and v!='0'*64
    path_ok=lambda v:type(v) is str and os.path.isabs(v) and os.path.normpath(v)==v and len(v)<=4000 and not v.startswith('//') and '\\' not in v and '\x00' not in v
    id_ok=lambda v:type(v) is str and re.fullmatch('[A-Za-z][A-Za-z0-9_.:-]{0,95}',v) is not None
    for k in scalars:
        v=inputs[k]
        if k.endswith('_utc'):
            if type(v) is not str or re.fullmatch(r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ',v) is None:
                _fail('EC379_FIXED_UTC_FORMAT_INVALID')
        elif k.endswith('_file'):
            if not path_ok(v):_fail('EC379_FIXED_ABSOLUTE_NORMALIZED_PATH_REQUIRED')
        elif k.endswith('_sha256'):
            if not sha_ok(v):_fail('EC379_FIXED_EXTERNAL_SHA_REQUIRED')
        elif k.startswith('minimum_'):
            if type(v) is not int or not 0<=v<=64:_fail('EC379_FIXED_PARENT_FLOOR_INVALID')
        elif k.startswith('claimed_') and not id_ok(v):
            _fail('EC379_FIXED_IDENTIFIER_INVALID')
    n=len(inputs['historical_directory_root_shas'])
    if not 1<=n<=3:_fail('EC379_FIXED_EPOCH_COUNT_INVALID')
    fixed_two={'institution_root_public_key_shas','witness_public_key_shas',
        'institution_claimed_ids','witness_claimed_ids',
        'expected_source_status_head_shas','expected_source_attestation_head_shas',
        'expected_witness_head_shas'}
    for name,_ in repeats:
        values=inputs[name]
        if name in fixed_two:lo=hi=2
        elif name=='historical_dual_handoff_shas':lo=0;hi=n-1
        elif name.startswith(('historical_','minimum_authority_','minimum_historical_')):
            lo=hi=n
        else:lo=1;hi=4
        if type(values) is not list or not lo<=len(values)<=hi:
            _fail('EC379_FIXED_PARENT_OR_EPOCH_STREAM_LENGTH_INVALID')
        if name.endswith('_ids'):
            if any(not id_ok(x) for x in values) or len(set(values))!=len(values):
                _fail('EC379_FIXED_ROLE_IDENTIFIER_DUPLICATE')
        elif name.startswith('minimum_'):
            cap=(4 if name=='minimum_historical_signed_source_counts' else
                 8 if name=='minimum_historical_authorized_registry_match_counts' else
                 8 if name=='minimum_historical_registry_signed_event_counts' else
                 20 if name=='minimum_historical_registry_dual_log_inclusion_counts' else
                 64 if 'tree_size' in name else
                 36 if 'disclosure_receipt' in name else
                 24 if 'disclosure_request' in name or 'custody_' in name or
                        'transparency_inclusion' in name else
                 7 if 'owner_' in name else 4 if 'revocation' in name else
                 5 if 'distribution' in name else 2147483647)
            if any(type(x) is not int or not 0<=x<=cap for x in values):
                _fail('EC379_FIXED_COUNT_OR_FLOOR_OUT_OF_BOUNDS')
        elif any(not sha_ok(x) and not (x is None and
                  name=='expected_source_attestation_head_shas') for x in values):
            _fail('EC379_FIXED_ORIGINAL_SHA_STREAM_INVALID')
        if (name.startswith('signed_') or name=='historical_dual_handoff_shas') and len(set(values))!=len(values):
            _fail('EC379_FIXED_SIGNED_HISTORY_REPLAY')
    for key in ('institution_root_public_key_shas','witness_public_key_shas'):
        if len(set(inputs[key]))!=2:_fail('EC379_FIXED_SOURCE_SIGNER_REUSE')
    argv=[sys.executable,'-I','-B',str(AIRGAP_HISTORICAL_SOURCE_ARCHIVE),
          'audit-historical-source-archive']
    for name in scalars:argv.extend(['--'+name.replace('_','-'),str(inputs[name])])
    for name,flag in repeats:
        for v in inputs[name]:argv.extend([flag,'none' if v is None else str(v)])
    rc,doc=_command(argv,timeout=180,max_output=180000)
    base={'schema','command','status','exit_code','offline_unresolved_exit_code',
          'sender_origin_path_required_or_read',
          'ec350_through_ec337_full_historical_parent_replay_performed',*EC379_NEGATIVES}
    if rc==2:
        extras={'historical_source_archive_bundle_original_sha256',
                'verified_live_parent_ec378_canonical_result_sha256',
                'receiver_verified_historical_source_inventory_sha256',
                'verified_old_ec351_signed_source_statement_count',
                'verified_old_ec351_signed_registry_authorization_match_count',
                'missing_old_ec351_channel_source_original_count',
                'historical_source_epoch_reviews',
                'local_pinned_ec351_source_signatures_and_old_registry_binding_consistent',
                *EC379_FLAGS}
        good=(type(doc) is dict and set(doc)==base|extras and
              doc.get('schema')=='ces.ec379.receiver_authentic_old_ec351_source_registry_binding_unresolved.v1' and
              doc.get('command')=='audit-historical-source-archive' and
              doc.get('exit_code')==2 and doc.get('offline_unresolved_exit_code')==2 and
              doc.get('sender_origin_path_required_or_read') is False and
              doc.get('ec350_through_ec337_full_historical_parent_replay_performed') is False and
              all(doc.get(k) is False for k in EC379_NEGATIVES) and
              all(type(doc.get(k)) is bool for k in EC379_FLAGS) and
              all(doc[k] is True for k in EC379_FLAGS[-2:]) and
              type(doc.get('local_pinned_ec351_source_signatures_and_old_registry_binding_consistent')) is bool and
              doc['local_pinned_ec351_source_signatures_and_old_registry_binding_consistent']==(
                  not any(doc[k] for k in EC379_FLAGS[:6])) and
              doc.get('status')==next((EC379_OUTCOMES[i] for i,k in enumerate(EC379_FLAGS)
                  if doc[k]),EC379_OUTCOMES[-1])+'_unresolved' and
              doc.get('historical_source_archive_bundle_original_sha256')==inputs[
                  'expected_historical_source_archive_bundle_sha256'] and
              sha_ok(doc.get('verified_live_parent_ec378_canonical_result_sha256')) and
              sha_ok(doc.get('receiver_verified_historical_source_inventory_sha256')) and
              type(doc.get('historical_source_epoch_reviews')) is list and
              len(doc['historical_source_epoch_reviews'])==n)
        fields={'epoch_index','actual_old_ec351_signed_source_original_count',
          'real_ec352_independent_registry_count',
          'real_signed_ec352_exact_source_authorization_match_count',
          'old_ec351_missing_claimed_tsa_channel_source_count',
          'old_ec351_source_original_inventory_sha256',
          'real_signed_ec352_source_binding_inventory_sha256',
          'real_signed_source_or_registry_revocation_or_fork_visible',
          'old_ec351_signed_source_claimed_issuer_role_collision_visible',
          'old_ec351_external_crl_ocsp_and_tsa_token_still_missing'}
        totals={
          'verified_old_ec351_signed_source_statement_count':
              'actual_old_ec351_signed_source_original_count',
          'verified_old_ec351_signed_registry_authorization_match_count':
              'real_signed_ec352_exact_source_authorization_match_count',
          'missing_old_ec351_channel_source_original_count':
              'old_ec351_missing_claimed_tsa_channel_source_count'}
        if good:
            for i,row in enumerate(doc['historical_source_epoch_reviews']):
                if (type(row) is not dict or set(row)!=fields or
                    type(row['epoch_index']) is not int or row['epoch_index']!=i or
                    row['real_ec352_independent_registry_count']!=2 or
                    any(type(row[k]) is not int or not 0<=row[k]<=8 for k in
                        totals.values()) or
                    row['actual_old_ec351_signed_source_original_count']>4 or
                    row['real_signed_ec352_exact_source_authorization_match_count']>
                         2*row['actual_old_ec351_signed_source_original_count'] or
                    any(type(row[k]) is not bool for k in (
                        'real_signed_source_or_registry_revocation_or_fork_visible',
                        'old_ec351_signed_source_claimed_issuer_role_collision_visible',
                        'old_ec351_external_crl_ocsp_and_tsa_token_still_missing')) or
                    row['old_ec351_external_crl_ocsp_and_tsa_token_still_missing'] is not True or
                    not sha_ok(row['old_ec351_source_original_inventory_sha256']) or
                    not sha_ok(row['real_signed_ec352_source_binding_inventory_sha256'])):
                    good=False;break
                if doc['local_pinned_ec351_source_signatures_and_old_registry_binding_consistent']:
                    if (row['old_ec351_source_original_inventory_sha256']!=inputs[
                          'historical_source_attestation_inventory_shas'][i] or
                        row['real_signed_ec352_source_binding_inventory_sha256']!=inputs[
                          'historical_source_registry_binding_inventory_shas'][i] or
                        row['actual_old_ec351_signed_source_original_count']<inputs[
                          'minimum_historical_signed_source_counts'][i] or
                        row['real_signed_ec352_exact_source_authorization_match_count']<inputs[
                          'minimum_historical_authorized_registry_match_counts'][i] or
                        row['old_ec351_missing_claimed_tsa_channel_source_count']!=0 or
                        row['real_signed_ec352_exact_source_authorization_match_count']!=
                          2*row['actual_old_ec351_signed_source_original_count']):
                        good=False;break
            for total,field in totals.items():
                if good and (type(doc.get(total)) is not int or doc[total]!=sum(
                       r[field] for r in doc['historical_source_epoch_reviews'])):
                    good=False;break
            if good and doc['local_pinned_ec351_source_signatures_and_old_registry_binding_consistent']:
                good=doc['receiver_verified_historical_source_inventory_sha256']==inputs[
                    'expected_retained_historical_source_inventory_sha256']
        if not good:_fail('EC379_FIXED_CHILD_SIGNED_SOURCE_REGISTRY_RESULT_SHAPE_INVALID',
                          status='unavailable')
    elif rc in (3,4,5):
        good=(type(doc) is dict and set(doc)==base|{'reason_code'} and
              doc.get('schema')=='ces.ec379.receiver_old_ec351_source_registry_denial.v1' and
              doc.get('command')=='audit-historical-source-archive' and
              doc.get('exit_code')==rc and STATUS_EXITS.get(doc.get('status'))==rc and
              doc.get('offline_unresolved_exit_code')==2 and
              doc.get('sender_origin_path_required_or_read') is False and
              doc.get('ec350_through_ec337_full_historical_parent_replay_performed') is False and
              all(doc.get(k) is False for k in EC379_NEGATIVES) and
              type(doc.get('reason_code')) is str and
              re.fullmatch('[A-Z][A-Z0-9_]{2,175}',doc['reason_code']) is not None)
        if not good:_fail('EC379_FIXED_CHILD_DENIAL_SHAPE_INVALID',status='unavailable')
    else:_fail('EC379_FIXED_CHILD_EXIT_CODE_INVALID',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc

