def audit_historical_timestamp_archive(action:str, mode:str, *,pretty:bool=False, **inputs)->int:
    if (action,mode)!=('DeliveryAudit','AuditHistoricalTimestampArchive'):
        _fail('EC380_ONLY_DELIVERYAUDIT_AUDITHISTORICALTIMESTAMPARCHIVE',
              status='permission_denied')
    if (not AIRGAP_HISTORICAL_TIMESTAMP_ARCHIVE.is_file() or
        AIRGAP_HISTORICAL_TIMESTAMP_ARCHIVE.is_symlink()):
        _fail('EC380_FIXED_OFFLINE_TIMESTAMP_CHILD_MISSING',status='unavailable')
    scalars=(*EC369_SCALARS,*EC370_NEW_SCALARS,*EC371_NEW_SCALARS,
       *EC372_NEW_SCALARS,*EC373_NEW_SCALARS,*EC374_NEW_SCALARS,
       *EC375_NEW_SCALARS,*EC376_NEW_SCALARS,*EC377_NEW_SCALARS,
       *EC378_NEW_SCALARS,*EC379_NEW_SCALARS,*EC380_NEW_SCALARS)
    repeats=(*EC369_REPEATS,*EC370_NEW_REPEATS,*EC371_NEW_REPEATS,
       *EC372_NEW_REPEATS,*EC373_NEW_REPEATS,*EC374_NEW_REPEATS,
       *EC375_NEW_REPEATS,*EC376_NEW_REPEATS,*EC377_NEW_REPEATS,
       *EC378_NEW_REPEATS,*EC379_NEW_REPEATS,*EC380_NEW_REPEATS)
    if set(inputs)!=set(scalars)|{k for k,_ in repeats}:
        _fail('EC380_EXACT_PARENT_AND_RETAINED_EPOCH_INPUTS_REQUIRED')
    sha_ok=lambda v:type(v) is str and re.fullmatch('[0-9a-f]{64}',v) is not None and v!='0'*64
    path_ok=lambda v:type(v) is str and os.path.isabs(v) and os.path.normpath(v)==v and len(v)<=4000 and not v.startswith('//') and '\\' not in v and '\x00' not in v
    id_ok=lambda v:type(v) is str and re.fullmatch('[A-Za-z][A-Za-z0-9_.:-]{0,95}',v) is not None
    for name in scalars:
        value=inputs[name]
        if name.endswith('_utc'):
            if type(value) is not str or re.fullmatch(r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ',value) is None:
                _fail('EC380_UTC_INPUT_INVALID')
        elif name.endswith('_file'):
            if not path_ok(value):_fail('EC380_ABSOLUTE_NORMALIZED_PATH_REQUIRED')
        elif name.endswith('_sha256'):
            if not sha_ok(value):_fail('EC380_INDEPENDENT_SHA256_REQUIRED')
        elif name.startswith('minimum_'):
            if type(value) is not int or not 0<=value<=64:_fail('EC380_PARENT_MINIMUM_INVALID')
        elif name.startswith('claimed_') and not id_ok(value):
            _fail('EC380_IDENTIFIER_INVALID')
    n=len(inputs['historical_directory_root_shas'])
    if not 1<=n<=3:_fail('EC380_EPOCH_BOUNDS_INVALID')
    fixed_two={'institution_root_public_key_shas','witness_public_key_shas',
       'institution_claimed_ids','witness_claimed_ids',
       'expected_source_status_head_shas','expected_source_attestation_head_shas',
       'expected_witness_head_shas'}
    for name,_ in repeats:
        v=inputs[name]
        if name in fixed_two:lo=hi=2
        elif name=='historical_dual_handoff_shas':lo=0;hi=n-1
        elif name.startswith(('historical_','minimum_authority_','minimum_historical_')):
            lo=hi=n
        else:lo=1;hi=4
        if type(v) is not list or not lo<=len(v)<=hi:
            _fail('EC380_FIXED_REPEATED_ARGUMENT_COUNT_INVALID')
        if name.endswith('_ids'):
            if any(not id_ok(x) for x in v):_fail('EC380_REPEATED_IDENTIFIER_INVALID')
        elif name.startswith('minimum_') or ('tree_size' in name) or ('sequence' in name):
            cap=(4 if name=='minimum_historical_verified_timestamp_counts' else
                 16 if name=='minimum_historical_signed_revocation_edge_counts' else
                 2147483647)
            if any(type(x) is not int or not 0<=x<=cap for x in v):
                _fail('EC380_REPEAT_MINIMUM_BOUNDS_INVALID')
        elif any(not sha_ok(x) and not (x is None and name=='expected_source_attestation_head_shas') for x in v):
            _fail('EC380_SIGNED_PARENT_SHA_STREAM_INVALID')
    for name in ('institution_root_public_key_shas','witness_public_key_shas'):
        if len(set(inputs[name]))!=2:_fail('EC380_INDEPENDENT_ROLE_KEYS_NOT_DISTINCT')
    argv=[sys.executable,'-I','-B',str(AIRGAP_HISTORICAL_TIMESTAMP_ARCHIVE),
          'audit-historical-timestamp-archive']
    for name in scalars:argv.extend(['--'+name.replace('_','-'),str(inputs[name])])
    for name,flag in repeats:
        for item in inputs[name]:argv.extend([flag,'none' if item is None else str(item)])
    rc,doc=_command(argv,timeout=180,max_output=280000)
    base={'schema','command','status','exit_code','offline_unresolved_exit_code',
          'sender_origin_path_required_or_read',
          'ec349_through_ec337_full_historical_parent_replay_performed',*EC380_NEGATIVES}
    if rc==2:
        extras={'historical_timestamp_archive_bundle_original_sha256',
          'verified_live_parent_ec379_canonical_result_sha256',
          'receiver_verified_historical_timestamp_inventory_sha256',
          'verified_real_rfc3161_timestamp_receipt_imprint_count',
          'signed_ocsp_matching_certificate_edge_count',
          'missing_authenticated_source_tsa_timestamp_count',
          'historical_timestamp_epoch_reviews',
          'local_signed_timestamp_and_revocation_inputs_consistent',*EC380_FLAGS}
        good=(type(doc) is dict and set(doc)==base|extras and
          doc.get('schema')=='ces.ec380.receiver_original_rfc3161_token_revocation_unresolved.v1' and
          doc.get('command')=='audit-historical-timestamp-archive' and
          doc.get('exit_code')==2 and doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec349_through_ec337_full_historical_parent_replay_performed') is False and
          all(doc.get(k) is False for k in EC380_NEGATIVES) and
          all(type(doc.get(k)) is bool for k in EC380_FLAGS) and
          all(doc[k] is True for k in EC380_FLAGS[-2:]) and
          type(doc.get('local_signed_timestamp_and_revocation_inputs_consistent')) is bool and
          doc['local_signed_timestamp_and_revocation_inputs_consistent']==(
             not any(doc[k] for k in EC380_FLAGS[:7])) and
          doc.get('status')==next((EC380_OUTCOMES[i] for i,k in enumerate(EC380_FLAGS)
                              if doc[k]),EC380_OUTCOMES[-1])+'_unresolved' and
          doc.get('historical_timestamp_archive_bundle_original_sha256')==inputs[
                              'expected_historical_timestamp_archive_bundle_sha256'] and
          sha_ok(doc.get('verified_live_parent_ec379_canonical_result_sha256')) and
          sha_ok(doc.get('receiver_verified_historical_timestamp_inventory_sha256')) and
          type(doc.get('historical_timestamp_epoch_reviews')) is list and
          len(doc['historical_timestamp_epoch_reviews'])==n)
        fields={'epoch_index','real_signed_rfc3161_token_and_ec349_receipt_imprint_count',
           'missing_ec350_signed_token_for_authenticated_source_count',
           'signed_ocsp_matching_certificate_edge_count',
           'timestamp_original_inventory_sha256','signed_revocation_original_inventory_sha256',
           'source_or_registry_signed_time_window_dispute',
           'signed_crl_revocation_or_missing_evidence',
           'signed_ocsp_revocation_or_missing_evidence',
           'complete_ec349_to_ec337_historic_parent_rebuilt'}
        total_fields={
           'verified_real_rfc3161_timestamp_receipt_imprint_count':
              'real_signed_rfc3161_token_and_ec349_receipt_imprint_count',
           'signed_ocsp_matching_certificate_edge_count':
              'signed_ocsp_matching_certificate_edge_count',
           'missing_authenticated_source_tsa_timestamp_count':
              'missing_ec350_signed_token_for_authenticated_source_count'}
        if good:
            for i,row in enumerate(doc['historical_timestamp_epoch_reviews']):
                if (type(row) is not dict or set(row)!=fields or
                    type(row['epoch_index']) is not int or row['epoch_index']!=i or
                    type(row['real_signed_rfc3161_token_and_ec349_receipt_imprint_count']) is not int or
                    not 0<=row['real_signed_rfc3161_token_and_ec349_receipt_imprint_count']<=4 or
                    type(row['missing_ec350_signed_token_for_authenticated_source_count']) is not int or
                    not 0<=row['missing_ec350_signed_token_for_authenticated_source_count']<=4 or
                    type(row['signed_ocsp_matching_certificate_edge_count']) is not int or
                    not 0<=row['signed_ocsp_matching_certificate_edge_count']<=16 or
                    any(type(row[k]) is not bool for k in (
                       'source_or_registry_signed_time_window_dispute',
                       'signed_crl_revocation_or_missing_evidence',
                       'signed_ocsp_revocation_or_missing_evidence')) or
                    row['complete_ec349_to_ec337_historic_parent_rebuilt'] is not False or
                    not sha_ok(row['timestamp_original_inventory_sha256']) or
                    not sha_ok(row['signed_revocation_original_inventory_sha256'])):
                    good=False;break
                if doc['local_signed_timestamp_and_revocation_inputs_consistent']:
                    if (row['timestamp_original_inventory_sha256']!=inputs[
                        'historical_timestamp_evidence_inventory_shas'][i] or
                        row['signed_revocation_original_inventory_sha256']!=inputs[
                        'historical_timestamp_revocation_inventory_shas'][i] or
                        row['real_signed_rfc3161_token_and_ec349_receipt_imprint_count']<inputs[
                        'minimum_historical_verified_timestamp_counts'][i] or
                        row['signed_ocsp_matching_certificate_edge_count']<inputs[
                        'minimum_historical_signed_revocation_edge_counts'][i] or
                        row['missing_ec350_signed_token_for_authenticated_source_count']!=0 or
                        any(row[k] for k in (
                          'source_or_registry_signed_time_window_dispute',
                          'signed_crl_revocation_or_missing_evidence',
                          'signed_ocsp_revocation_or_missing_evidence'))):
                        good=False;break
            for key,field in total_fields.items():
                if good and (type(doc.get(key)) is not int or doc[key]!=sum(
                       row[field] for row in doc['historical_timestamp_epoch_reviews'])):
                    good=False;break
            if good and doc['local_signed_timestamp_and_revocation_inputs_consistent']:
                good=doc['receiver_verified_historical_timestamp_inventory_sha256']==inputs[
                    'expected_retained_historical_timestamp_inventory_sha256']
        if not good:_fail('EC380_CHILD_TIMESTAMP_REPORT_SHAPE_INVALID',status='unavailable')
    elif rc in (3,4,5):
        good=(type(doc) is dict and set(doc)==base|{'reason_code'} and
          doc.get('schema')=='ces.ec380.receiver_rfc3161_original_denial.v1' and
          doc.get('command')=='audit-historical-timestamp-archive' and
          doc.get('exit_code')==rc and STATUS_EXITS.get(doc.get('status'))==rc and
          doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec349_through_ec337_full_historical_parent_replay_performed') is False and
          all(doc.get(k) is False for k in EC380_NEGATIVES) and
          type(doc.get('reason_code')) is str and
          re.fullmatch('[A-Z][A-Z0-9_]{2,175}',doc['reason_code']) is not None)
        if not good:_fail('EC380_CHILD_DENIAL_SHAPE_INVALID',status='unavailable')
    else:_fail('EC380_FIXED_CHILD_EXIT_CODE_INVALID',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc

