def audit_historical_ec349_channel_archive(action:str,mode:str,*,pretty:bool=False,**inputs)->int:
    if (action,mode)!=('DeliveryAudit','AuditHistoricalEC349ChannelArchive'):
        _fail('EC381_ONLY_DELIVERYAUDIT_AUDITHISTORICALEC349CHANNELARCHIVE',
              status='permission_denied')
    if (not AIRGAP_EC349_CHANNEL_ARCHIVE.is_file() or
        AIRGAP_EC349_CHANNEL_ARCHIVE.is_symlink()):
        _fail('EC381_FIXED_OFFLINE_CHILD_MISSING',status='unavailable')
    scalars=(*EC369_SCALARS,*EC370_NEW_SCALARS,*EC371_NEW_SCALARS,
       *EC372_NEW_SCALARS,*EC373_NEW_SCALARS,*EC374_NEW_SCALARS,
       *EC375_NEW_SCALARS,*EC376_NEW_SCALARS,*EC377_NEW_SCALARS,
       *EC378_NEW_SCALARS,*EC379_NEW_SCALARS,*EC380_NEW_SCALARS,
       *EC381_NEW_SCALARS)
    repeats=(*EC369_REPEATS,*EC370_NEW_REPEATS,*EC371_NEW_REPEATS,
       *EC372_NEW_REPEATS,*EC373_NEW_REPEATS,*EC374_NEW_REPEATS,
       *EC375_NEW_REPEATS,*EC376_NEW_REPEATS,*EC377_NEW_REPEATS,
       *EC378_NEW_REPEATS,*EC379_NEW_REPEATS,*EC380_NEW_REPEATS,
       *EC381_NEW_REPEATS)
    if set(inputs)!=set(scalars)|{k for k,_ in repeats}:
        _fail('EC381_EXACT_PARENT_AND_RECEIVER_INPUTS_REQUIRED')
    sha_ok=lambda v:type(v) is str and re.fullmatch('[0-9a-f]{64}',v) is not None and v!='0'*64
    path_ok=lambda v:type(v) is str and os.path.isabs(v) and os.path.normpath(v)==v and len(v)<=4000 and not v.startswith('//') and '\\' not in v and '\x00' not in v
    id_ok=lambda v:type(v) is str and re.fullmatch('[A-Za-z][A-Za-z0-9_.:-]{0,95}',v) is not None
    for name in scalars:
        value=inputs[name]
        if name.endswith('_utc'):
            if type(value) is not str or re.fullmatch(r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ',value) is None:
                _fail('EC381_UTC_INPUT_INVALID')
        elif name.endswith('_file'):
            if not path_ok(value):_fail('EC381_ABSOLUTE_NORMALIZED_PATH_REQUIRED')
        elif name.endswith('_sha256'):
            if not sha_ok(value):_fail('EC381_EXTERNALLY_RETAINED_SHA256_REQUIRED')
        elif name.startswith('minimum_'):
            if type(value) is not int or not 0<=value<=64:_fail('EC381_PARENT_MINIMUM_INVALID')
        elif name.startswith('claimed_') and not id_ok(value):
            _fail('EC381_IDENTIFIER_INVALID')
    n=len(inputs['historical_directory_root_shas'])
    if not 1<=n<=3:_fail('EC381_EPOCH_BOUNDS_INVALID')
    fixed_two={'institution_root_public_key_shas','witness_public_key_shas',
        'institution_claimed_ids','witness_claimed_ids',
        'expected_source_status_head_shas','expected_source_attestation_head_shas',
        'expected_witness_head_shas'}
    for name,_ in repeats:
        v=inputs[name]
        if name in fixed_two:lo=hi=2
        elif name=='historical_dual_handoff_shas':lo=0;hi=n-1
        elif name.startswith(('historical_','minimum_authority_','minimum_historical_')):
            lo=hi=n
        else:lo=1;hi=4
        if type(v) is not list or not lo<=len(v)<=hi:
            _fail('EC381_FIXED_REPEATED_ARGUMENT_COUNT_INVALID')
        if name.endswith('_ids'):
            if any(not id_ok(x) for x in v):_fail('EC381_REPEATED_IDENTIFIER_INVALID')
        elif name.startswith('minimum_') or 'tree_size' in name or 'sequence' in name:
            cap=(12 if name in ('minimum_historical_ec349_signed_receipt_counts',
                                'minimum_historical_ec349_signed_witness_counts') else
                 4 if name=='minimum_historical_verified_timestamp_counts' else
                 16 if name=='minimum_historical_signed_revocation_edge_counts' else
                 2147483647)
            if any(type(x) is not int or not 0<=x<=cap for x in v):
                _fail('EC381_REPEAT_MINIMUM_BOUNDS_INVALID')
        elif any(not sha_ok(x) and not (x is None and name=='expected_source_attestation_head_shas') for x in v):
            _fail('EC381_SHA_STREAM_INVALID')
    for name in ('institution_root_public_key_shas','witness_public_key_shas'):
        if len(set(inputs[name]))!=2:_fail('EC381_INDEPENDENT_ROLE_KEYS_NOT_DISTINCT')
    argv=[sys.executable,'-I','-B',str(AIRGAP_EC349_CHANNEL_ARCHIVE),
          'audit-historical-ec349-channel-archive']
    for name in scalars:argv.extend(['--'+name.replace('_','-'),str(inputs[name])])
    for name,flag in repeats:
        for item in inputs[name]:argv.extend([flag,'none' if item is None else str(item)])
    rc,doc=_command(argv,timeout=240,max_output=280000)
    base={'schema','command','status','exit_code','offline_unresolved_exit_code',
          'sender_origin_path_required_or_read',
          'ec349_through_ec337_full_historical_parent_replay_performed',*EC381_NEGATIVES}
    if rc==2:
        extra={'historical_ec349_channel_archive_bundle_original_sha256',
          'verified_live_parent_ec380_canonical_result_sha256',
          'receiver_verified_historical_ec349_channel_inventory_sha256',
          'real_signed_ec349_receipt_original_count',
          'real_signed_ec349_time_witness_original_count',
          'missing_ec349_channel_directory_count',
          'historical_ec349_channel_epoch_reviews',
          'local_root_authorized_receipt_witness_and_keeper_binding_consistent',*EC381_FLAGS}
        good=(type(doc) is dict and set(doc)==base|extra and
          doc.get('schema')=='ces.ec381.receiver_original_ec349_directory_receipts_witnesses_unresolved.v1' and
          doc.get('command')=='audit-historical-ec349-channel-archive' and
          doc.get('exit_code')==2 and doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec349_through_ec337_full_historical_parent_replay_performed') is False and
          all(doc.get(k) is False for k in EC381_NEGATIVES) and
          all(type(doc.get(k)) is bool for k in EC381_FLAGS) and
          all(doc.get(k) is True for k in EC381_FLAGS[-2:]) and
          type(doc.get('local_root_authorized_receipt_witness_and_keeper_binding_consistent')) is bool and
          doc['local_root_authorized_receipt_witness_and_keeper_binding_consistent']==(
             not any(doc[k] for k in EC381_FLAGS[:7])) and
          doc.get('status')==next((EC381_OUTCOMES[j] for j,k in enumerate(EC381_FLAGS)
              if doc[k]),EC381_OUTCOMES[-1])+'_unresolved' and
          doc.get('historical_ec349_channel_archive_bundle_original_sha256')==inputs[
              'expected_historical_ec349_channel_archive_bundle_sha256'] and
          sha_ok(doc.get('verified_live_parent_ec380_canonical_result_sha256')) and
          sha_ok(doc.get('receiver_verified_historical_ec349_channel_inventory_sha256')) and
          type(doc.get('historical_ec349_channel_epoch_reviews')) is list and
          len(doc['historical_ec349_channel_epoch_reviews'])==n)
        fields={'epoch_index','real_root_authorized_ec349_channel_count',
          'real_signed_ec349_receipt_original_count',
          'real_signed_ec349_time_witness_original_count',
          'missing_ec349_channel_directory_for_ec380_token_count',
          'real_ec348_replayed_keeper_channel_count',
          'signed_receipt_fork_expiry_revocation_or_nonhead_visible',
          'signed_witness_missing_claim_disagreement_or_peer_mismatch',
          'ec348_keeper_source_originals_missing_for_channel',
          'ec349_signed_authority_inventory_sha256',
          'ec349_signed_witness_inventory_sha256',
          'all_local_directory_receipt_witness_evidence_consistent'}
        if good:
            for i,row in enumerate(doc['historical_ec349_channel_epoch_reviews']):
                if (type(row) is not dict or set(row)!=fields or
                    type(row['epoch_index']) is not int or row['epoch_index']!=i or
                    any(type(row[k]) is not int or not 0<=row[k]<=cap for k,cap in (
                     ('real_root_authorized_ec349_channel_count',2),
                     ('real_signed_ec349_receipt_original_count',12),
                     ('real_signed_ec349_time_witness_original_count',12),
                     ('missing_ec349_channel_directory_for_ec380_token_count',4),
                     ('real_ec348_replayed_keeper_channel_count',2))) or
                    any(type(row[k]) is not bool for k in (
                     'signed_receipt_fork_expiry_revocation_or_nonhead_visible',
                     'signed_witness_missing_claim_disagreement_or_peer_mismatch',
                     'ec348_keeper_source_originals_missing_for_channel',
                     'all_local_directory_receipt_witness_evidence_consistent')) or
                    not sha_ok(row['ec349_signed_authority_inventory_sha256']) or
                    not sha_ok(row['ec349_signed_witness_inventory_sha256'])):
                    good=False;break
                if doc['local_root_authorized_receipt_witness_and_keeper_binding_consistent']:
                    if (row['ec349_signed_authority_inventory_sha256']!=inputs[
                           'historical_ec349_authority_inventory_shas'][i] or
                        row['ec349_signed_witness_inventory_sha256']!=inputs[
                           'historical_ec349_witness_inventory_shas'][i] or
                        row['real_signed_ec349_receipt_original_count']<inputs[
                           'minimum_historical_ec349_signed_receipt_counts'][i] or
                        row['real_signed_ec349_time_witness_original_count']<inputs[
                           'minimum_historical_ec349_signed_witness_counts'][i] or
                        row['missing_ec349_channel_directory_for_ec380_token_count']!=0 or
                        not row['all_local_directory_receipt_witness_evidence_consistent'] or
                        row['ec348_keeper_source_originals_missing_for_channel']):
                        good=False;break
            for count,field in (
                ('real_signed_ec349_receipt_original_count','real_signed_ec349_receipt_original_count'),
                ('real_signed_ec349_time_witness_original_count','real_signed_ec349_time_witness_original_count'),
                ('missing_ec349_channel_directory_count','missing_ec349_channel_directory_for_ec380_token_count')):
                if good and (type(doc.get(count)) is not int or doc[count]!=sum(
                        row[field] for row in doc['historical_ec349_channel_epoch_reviews'])):
                    good=False;break
            if good and doc['local_root_authorized_receipt_witness_and_keeper_binding_consistent']:
                good=doc['receiver_verified_historical_ec349_channel_inventory_sha256']==inputs[
                    'expected_retained_historical_ec349_channel_inventory_sha256']
        if not good:_fail('EC381_FIXED_CHILD_CHANNEL_REPORT_SHAPE_INVALID',status='unavailable')
    elif rc in (3,4,5):
        good=(type(doc) is dict and set(doc)==base|{'reason_code'} and
          doc.get('schema')=='ces.ec381.receiver_original_ec349_authority_denial.v1' and
          doc.get('command')=='audit-historical-ec349-channel-archive' and
          doc.get('exit_code')==rc and STATUS_EXITS.get(doc.get('status'))==rc and
          doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec349_through_ec337_full_historical_parent_replay_performed') is False and
          all(doc.get(k) is False for k in EC381_NEGATIVES) and
          type(doc.get('reason_code')) is str and
          re.fullmatch('[A-Z][A-Z0-9_]{2,175}',doc['reason_code']) is not None)
        if not good:_fail('EC381_FIXED_CHILD_DENIAL_SHAPE_INVALID',status='unavailable')
    else:_fail('EC381_FIXED_CHILD_EXIT_CODE_INVALID',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc

