def audit_historical_ec347_site_provenance_archive(action:str,mode:str,*,pretty:bool=False,**inputs)->int:
    if (action,mode)!=('DeliveryAudit','AuditHistoricalEC347SiteProvenanceArchive'):
        _fail('EC383_ONLY_DELIVERYAUDIT_AUDITHISTORICALEC347SITEPROVENANCEARCHIVE',
              status='permission_denied')
    if (not AIRGAP_EC347_SITE_PROVENANCE.is_file() or
        AIRGAP_EC347_SITE_PROVENANCE.is_symlink()):
        _fail('EC383_FIXED_OFFLINE_CHILD_MISSING',status='unavailable')
    scalars=(*EC369_SCALARS,*EC370_NEW_SCALARS,*EC371_NEW_SCALARS,
       *EC372_NEW_SCALARS,*EC373_NEW_SCALARS,*EC374_NEW_SCALARS,
       *EC375_NEW_SCALARS,*EC376_NEW_SCALARS,*EC377_NEW_SCALARS,
       *EC378_NEW_SCALARS,*EC379_NEW_SCALARS,*EC380_NEW_SCALARS,
       *EC381_NEW_SCALARS,*EC382_NEW_SCALARS,*EC383_NEW_SCALARS)
    repeats=(*EC369_REPEATS,*EC370_NEW_REPEATS,*EC371_NEW_REPEATS,
       *EC372_NEW_REPEATS,*EC373_NEW_REPEATS,*EC374_NEW_REPEATS,
       *EC375_NEW_REPEATS,*EC376_NEW_REPEATS,*EC377_NEW_REPEATS,
       *EC378_NEW_REPEATS,*EC379_NEW_REPEATS,*EC380_NEW_REPEATS,
       *EC381_NEW_REPEATS,*EC382_NEW_REPEATS,*EC383_NEW_REPEATS)
    if set(inputs)!=set(scalars)|{k for k,_ in repeats}:
        _fail('EC383_EXACT_LIVE_EC382_PARENT_AND_SIGNER_SITE_INPUTS_REQUIRED')
    sha_ok=lambda v:type(v) is str and re.fullmatch('[0-9a-f]{64}',v) is not None and v!='0'*64
    path_ok=lambda v:type(v) is str and os.path.isabs(v) and os.path.normpath(v)==v and len(v)<=4000 and not v.startswith('//') and '\\' not in v and '\x00' not in v
    id_ok=lambda v:type(v) is str and re.fullmatch('[A-Za-z][A-Za-z0-9_.:-]{0,95}',v) is not None
    for name in scalars:
        val=inputs[name]
        if name.endswith('_utc'):
            if type(val) is not str or re.fullmatch(r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ',val) is None:
                _fail('EC383_UTC_SCALAR_INVALID')
        elif name.endswith('_file'):
            if not path_ok(val):_fail('EC383_ABSOLUTE_NORMALIZED_RECEIVER_PATH_REQUIRED')
        elif name.endswith('_sha256'):
            if not sha_ok(val):_fail('EC383_INDEPENDENT_SHA256_COMPARATOR_REQUIRED')
        elif name.startswith('minimum_'):
            if type(val) is not int or not 0<=val<=64:_fail('EC383_PARENT_MINIMUM_INVALID')
        elif name.startswith('claimed_') and not id_ok(val):
            _fail('EC383_IDENTIFIER_INVALID')
    n=len(inputs['historical_directory_root_shas'])
    if not 1<=n<=3:_fail('EC383_HISTORIC_EPOCH_BOUNDS_INVALID')
    fixed_two={'institution_root_public_key_shas','witness_public_key_shas',
        'institution_claimed_ids','witness_claimed_ids',
        'expected_source_status_head_shas','expected_source_attestation_head_shas',
        'expected_witness_head_shas'}
    for name,_ in repeats:
        arr=inputs[name]
        if name in fixed_two:lo=hi=2
        elif name=='historical_dual_handoff_shas':lo=0;hi=n-1
        elif name.startswith(('historical_','minimum_authority_','minimum_historical_')):
            lo=hi=n
        else:lo=1;hi=4
        if type(arr) is not list or not lo<=len(arr)<=hi:
            _fail('EC383_FIXED_SIGNED_ORIGINAL_REPEATED_ARGUMENT_COUNT_INVALID')
        if name.endswith('_ids'):
            if any(not id_ok(x) for x in arr):_fail('EC383_REPEATED_IDENTIFIER_INVALID')
        elif name.startswith('minimum_') or 'tree_size' in name or 'sequence' in name:
            cap=(24 if name=='minimum_historical_ec348_signed_keeper_receipt_counts' else
                 8 if name=='minimum_historical_ec348_retested_ledger_counts' else
                 12 if name in ('minimum_historical_ec349_signed_receipt_counts',
                                'minimum_historical_ec349_signed_witness_counts') else
                 4 if name=='minimum_historical_verified_timestamp_counts' else
                 16 if name=='minimum_historical_signed_revocation_edge_counts' else
                 48 if name=='minimum_historical_ec346_signed_observation_counts' else
                 8 if name in ('minimum_historical_ec347_authorized_receiver_counts',
                               'minimum_historical_ec346_byte_retested_copy_counts') else
                 2147483647)
            if any(type(x) is not int or not 0<=x<=cap for x in arr):
                _fail('EC383_SIGNED_ORIGINAL_COUNT_FLOOR_INVALID')
        elif any(not sha_ok(x) and not (x is None and name=='expected_source_attestation_head_shas') for x in arr):
            _fail('EC383_INDEPENDENT_SHA256_COMPARATOR_STREAM_INVALID')
    for name in ('institution_root_public_key_shas','witness_public_key_shas'):
        if len(set(inputs[name]))!=2:_fail('EC383_INDEPENDENT_PUBLISHED_ROLE_KEYS_NOT_DISTINCT')
    argv=[sys.executable,'-I','-B',str(AIRGAP_EC347_SITE_PROVENANCE),
          'audit-historical-ec347-site-provenance-archive']
    for name in scalars:argv.extend(['--'+name.replace('_','-'),str(inputs[name])])
    for name,flag in repeats:
        for item in inputs[name]:argv.extend([flag,'none' if item is None else str(item)])
    rc,doc=_command(argv,timeout=420,max_output=440000)
    base={'schema','command','status','exit_code','offline_unresolved_exit_code',
       'sender_origin_path_required_or_read',
       'ec346_through_ec337_full_independent_original_historical_acceptance_performed',
       *EC383_NEGATIVES}
    if rc==2:
        extra={'verified_live_parent_ec382_canonical_result_sha256',
          'historical_ec347_site_archive_bundle_original_sha256',
          'receiver_verified_historical_ec347_site_inventory_sha256',
          'genuine_old_ec347_authorized_receiver_count',
          'genuine_old_ec346_signed_observation_original_count',
          'genuine_old_ec346_current_copy_local_retest_count',
          'historical_ec347_site_epoch_reviews',
          'local_ec347_challenger_receiver_ec346_signed_source_originals_consistent',
          *EC383_FLAGS}
        rows=doc.get('historical_ec347_site_epoch_reviews') if type(doc) is dict else None
        good=(type(doc) is dict and set(doc)==base|extra and
          doc.get('schema')=='ces.ec383.receiver_original_ec347_signer_ec346_copy_site_provenance_unresolved.v1' and
          doc.get('command')=='audit-historical-ec347-site-provenance-archive' and
          doc.get('exit_code')==2 and doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec346_through_ec337_full_independent_original_historical_acceptance_performed') is False and
          all(doc.get(k) is False for k in EC383_NEGATIVES) and
          all(type(doc.get(k)) is bool for k in EC383_FLAGS) and
          all(doc.get(k) is True for k in EC383_FLAGS[-2:]) and
          type(doc.get('local_ec347_challenger_receiver_ec346_signed_source_originals_consistent')) is bool and
          doc['local_ec347_challenger_receiver_ec346_signed_source_originals_consistent']==(
              not any(doc[k] for k in EC383_FLAGS[:7])) and
          doc.get('status')==next((EC383_OUTCOMES[i] for i,k in enumerate(EC383_FLAGS)
              if doc[k]),EC383_OUTCOMES[-1])+'_unresolved' and
          type(rows) is list and len(rows)==n and
          all(type(r) is dict and r.get('epoch_index')==i and
              type(r.get('verified_ec347_challenged_receiver_count')) is int and
              type(r.get('verified_ec346_signed_observation_original_count')) is int and
              type(r.get('explicit_current_copy_pair_local_retest_count')) is int and
              sha_ok(r.get('ec347_challenger_actor_original_inventory_sha256')) and
              sha_ok(r.get('ec346_signed_site_and_retested_byte_inventory_sha256'))
              for i,r in enumerate(rows)) and
          all(type(doc.get(k)) is int and doc[k]>=0 for k in (
              'genuine_old_ec347_authorized_receiver_count',
              'genuine_old_ec346_signed_observation_original_count',
              'genuine_old_ec346_current_copy_local_retest_count')) and
          all(sha_ok(doc.get(k)) for k in (
              'verified_live_parent_ec382_canonical_result_sha256',
              'historical_ec347_site_archive_bundle_original_sha256',
              'receiver_verified_historical_ec347_site_inventory_sha256')))
        if not good:_fail('EC383_FIXED_CHILD_SIGNER_SITE_REPORT_SHAPE_INVALID',status='unavailable')
    elif rc in (3,4,5):
        good=(type(doc) is dict and set(doc)==base|{'reason_code'} and
          doc.get('schema')=='ces.ec383.receiver_ec347_signer_ec346_copy_site_denial.v1' and
          doc.get('command')=='audit-historical-ec347-site-provenance-archive' and
          doc.get('exit_code')==rc and STATUS_EXITS.get(doc.get('status'))==rc and
          doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec346_through_ec337_full_independent_original_historical_acceptance_performed') is False and
          all(doc.get(k) is False for k in EC383_NEGATIVES) and
          type(doc.get('reason_code')) is str and
          re.fullmatch('[A-Z][A-Z0-9_]{2,175}',doc['reason_code']) is not None)
        if not good:_fail('EC383_FIXED_CHILD_DENIAL_SHAPE_INVALID',status='unavailable')
    else:_fail('EC383_FIXED_CHILD_EXIT_CODE_INVALID',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc


