def audit_historical_ec343_change_archive(action:str,mode:str,*,pretty:bool=False,**inputs)->int:
    if (action,mode)!=('DeliveryAudit','AuditHistoricalEC343ChangeArchive'):
        _fail('EC385_ONLY_DELIVERYAUDIT_AUDITHISTORICALEC343CHANGEARCHIVE',status='permission_denied')
    if not AIRGAP_EC343_CHANGE_ARCHIVE.is_file() or AIRGAP_EC343_CHANGE_ARCHIVE.is_symlink():
        _fail('EC385_FIXED_CHILD_MISSING',status='unavailable')
    if set(inputs)!=set(EC385_ALL_SCALARS)|{k for k,_ in EC385_ALL_REPEATS}:
        _fail('EC385_EXACT_INHERITED_ORIGINALS_AND_NEW_CHANGE_INPUTS_REQUIRED')
    sha_ok=lambda v:type(v) is str and re.fullmatch('[0-9a-f]{64}',v) is not None and v!='0'*64
    path_ok=lambda v:type(v) is str and os.path.isabs(v) and os.path.normpath(v)==v and len(v)<=4000 and not v.startswith('//') and '\\' not in v and '\x00' not in v
    id_ok=lambda v:type(v) is str and re.fullmatch('[A-Za-z][A-Za-z0-9_.:-]{0,95}',v) is not None
    for name in EC385_ALL_SCALARS:
        val=inputs[name]
        if name.endswith('_utc'):
            if type(val) is not str or re.fullmatch(r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ',val) is None:
                _fail('EC385_UTC_INPUT_INVALID')
        elif name.endswith('_file'):
            if not path_ok(val):_fail('EC385_ABSOLUTE_NORMALIZED_RECEIVER_PATH_REQUIRED')
        elif name.endswith('_sha256'):
            if not sha_ok(val):_fail('EC385_WHOLE_ORIGINAL_SHA_PIN_REQUIRED')
        elif name.startswith('minimum_'):
            if type(val) is not int or not 0<=val<=64:_fail('EC385_PARENT_MINIMUM_INVALID')
        elif name.startswith('claimed_') and not id_ok(val):
            _fail('EC385_IDENTIFIER_INVALID')
    n=len(inputs['historical_directory_root_shas'])
    if not 1<=n<=3:_fail('EC385_EPOCH_BOUNDS_INVALID')
    fixed_two={'institution_root_public_key_shas','witness_public_key_shas',
      'institution_claimed_ids','witness_claimed_ids',
      'expected_source_status_head_shas','expected_source_attestation_head_shas',
      'expected_witness_head_shas'}
    for name,_ in EC385_ALL_REPEATS:
        arr=inputs[name]
        if name in fixed_two:lo=hi=2
        elif name=='historical_dual_handoff_shas':lo=0;hi=n-1
        elif name.startswith(('historical_','minimum_authority_','minimum_historical_')):
            lo=hi=n
        else:lo=1;hi=4
        if type(arr) is not list or not lo<=len(arr)<=hi:
            _fail('EC385_REPEATED_ORIGINAL_CENSUS_INVALID')
        if name.endswith('_ids'):
            if any(not id_ok(v) for v in arr):_fail('EC385_REPEATED_SIGNER_IDENTIFIER_INVALID')
        elif name.startswith('minimum_') or 'tree_size' in name or 'sequence' in name:
            cap=(24 if name=='minimum_historical_ec348_signed_keeper_receipt_counts' else
                8 if name=='minimum_historical_ec348_retested_ledger_counts' else
                12 if name in ('minimum_historical_ec349_signed_receipt_counts',
                               'minimum_historical_ec349_signed_witness_counts') else
                4 if name=='minimum_historical_verified_timestamp_counts' else
                16 if name=='minimum_historical_signed_revocation_edge_counts' else
                48 if name=='minimum_historical_ec346_signed_observation_counts' else
                8 if name in ('minimum_historical_ec347_authorized_receiver_counts',
                              'minimum_historical_ec346_byte_retested_copy_counts') else
                16 if name in ('minimum_historical_ec344_signed_visibility_counts',
                               'minimum_historical_ec345_signed_challenge_counts') else
                64 if name=='minimum_historical_ec345_signed_offer_counts' else
                10 if name=='minimum_historical_ec342_signed_review_counts' else
                6 if name=='minimum_historical_ec343_signed_change_counts' else
                32 if name=='minimum_historical_ec343_signed_ack_counts' else
                2147483647)
            if any(type(v) is not int or not 0<=v<=cap for v in arr):
                _fail('EC385_SIGNED_COUNT_FLOOR_BOUNDS_INVALID')
        elif any(not sha_ok(v) and not (v is None and name=='expected_source_attestation_head_shas') for v in arr):
            _fail('EC385_HISTORICAL_ORIGINAL_SHA_FLOOR_INVALID')
    for name in ('institution_root_public_key_shas','witness_public_key_shas'):
        if len(set(inputs[name]))!=2:_fail('EC385_INDEPENDENT_PUBLISHED_ACTOR_KEYS_REQUIRED')
    argv=[sys.executable,'-I','-B',str(AIRGAP_EC343_CHANGE_ARCHIVE),
          'audit-historical-ec343-change-archive']
    for name in EC385_ALL_SCALARS:argv.extend(['--'+name.replace('_','-'),str(inputs[name])])
    for name,flag in EC385_ALL_REPEATS:
        for item in inputs[name]:argv.extend([flag,'none' if item is None else str(item)])
    rc,doc=_command(argv,timeout=480,max_output=480000)
    base={'schema','command','status','exit_code','offline_unresolved_exit_code',
          'sender_origin_path_required_or_read',
          'ec343_through_ec337_full_independent_original_historical_acceptance_performed',
          *EC385_NEGATIVES}
    if rc==2:
        extra={'verified_live_parent_ec384_canonical_result_sha256',
          'historical_ec343_change_archive_bundle_original_sha256',
          'receiver_verified_historical_ec343_change_inventory_sha256',
          'genuine_old_ec342_signed_review_original_count',
          'genuine_old_ec343_signed_change_original_count',
          'genuine_old_ec343_signed_receiver_ack_original_count',
          'historical_ec343_change_epoch_reviews',
          'local_ec342_approved_hold_ec343_signed_change_originals_consistent',*EC385_FLAGS}
        rows=doc.get('historical_ec343_change_epoch_reviews') if type(doc) is dict else None
        good=(type(doc) is dict and set(doc)==base|extra and
          doc.get('schema')=='ces.ec385.receiver_original_ec342_hold_ec343_signed_change_unresolved.v1' and
          doc.get('command')=='audit-historical-ec343-change-archive' and
          doc.get('exit_code')==2 and doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec343_through_ec337_full_independent_original_historical_acceptance_performed') is False and
          all(doc.get(k) is False for k in EC385_NEGATIVES) and
          all(type(doc.get(k)) is bool for k in EC385_FLAGS) and
          all(doc.get(k) is True for k in EC385_FLAGS[-2:]) and
          type(doc.get('local_ec342_approved_hold_ec343_signed_change_originals_consistent')) is bool and
          doc['local_ec342_approved_hold_ec343_signed_change_originals_consistent']==(
             not any(doc[k] for k in EC385_FLAGS[:7])) and
          doc.get('status')==next((EC385_OUTCOMES[i] for i,k in enumerate(EC385_FLAGS)
              if doc[k]),EC385_OUTCOMES[-1])+'_unresolved' and
          type(rows) is list and len(rows)==n and
          all(type(r) is dict and r.get('epoch_index')==i and
              all(type(r.get(k)) is int and r[k]>=0 for k in (
                'original_signed_ec342_reviewer_count',
                'original_signed_ec343_change_count',
                'original_signed_ec343_receiver_ack_count',
                'visible_signed_same_parent_branch_count',
                'missing_actual_original_source_channels')) and
              sha_ok(r.get('ec342_approved_hold_inventory_sha256')) and
              sha_ok(r.get('ec343_signed_change_inventory_sha256')) and
              type(r.get('local_original_ec342_approved_hold_and_ec343_signed_change_consistent')) is bool
              for i,r in enumerate(rows)) and
          all(type(doc.get(k)) is int and doc[k]>=0 for k in (
              'genuine_old_ec342_signed_review_original_count',
              'genuine_old_ec343_signed_change_original_count',
              'genuine_old_ec343_signed_receiver_ack_original_count')) and
          all(sha_ok(doc.get(k)) for k in (
              'verified_live_parent_ec384_canonical_result_sha256',
              'historical_ec343_change_archive_bundle_original_sha256',
              'receiver_verified_historical_ec343_change_inventory_sha256')))
        if not good:_fail('EC385_FIXED_CHILD_SIGNED_CHANGE_REPORT_SHAPE_INVALID',status='unavailable')
    elif rc in (3,4,5):
        good=(type(doc) is dict and set(doc)==base|{'reason_code'} and
          doc.get('schema')=='ces.ec385.receiver_original_ec342_ec343_change_denial.v1' and
          doc.get('command')=='audit-historical-ec343-change-archive' and
          doc.get('exit_code')==rc and STATUS_EXITS.get(doc.get('status'))==rc and
          doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec343_through_ec337_full_independent_original_historical_acceptance_performed') is False and
          all(doc.get(k) is False for k in EC385_NEGATIVES) and
          type(doc.get('reason_code')) is str and
          re.fullmatch('[A-Z][A-Z0-9_]{2,175}',doc['reason_code']) is not None)
        if not good:_fail('EC385_FIXED_CHILD_DENIAL_SHAPE_INVALID',status='unavailable')
    else:_fail('EC385_FIXED_CHILD_EXIT_CODE_INVALID',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc


