def audit_historical_ec340_rotation_archive(action:str,mode:str,*,pretty:bool=False,**inputs)->int:
    if (action,mode)!=('DeliveryAudit','AuditHistoricalEC340RotationArchive'):
        _fail('EC387_ONLY_DELIVERYAUDIT_AUDITHISTORICALEC340ROTATIONARCHIVE',status='permission_denied')
    if not AIRGAP_EC340_ROTATION_ARCHIVE.is_file() or AIRGAP_EC340_ROTATION_ARCHIVE.is_symlink():
        _fail('EC387_FIXED_CHILD_MISSING',status='unavailable')
    if set(inputs)!=set(EC387_ALL_SCALARS)|{k for k,_ in EC387_ALL_REPEATS}:
        _fail('EC387_EXACT_UNMODIFIED_PARENT_AND_ROTATION_ORIGINAL_INPUTS_REQUIRED')
    sha_ok=lambda v:type(v) is str and re.fullmatch('[0-9a-f]{64}',v) is not None and v!='0'*64
    path_ok=lambda v:type(v) is str and os.path.isabs(v) and os.path.normpath(v)==v and len(v)<=4000 and not v.startswith('//') and '\\' not in v and '\x00' not in v
    id_ok=lambda v:type(v) is str and re.fullmatch('[A-Za-z][A-Za-z0-9_.:-]{0,95}',v) is not None
    for name in EC387_ALL_SCALARS:
        val=inputs[name]
        if name.endswith('_utc'):
            if type(val) is not str or re.fullmatch(r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ',val) is None:
                _fail('EC387_UTC_INPUT_INVALID')
        elif name.endswith('_file'):
            if not path_ok(val):_fail('EC387_ABSOLUTE_NORMALIZED_RECEIVER_FILE_REQUIRED')
        elif name.endswith('_sha256'):
            if not sha_ok(val):_fail('EC387_WHOLE_ORIGINAL_SHA_REQUIRED')
        elif name.startswith('minimum_'):
            if type(val) is not int or not 0<=val<=64:_fail('EC387_PARENT_MINIMUM_INVALID')
        elif name.startswith('claimed_') and not id_ok(val):
            _fail('EC387_IDENTIFIER_INVALID')
    n=len(inputs['historical_directory_root_shas']) if type(inputs['historical_directory_root_shas']) is list else 0
    if not 1<=n<=3:_fail('EC387_EPOCH_BOUNDS_INVALID')
    fixed_two={'institution_root_public_key_shas','witness_public_key_shas',
      'institution_claimed_ids','witness_claimed_ids',
      'expected_source_status_head_shas','expected_source_attestation_head_shas',
      'expected_witness_head_shas'}
    caps={
     'minimum_historical_ec340_signed_edge_counts':16,
     'minimum_historical_ec340_signed_observation_counts':2,
     'minimum_historical_ec339_signed_grant_status_counts':16,
     'minimum_historical_ec341_signed_edge_counts':240,
     'minimum_historical_ec341_signed_observation_counts':30,
     'minimum_historical_ec341_verified_sibling_counts':16,
     'minimum_historical_ec348_signed_keeper_receipt_counts':24,
     'minimum_historical_ec348_retested_ledger_counts':8,
     'minimum_historical_verified_timestamp_counts':4,
     'minimum_historical_signed_revocation_edge_counts':16,
     'minimum_historical_ec346_signed_observation_counts':48,
     'minimum_historical_ec345_signed_offer_counts':64,
     'minimum_historical_ec342_signed_review_counts':10,
     'minimum_historical_ec343_signed_change_counts':6,
     'minimum_historical_ec343_signed_ack_counts':32}
    for name in ('minimum_historical_ec349_signed_receipt_counts',
                 'minimum_historical_ec349_signed_witness_counts'):caps[name]=12
    for name in ('minimum_historical_ec347_authorized_receiver_counts',
                 'minimum_historical_ec346_byte_retested_copy_counts'):caps[name]=8
    for name in ('minimum_historical_ec344_signed_visibility_counts',
                 'minimum_historical_ec345_signed_challenge_counts'):caps[name]=16
    for name,_ in EC387_ALL_REPEATS:
        arr=inputs[name]
        if name in fixed_two:lo=hi=2
        elif name=='historical_dual_handoff_shas':lo=0;hi=n-1
        elif name.startswith(('historical_','minimum_authority_','minimum_historical_')):lo=hi=n
        else:lo=1;hi=4
        if type(arr) is not list or not lo<=len(arr)<=hi:
            _fail('EC387_REPEATED_SIGNED_ORIGINAL_CENSUS_INVALID')
        if name.endswith('_ids'):
            if any(not id_ok(v) for v in arr):_fail('EC387_SIGNER_IDENTIFIER_INVALID')
        elif name.startswith('minimum_') or 'tree_size' in name or 'sequence' in name:
            if any(type(v) is not int or not 0<=v<=caps.get(name,2147483647) for v in arr):
                _fail('EC387_SIGNED_COUNT_FLOORS_INVALID')
        elif any(not sha_ok(v) and not (v is None and name=='expected_source_attestation_head_shas') for v in arr):
            _fail('EC387_ORIGINAL_SHA_FLOORS_INVALID')
    for name in ('institution_root_public_key_shas','witness_public_key_shas'):
        if len(set(inputs[name]))!=2:_fail('EC387_PUBLISHED_ACTOR_KEYS_NOT_DISTINCT')
    argv=[sys.executable,'-I','-B',str(AIRGAP_EC340_ROTATION_ARCHIVE),
          'audit-historical-ec340-rotation-archive']
    for name in EC387_ALL_SCALARS:argv.extend(['--'+name.replace('_','-'),str(inputs[name])])
    for name,flag in EC387_ALL_REPEATS:
        for value in inputs[name]:argv.extend([flag,'none' if value is None else str(value)])
    rc,doc=_command(argv,timeout=600,max_output=640000)
    base={'schema','command','status','exit_code','offline_unresolved_exit_code',
          'sender_origin_path_required_or_read',
          'ec340_to_ec337_full_independent_unmocked_external_acceptance_performed',
          *EC387_NEGATIVES}
    if rc==2:
        extra={'verified_live_parent_ec386_canonical_result_sha256',
          'historical_ec340_rotation_archive_original_sha256',
          'receiver_verified_old_ec340_signed_rotation_inventory_sha256',
          'genuine_old_ec340_signed_edge_count',
          'genuine_old_ec340_signed_observation_count',
          'genuine_old_ec339_signed_grant_status_count',
          'historical_ec340_rotation_epoch_reviews',
          'local_old_ec340_signed_rotation_ec341_conflict_parent_originals_consistent',*EC387_FLAGS}
        rows=doc.get('historical_ec340_rotation_epoch_reviews') if type(doc) is dict else None
        valid=(type(doc) is dict and set(doc)==base|extra and
          doc.get('schema')=='ces.ec387.receiver_old_ec340_epoch1_to_epoch2_original_rotation_unresolved.v1' and
          doc.get('command')=='audit-historical-ec340-rotation-archive' and
          doc.get('exit_code')==2 and doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec340_to_ec337_full_independent_unmocked_external_acceptance_performed') is False and
          all(doc.get(k) is False for k in EC387_NEGATIVES) and
          all(type(doc.get(k)) is bool for k in EC387_FLAGS) and
          all(doc.get(k) is True for k in EC387_FLAGS[-2:]) and
          type(doc.get('local_old_ec340_signed_rotation_ec341_conflict_parent_originals_consistent')) is bool and
          doc['local_old_ec340_signed_rotation_ec341_conflict_parent_originals_consistent']==(
              not any(doc[k] for k in EC387_FLAGS[:7])) and
          doc.get('status')==next((EC387_OUTCOMES[i] for i,k in enumerate(EC387_FLAGS)
              if doc[k]),EC387_OUTCOMES[-1])+'_unresolved' and
          type(rows) is list and len(rows)==n and
          all(type(r) is dict and r.get('epoch_index')==i and
              all(type(r.get(k)) is int and 0<=r[k]<=32 for k in (
               'old_ec340_eight_way_signed_role_edge_count',
               'old_ec340_signed_observation_count','old_ec339_signed_grant_status_count',
               'missing_authentic_ec340_original_channels')) and
              sha_ok(r.get('old_ec340_rotation_inventory_sha256')) and
              sha_ok(r.get('old_ec339_actor_history_inventory_sha256')) and
              type(r.get('local_old_ec340_rotation_and_ec341_conflict_parent_consistent')) is bool
              for i,r in enumerate(rows)) and
          all(type(doc.get(k)) is int and 0<=doc[k]<=96 for k in (
               'genuine_old_ec340_signed_edge_count',
               'genuine_old_ec340_signed_observation_count',
               'genuine_old_ec339_signed_grant_status_count')) and
          all(sha_ok(doc.get(k)) for k in (
               'verified_live_parent_ec386_canonical_result_sha256',
               'historical_ec340_rotation_archive_original_sha256',
               'receiver_verified_old_ec340_signed_rotation_inventory_sha256')))
        if not valid:_fail('EC387_FIXED_CHILD_SIGNED_ROTATION_SHAPE_INVALID',status='unavailable')
    elif rc in (3,4,5):
        valid=(type(doc) is dict and set(doc)==base|{'reason_code'} and
          doc.get('schema')=='ces.ec387.receiver_old_ec340_epoch_root_rotation_denial.v1' and
          doc.get('command')=='audit-historical-ec340-rotation-archive' and
          doc.get('exit_code')==rc and STATUS_EXITS.get(doc.get('status'))==rc and
          doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec340_to_ec337_full_independent_unmocked_external_acceptance_performed') is False and
          all(doc.get(k) is False for k in EC387_NEGATIVES) and
          type(doc.get('reason_code')) is str and
          re.fullmatch('[A-Z][A-Z0-9_]{2,175}',doc['reason_code']) is not None)
        if not valid:_fail('EC387_FIXED_CHILD_DENIAL_SHAPE_INVALID',status='unavailable')
    else:_fail('EC387_FIXED_CHILD_EXIT_CODE_INVALID',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc


