def audit_historical_ec339_independent_archive_heads(action:str,mode:str,*,pretty:bool=False,**inputs)->int:
    if (action,mode)!=('DeliveryAudit','AuditHistoricalEC339IndependentArchiveHeads'):
        _fail('EC390_ONLY_DELIVERYAUDIT_AUDITHISTORICALEC339INDEPENDENTARCHIVEHEADS',
              status='permission_denied')
    if (not AIRGAP_EC339_INDEPENDENT_ARCHIVE.is_file() or
        AIRGAP_EC339_INDEPENDENT_ARCHIVE.is_symlink()):
        _fail('EC390_FIXED_ISOLATED_SIGNED_HEAD_RECEIVER_MISSING',status='unavailable')
    if set(inputs)!=set(EC390_ALL_SCALARS)|{k for k,_ in EC390_ALL_REPEATS}:
        _fail('EC390_EXACT_INHERITED_AND_SIGNED_HEAD_RECEIPT_INPUTS_REQUIRED')
    sha_ok=lambda v:type(v) is str and re.fullmatch('[0-9a-f]{64}',v) is not None and v!='0'*64
    path_ok=lambda v:type(v) is str and os.path.isabs(v) and os.path.normpath(v)==v and len(v)<=4000 and not v.startswith('//') and '\\' not in v and '\x00' not in v
    id_ok=lambda v:type(v) is str and re.fullmatch('[A-Za-z][A-Za-z0-9_.:-]{0,95}',v) is not None
    for name in EC390_ALL_SCALARS:
        val=inputs[name]
        if name.endswith('_file'):
            if not path_ok(val):_fail('EC390_RECEIVER_SOURCE_ABSOLUTE_NORMAL_PATH_REQUIRED')
        elif name.endswith('_sha256'):
            if not sha_ok(val):_fail('EC390_SHA_PIN_OR_INDEPENDENT_RETENTION_INVALID')
        elif name.endswith('_utc'):
            if type(val) is not str or re.fullmatch(r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ',val) is None:
                _fail('EC390_UTC_INPUT_INVALID')
        elif name.startswith('claimed_') and not id_ok(val):
            _fail('EC390_IDENTIFIER_INVALID')
        elif name.startswith('minimum_') and (type(val) is not int or not 0<=val<=64):
            _fail('EC390_MINIMUM_INVALID')
    n=len(inputs['historical_directory_root_shas']) if type(inputs['historical_directory_root_shas']) is list else 0
    if not 1<=n<=3:_fail('EC390_MAX_THREE_EPOCHS_REQUIRED')
    fixed_two={'institution_root_public_key_shas','witness_public_key_shas',
       'institution_claimed_ids','witness_claimed_ids','expected_source_status_head_shas',
       'expected_source_attestation_head_shas','expected_witness_head_shas'}
    for name,_ in EC390_ALL_REPEATS:
        vals=inputs[name]
        if name in fixed_two:low=high=2
        elif name=='historical_dual_handoff_shas':low=0;high=n-1
        elif name.startswith(('historical_','minimum_authority_','minimum_historical_')):low=high=n
        else:low=1;high=4
        if type(vals) is not list or not low<=len(vals)<=high:
            _fail('EC390_EXACT_PER_EPOCH_OR_PARENT_REPEAT_COUNTS_REQUIRED')
        if name.endswith('_ids'):
            if any(not id_ok(v) for v in vals):_fail('EC390_SIGNER_ID_INVALID')
        elif name.startswith('minimum_') or 'tree_size' in name or 'sequence' in name:
            limit=2 if name=='minimum_historical_ec339_independent_signed_checkpoint_counts' else (
                16 if name=='minimum_historical_ec339_external_witness_custody_pair_counts' else 2147483647)
            if any(type(v) is not int or not 0<=v<=limit for v in vals):
                _fail('EC390_MINIMUM_SIGNED_ORIGINAL_COUNT_INVALID')
        elif any(not sha_ok(v) and not (v is None and name=='expected_source_attestation_head_shas') for v in vals):
            _fail('EC390_EPOCH_SIGNED_SHA_OR_INDEPENDENT_PIN_INVALID')
    if any(len(set(inputs[k]))!=2 for k in ('institution_root_public_key_shas','witness_public_key_shas')):
        _fail('EC390_PUBLISHED_OLD_KEYS_MUST_BE_DISTINCT')
    argv=[sys.executable,'-I','-B',str(AIRGAP_EC339_INDEPENDENT_ARCHIVE),
          'audit-historical-ec339-independent-archive-heads']
    for name in EC390_ALL_SCALARS:argv.extend(['--'+name.replace('_','-'),str(inputs[name])])
    for name,flag in EC390_ALL_REPEATS:
        for v in inputs[name]:argv.extend([flag,'none' if v is None else str(v)])
    rc,doc=_command(argv,timeout=600,max_output=640000)
    base={'schema','command','status','exit_code','offline_unresolved_exit_code',
        'sender_origin_path_required_or_read',
        'ec339_to_ec337_full_independent_unmocked_external_acceptance_performed',
        *EC390_NEGATIVES}
    if rc==2:
        extra={'verified_live_parent_ec389_canonical_result_sha256',
          'historical_independent_archive_original_sha256',
          'receiver_verified_independent_archive_inventory_sha256',
          'genuine_independent_signed_checkpoint_receipt_count',
          'historical_independent_archive_epoch_reviews',
          'local_independent_signed_archive_heads_and_receipts_consistent',*EC390_FLAGS}
        rows=doc.get('historical_independent_archive_epoch_reviews') if type(doc) is dict else None
        valid=(type(doc) is dict and set(doc)==base|extra and
          doc.get('schema')=='ces.ec390.receiver_independent_signed_archive_heads_receipts_unresolved.v1' and
          doc.get('command')=='audit-historical-ec339-independent-archive-heads' and
          doc.get('exit_code')==2 and doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec339_to_ec337_full_independent_unmocked_external_acceptance_performed') is False and
          all(doc.get(k) is False for k in EC390_NEGATIVES) and
          all(type(doc.get(k)) is bool for k in EC390_FLAGS) and
          all(doc[k] is True for k in EC390_FLAGS[-2:]) and
          type(doc.get('local_independent_signed_archive_heads_and_receipts_consistent')) is bool and
          doc['local_independent_signed_archive_heads_and_receipts_consistent']==(
             not any(doc[k] for k in EC390_FLAGS[:7])) and
          doc.get('status')==next((EC390_OUTCOMES[i] for i,k in enumerate(EC390_FLAGS)
             if doc[k]),EC390_OUTCOMES[-1])+'_unresolved' and
          type(rows) is list and len(rows)==n and
          all(type(r) is dict and r.get('epoch_index')==i and
              all(type(r.get(k)) is int and 0<=r[k]<=16 for k in (
                'genuine_independent_signed_checkpoint_pair_count',
                'visible_authentic_ec389_revocation_pair_count',
                'incomplete_independent_checkpoint_channels')) and
              sha_ok(r.get('independent_signed_head_inventory_sha256')) and
              sha_ok(r.get('independent_signed_receipt_inventory_sha256'))
              for i,r in enumerate(rows)) and
          type(doc.get('genuine_independent_signed_checkpoint_receipt_count')) is int and
          0<=doc['genuine_independent_signed_checkpoint_receipt_count']<=6 and
          all(sha_ok(doc.get(k)) for k in (
            'verified_live_parent_ec389_canonical_result_sha256',
            'historical_independent_archive_original_sha256',
            'receiver_verified_independent_archive_inventory_sha256')))
        if not valid:_fail('EC390_FIXED_SIGNED_CHILD_RESULT_INVALID',status='unavailable')
    elif rc in (3,4,5):
        valid=(type(doc) is dict and set(doc)==base|{'reason_code'} and
          doc.get('schema')=='ces.ec390.receiver_independent_archive_heads_receipts_denial.v1' and
          doc.get('command')=='audit-historical-ec339-independent-archive-heads' and
          doc.get('exit_code')==rc and STATUS_EXITS.get(doc.get('status'))==rc and
          doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec339_to_ec337_full_independent_unmocked_external_acceptance_performed') is False and
          all(doc.get(k) is False for k in EC390_NEGATIVES) and
          type(doc.get('reason_code')) is str and
          re.fullmatch('[A-Z][A-Z0-9_]{2,175}',doc['reason_code']) is not None)
        if not valid:_fail('EC390_FIXED_CHILD_DENIAL_INVALID',status='unavailable')
    else:_fail('EC390_FIXED_SIGNED_CHILD_EXIT_INVALID',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc


