EC392_NEGATIVES=('two_different_pinned_keeper_keys_prove_two_legally_independent_people_or_sites', 'locally_supplied_roster_root_sha_or_unsigned_inventory_is_historically_independently_retained', 'local_rfc3161_fixture_or_caller_pinned_root_proves_qualified_time_authority', 'signed_claimed_observed_utc_proves_original_offsite_physical_possession', 'cross_observer_gossip_proves_completeness_of_global_hidden_fork_census', 'valid_conflicting_signed_views_select_an_authoritative_fork_winner', 'secondary_ec391_parent_or_signed_source_is_allowed_to_be_caller_fabricated', 'signed_crossview_observation_extends_historical_ec339_issuer_authority', 'one_cms_token_proves_global_current_ocsp_or_exhaustive_revocation', 'receiver_has_issued_timestamp_or_accessed_private_keys_or_external_network', 'receiver_performed_native_powershell_git_ci_provider_or_cas_worm_write', 'full_unmocked_ec317_ec318_and_final_independent_user_acceptance_proven')
EC392_ALL_SCALARS=(*EC391_ALL_SCALARS,*EC392_NEW_SCALARS,'expected_retained_historical_ec339_crossview_inventory_sha256')
EC392_ALL_REPEATS=(*EC391_ALL_REPEATS,*EC392_NEW_REPEATS)

def audit_historical_ec339_crossview(action:str,mode:str,*,pretty:bool=False,**inputs)->int:
    if (action,mode)!=('DeliveryAudit','AuditHistoricalEC339CrossView'):
        _fail('EC392_FIXED_DELIVERY_AUDIT_MODE_REQUIRED',status='permission_denied')
    if not AIRGAP_EC339_CROSSVIEW.is_file() or AIRGAP_EC339_CROSSVIEW.is_symlink():
        _fail('EC392_FIXED_CROSSVIEW_CHILD_MISSING',status='unavailable')
    if set(inputs)!=set(EC392_ALL_SCALARS)|{k for k,_ in EC392_ALL_REPEATS}:
        _fail('EC392_EXACT_INHERITED_AND_CROSSVIEW_ARGUMENTS_REQUIRED')
    sha_ok=lambda v:type(v) is str and re.fullmatch('[0-9a-f]{64}',v) is not None and v!='0'*64
    path_ok=lambda v:type(v) is str and os.path.isabs(v) and os.path.normpath(v)==v and len(v)<=4000 and not v.startswith('//') and chr(92) not in v and chr(0) not in v
    id_ok=lambda v:type(v) is str and re.fullmatch('[A-Za-z][A-Za-z0-9_.:-]{0,95}',v) is not None
    for k in EC392_ALL_SCALARS:
        v=inputs[k]
        if k.endswith('_file'):
            if not path_ok(v):_fail('EC392_SIGNED_SOURCE_NORMAL_ABSOLUTE_PATH_REQUIRED')
        elif k.endswith('_sha256'):
            if not sha_ok(v):_fail('EC392_SHA_OR_OUTSIDE_PIN_INVALID')
        elif k.endswith('_utc'):
            if type(v) is not str or re.fullmatch(r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ',v) is None:
                _fail('EC392_UTC_FORMAT_INVALID')
        elif k.endswith('_observer_id') or k.startswith('claimed_'):
            if not id_ok(v):_fail('EC392_OBSERVER_ID_INVALID')
    if inputs['expected_outside_retained_ec392_primary_observer_id']==inputs[
       'expected_outside_retained_ec392_secondary_observer_id']:
        _fail('EC392_DUPLICATE_OBSERVER_NAMES',status='permission_denied')
    n=len(inputs['historical_directory_root_shas']) if type(inputs['historical_directory_root_shas']) is list else 0
    if not 1<=n<=3:_fail('EC392_ONE_TO_THREE_EPOCHS_REQUIRED')
    fixed_two={'institution_root_public_key_shas','witness_public_key_shas',
      'institution_claimed_ids','witness_claimed_ids','expected_source_status_head_shas',
      'expected_source_attestation_head_shas','expected_witness_head_shas'}
    for k,_ in EC392_ALL_REPEATS:
        seq=inputs[k]
        if k in fixed_two:low=high=2
        elif k=='historical_dual_handoff_shas':low=0;high=n-1
        elif k.startswith(('historical_','secondary_','minimum_authority_','minimum_historical_','minimum_secondary_')):
            low=high=n
        else:low=1;high=4
        if type(seq) is not list or not low<=len(seq)<=high:
            _fail('EC392_PARENT_OR_CROSSVIEW_REPEAT_COUNT_INVALID')
        if k.endswith('_ids'):
            if any(not id_ok(v) for v in seq):_fail('EC392_INVALID_SENDER_ID')
        elif k.startswith('minimum_') or 'tree_size' in k or 'sequence' in k:
            limit=(4 if k=='minimum_historical_ec339_crossview_timestamped_checkpoint_counts'
                   else 2 if k in ('minimum_secondary_ec391_prior_timestamped_head_counts',
                     'minimum_historical_ec339_prior_timestamped_head_counts',
                     'minimum_historical_ec339_independent_signed_checkpoint_counts')
                   else 16 if k=='minimum_historical_ec339_external_witness_custody_pair_counts'
                   else 2147483647)
            if any(type(v) is not int or not 0<=v<=limit for v in seq):
                _fail('EC392_SIGNED_COUNT_FLOOR_OUT_OF_BOUNDS')
        elif any(not sha_ok(v) and not (v is None and k=='expected_source_attestation_head_shas') for v in seq):
            _fail('EC392_SIGNED_SOURCE_SHA_INVALID')
    if any(len(set(inputs[k]))!=2 for k in ('institution_root_public_key_shas',
                                              'witness_public_key_shas')):
        _fail('EC392_COPIED_OLD_ROOT_OR_WITNESS_KEYS')
    argv=[sys.executable,'-I','-B',str(AIRGAP_EC339_CROSSVIEW),
          'audit-historical-ec339-crossview']
    for k in EC392_ALL_SCALARS:argv.extend(['--'+k.replace('_','-'),str(inputs[k])])
    for k,flag in EC392_ALL_REPEATS:
        for value in inputs[k]:argv.extend([flag,'none' if value is None else str(value)])
    rc,doc=_command(argv,timeout=1000,max_output=900000)
    base={'schema','command','status','exit_code','offline_unresolved_exit_code',
        'sender_origin_path_required_or_read',
        'ec339_to_ec337_full_independent_unmocked_external_acceptance_performed',
        *EC392_NEGATIVES}
    if rc==2:
        extra={'verified_primary_ec391_report_sha256','verified_secondary_ec391_report_sha256',
           'verified_live_parent_ec390_canonical_result_sha256',
           'receiver_verified_crossview_inventory_sha256','historical_crossview_original_sha256',
           'cryptographically_timestamped_crossview_checkpoint_count',
           'valid_distinct_same_keeper_signed_equivocation_count',
           'historical_crossview_epoch_reviews','visible_crossview_conflict_cases',
           'local_two_observer_signed_views_and_crossview_receipts_consistent',*EC392_FLAGS}
        reviews=doc.get('historical_crossview_epoch_reviews') if type(doc) is dict else None
        cases=doc.get('visible_crossview_conflict_cases') if type(doc) is dict else None
        valid=(type(doc) is dict and set(doc)==base|extra and
          doc.get('schema')=='ces.ec392.receiver_dual_offsite_crossview_unresolved.v1' and
          doc.get('command')=='audit-historical-ec339-crossview' and
          doc.get('exit_code')==2 and doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec339_to_ec337_full_independent_unmocked_external_acceptance_performed') is False and
          all(doc.get(k) is False for k in EC392_NEGATIVES) and
          all(type(doc.get(k)) is bool for k in EC392_FLAGS) and all(doc[k] is True for k in EC392_FLAGS[-2:]) and
          type(doc.get('local_two_observer_signed_views_and_crossview_receipts_consistent')) is bool and
          doc['local_two_observer_signed_views_and_crossview_receipts_consistent']==(
             not any(doc[k] for k in EC392_FLAGS[:9])) and
          doc.get('status')==next((EC392_OUTCOMES[i] for i,k in enumerate(EC392_FLAGS)
             if doc[k]),EC392_OUTCOMES[-1])+'_unresolved' and
          type(reviews) is list and len(reviews)==n and all(
            type(r) is dict and set(r)=={
             'epoch_index','timestamp_authenticated_crossview_count',
             'crossview_signed_checkpoint_inventory_sha256',
             'crossview_rfc3161_token_inventory_sha256',
             'signed_snapshot_disagreements','nonprefix_signed_split_views',
             'signed_self_equivocation_cases'} and
            type(r['epoch_index']) is int and r['epoch_index']==i and
            type(r['timestamp_authenticated_crossview_count']) is int and
            0<=r['timestamp_authenticated_crossview_count']<=4 and
            all(type(r[k]) is int and 0<=r[k]<=2 for k in (
              'signed_snapshot_disagreements','nonprefix_signed_split_views',
              'signed_self_equivocation_cases')) and
            sha_ok(r['crossview_signed_checkpoint_inventory_sha256']) and
            sha_ok(r['crossview_rfc3161_token_inventory_sha256'])
            for i,r in enumerate(reviews)) and
          type(cases) is list and len(cases)<=2*n and all(
            type(c) is dict and type(c.get('epoch_index')) is int and
            0<=c['epoch_index']<n and id_ok(c.get('tsa_channel_id')) and
            c.get('primary_observer_id')==inputs['expected_outside_retained_ec392_primary_observer_id'] and
            c.get('secondary_observer_id')==inputs['expected_outside_retained_ec392_secondary_observer_id']
            for c in cases) and
          type(doc.get('cryptographically_timestamped_crossview_checkpoint_count')) is int and
          doc['cryptographically_timestamped_crossview_checkpoint_count']==sum(
             r['timestamp_authenticated_crossview_count'] for r in reviews) and
          type(doc.get('valid_distinct_same_keeper_signed_equivocation_count')) is int and
          doc['valid_distinct_same_keeper_signed_equivocation_count']==sum(
             r['signed_self_equivocation_cases'] for r in reviews) and
          all(sha_ok(doc.get(k)) for k in (
            'verified_primary_ec391_report_sha256','verified_secondary_ec391_report_sha256',
            'verified_live_parent_ec390_canonical_result_sha256',
            'receiver_verified_crossview_inventory_sha256',
            'historical_crossview_original_sha256')))
        if not valid:_fail('EC392_CHILD_SIGNED_REPORT_SCHEMA_DENIED',status='unavailable')
    elif rc in (3,4,5):
        valid=(type(doc) is dict and set(doc)==base|{'reason_code'} and
          doc.get('schema')=='ces.ec392.receiver_dual_offsite_crossview_denial.v1' and
          doc.get('command')=='audit-historical-ec339-crossview' and
          doc.get('exit_code')==rc and STATUS_EXITS.get(doc.get('status'))==rc and
          doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec339_to_ec337_full_independent_unmocked_external_acceptance_performed') is False and
          all(doc.get(k) is False for k in EC392_NEGATIVES) and
          type(doc.get('reason_code')) is str and
          re.fullmatch('[A-Z][A-Z0-9_]{2,175}',doc['reason_code']) is not None)
        if not valid:_fail('EC392_CHILD_DENIAL_SCHEMA_INVALID',status='unavailable')
    else:_fail('EC392_CHILD_EXIT_INVALID',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc


# EC393: independent preexisting two-party custody originals + timestamped log anchor.
AIRGAP_EC339_CUSTODY_ANCHOR=ROOT/'scripts'/'ces_cas_historical_custody_anchor.py'
