EC393_NEGATIVES=('newly_presented_sender_receiver_public_keys_prove_separate_legal_custody_sites', 'caller_chosen_dispute_cutoff_or_roster_sha_is_genuinely_external_pre_dispute_evidence', 'locally_generated_log_head_or_rfc3161_fixture_proves_qualified_independent_tsa', 'signed_handoff_utc_or_log_claimed_integrated_utc_is_calibrated_true_wall_clock', 'rfc6962_consistency_with_two_heads_proves_absence_of_other_forked_heads', 'merkle_inclusion_and_cms_token_prove_physical_worm_or_external_retention', 'contradictory_signed_custody_claims_choose_an_authoritative_history', 'supplied_crls_prove_exhaustive_online_revocation_or_current_ocsp', 'ec393_receiver_may_generate_a_custody_receipt_log_head_or_timestamp', 'receiver_performed_signing_network_cas_worm_provider_git_ci_or_powershell_write', 'ec339_issuer_authority_is_extended_by_newer_custody_claims', 'unmocked_external_ec317_ec318_corpus_and_final_user_acceptance_proven')
EC393_ALL_SCALARS=(*EC392_ALL_SCALARS,*EC393_NEW_SCALARS,
                  'expected_retained_historical_ec339_custody_anchor_inventory_sha256')
