def audit_historical_ec339_custody_anchor(action:str,mode:str,*,pretty:bool=False,**inputs)->int:
    if (action,mode)!=('DeliveryAudit','AuditHistoricalEC339CustodyAnchor'):
        _fail('EC393_FIXED_READONLY_AUDIT_ACTION_MODE_REQUIRED',status='permission_denied')
    if not AIRGAP_EC339_CUSTODY_ANCHOR.is_file() or AIRGAP_EC339_CUSTODY_ANCHOR.is_symlink():
        _fail('EC393_FIXED_INDEPENDENT_CHILD_MISSING',status='unavailable')
    if set(inputs)!=set(EC393_ALL_SCALARS)|{k for k,_ in EC393_ALL_REPEATS}:
        _fail('EC393_EXACT_EC392_AND_ANCHOR_PINS_REQUIRED')
    sha_ok=lambda v:type(v) is str and re.fullmatch('[0-9a-f]{64}',v) is not None and v!='0'*64
    path_ok=lambda v:type(v) is str and os.path.isabs(v) and os.path.normpath(v)==v and len(v)<=4000 and not v.startswith('//') and chr(92) not in v and chr(0) not in v
    id_ok=lambda v:type(v) is str and re.fullmatch('[A-Za-z][A-Za-z0-9_.:-]{0,95}',v) is not None
    for k in EC393_ALL_SCALARS:
        v=inputs[k]
        if k.endswith('_file'):
            if not path_ok(v):_fail('EC393_NORMAL_ABSOLUTE_SOURCE_REQUIRED')
        elif k.endswith('_sha256'):
            if not sha_ok(v):_fail('EC393_OUTSIDE_PIN_SHA_REQUIRED')
        elif k.endswith('_utc'):
            if type(v) is not str or re.fullmatch(r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ',v) is None:
                _fail('EC393_CANONICAL_UTC_INPUT_REQUIRED')
        elif k.endswith('_observer_id') or k.startswith('claimed_'):
            if not id_ok(v):_fail('EC393_OUTSIDE_OBSERVER_ID_INVALID')
    if inputs['expected_outside_retained_ec392_primary_observer_id']==inputs[
       'expected_outside_retained_ec392_secondary_observer_id']:
        _fail('EC393_DUPLICATE_OBSERVERS',status='permission_denied')
    n=len(inputs['historical_directory_root_shas']) if type(inputs['historical_directory_root_shas']) is list else 0
    if not 1<=n<=3:_fail('EC393_ONE_TO_THREE_EPOCHS_REQUIRED')
    fixed_two={'institution_root_public_key_shas','witness_public_key_shas',
      'institution_claimed_ids','witness_claimed_ids','expected_source_status_head_shas',
      'expected_source_attestation_head_shas','expected_witness_head_shas'}
    for k,_ in EC393_ALL_REPEATS:
        seq=inputs[k]
        if k in fixed_two:low=high=2
        elif k=='historical_dual_handoff_shas':low=0;high=n-1
        elif k.startswith(('historical_','secondary_','minimum_authority_',
                           'minimum_historical_','minimum_secondary_')):low=high=n
        else:low=1;high=4
        if type(seq) is not list or not low<=len(seq)<=high:
            _fail('EC393_PARENT_OR_NEW_REPEAT_COUNT_INVALID')
        if k.endswith('_ids'):
            if any(not id_ok(v) for v in seq):_fail('EC393_SIGNER_ID_INVALID')
        elif k.startswith('minimum_') or 'tree_size' in k or 'sequence' in k:
            limit=(4 if k in ('minimum_historical_ec339_pre_cutoff_log_anchored_receipt_counts',
                     'minimum_historical_ec339_crossview_timestamped_checkpoint_counts') else
                   2 if k in ('minimum_secondary_ec391_prior_timestamped_head_counts',
                     'minimum_historical_ec339_prior_timestamped_head_counts',
                     'minimum_historical_ec339_independent_signed_checkpoint_counts') else
                   16 if k=='minimum_historical_ec339_external_witness_custody_pair_counts'
                   else 2147483647)
            if any(type(v) is not int or not 0<=v<=limit for v in seq):
                _fail('EC393_MINIMUM_BOUND_INVALID')
        elif any(not sha_ok(v) and not (v is None and k=='expected_source_attestation_head_shas')
                 for v in seq):_fail('EC393_SHA_PIN_INVALID')
    if any(len(set(inputs[k]))!=2 for k in ('institution_root_public_key_shas',
                                              'witness_public_key_shas')):
        _fail('EC393_OLD_SIGNER_KEY_REUSE')
    argv=[sys.executable,'-I','-B',str(AIRGAP_EC339_CUSTODY_ANCHOR),
          'audit-historical-ec339-custody-anchor']
    for k in EC393_ALL_SCALARS:argv.extend(['--'+k.replace('_','-'),str(inputs[k])])
    for k,flag in EC393_ALL_REPEATS:
        for v in inputs[k]:argv.extend([flag,'none' if v is None else str(v)])
    rc,doc=_command(argv,timeout=1200,max_output=1000000)
    base={'schema','command','status','exit_code','offline_unresolved_exit_code',
          'sender_origin_path_required_or_read',
          'ec339_to_ec337_full_independent_unmocked_external_acceptance_performed',
          *EC393_NEGATIVES}
    if rc==2:
        extra={'verified_live_ec392_report_sha256','verified_live_ec392_inventory_sha256',
            'historical_custody_anchor_original_sha256',
            'receiver_verified_custody_anchor_inventory_sha256',
            'cryptographically_bounded_pre_cutoff_handoff_count',
            'valid_distinct_dual_countersigned_conflict_count',
            'signed_log_prior_and_current_sha256',
            'signed_rfc6962_append_only_extension_verified','custody_anchor_epoch_reviews',
            'visible_custody_conflict_cases',
            'local_custody_counter_signatures_log_and_timestamps_consistent',*EC393_FLAGS}
        rows=doc.get('custody_anchor_epoch_reviews') if type(doc) is dict else None
        cases=doc.get('visible_custody_conflict_cases') if type(doc) is dict else None
        heads=doc.get('signed_log_prior_and_current_sha256') if type(doc) is dict else None
        valid=(type(doc) is dict and set(doc)==base|extra and
          doc.get('schema')=='ces.ec393.receiver_countersigned_custody_log_anchor_unresolved.v1' and
          doc.get('command')=='audit-historical-ec339-custody-anchor' and
          doc.get('exit_code')==2 and doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec339_to_ec337_full_independent_unmocked_external_acceptance_performed') is False and
          all(doc.get(k) is False for k in EC393_NEGATIVES) and
          all(type(doc.get(k)) is bool for k in EC393_FLAGS) and
          all(doc[k] is True for k in EC393_FLAGS[-2:]) and
          type(doc.get('local_custody_counter_signatures_log_and_timestamps_consistent')) is bool and
          doc['local_custody_counter_signatures_log_and_timestamps_consistent']==(
             not any(doc[k] for k in EC393_FLAGS[:8])) and
          type(doc.get('signed_rfc6962_append_only_extension_verified')) is bool and
          doc.get('status')==next((EC393_OUTCOMES[i] for i,k in enumerate(EC393_FLAGS)
             if doc[k]),EC393_OUTCOMES[-1])+'_unresolved' and
          type(heads) is list and len(heads)==2 and
          all(h is None or sha_ok(h) for h in heads) and
          type(rows) is list and len(rows)==n and
          all(type(r) is dict and set(r)=={'epoch_index',
              'pre_cutoff_log_anchored_handoff_count','genuine_double_countersigned_conflict_cases',
              'countersigned_receipt_inventory_sha256','rfc6962_inclusion_inventory_sha256'} and
              type(r['epoch_index']) is int and r['epoch_index']==i and
              all(type(r[k]) is int and 0<=r[k]<=4 for k in (
                 'pre_cutoff_log_anchored_handoff_count',
                 'genuine_double_countersigned_conflict_cases')) and
              sha_ok(r['countersigned_receipt_inventory_sha256']) and
              sha_ok(r['rfc6962_inclusion_inventory_sha256'])
              for i,r in enumerate(rows)) and
          type(cases) is list and len(cases)<=4*n and all(
              type(c) is dict and set(c)=={'epoch_index','tsa_channel_id','observer_id',
                 'primary_countersigned_receipt_original_sha256',
                 'alternate_countersigned_receipt_original_sha256',
                 'alternate_inclusion_authenticated'} and
              type(c['epoch_index']) is int and 0<=c['epoch_index']<n and
              id_ok(c['tsa_channel_id']) and
              c['observer_id'] in (
                inputs['expected_outside_retained_ec392_primary_observer_id'],
                inputs['expected_outside_retained_ec392_secondary_observer_id']) and
              sha_ok(c['primary_countersigned_receipt_original_sha256']) and
              sha_ok(c['alternate_countersigned_receipt_original_sha256']) and
              type(c['alternate_inclusion_authenticated']) is bool
              for c in cases) and
          type(doc.get('cryptographically_bounded_pre_cutoff_handoff_count')) is int and
          doc['cryptographically_bounded_pre_cutoff_handoff_count']==sum(
              r['pre_cutoff_log_anchored_handoff_count'] for r in rows) and
          type(doc.get('valid_distinct_dual_countersigned_conflict_count')) is int and
          doc['valid_distinct_dual_countersigned_conflict_count']==sum(
              r['genuine_double_countersigned_conflict_cases'] for r in rows) and
          all(sha_ok(doc.get(k)) for k in (
               'verified_live_ec392_report_sha256','verified_live_ec392_inventory_sha256',
               'historical_custody_anchor_original_sha256',
               'receiver_verified_custody_anchor_inventory_sha256')))
        if not valid:_fail('EC393_CHILD_SIGNED_REPORT_SCHEMA_DENIED',status='unavailable')
    elif rc in (3,4,5):
        valid=(type(doc) is dict and set(doc)==base|{'reason_code'} and
          doc.get('schema')=='ces.ec393.receiver_custody_log_anchor_denial.v1' and
          doc.get('command')=='audit-historical-ec339-custody-anchor' and
          doc.get('exit_code')==rc and STATUS_EXITS.get(doc.get('status'))==rc and
          doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec339_to_ec337_full_independent_unmocked_external_acceptance_performed') is False and
          all(doc.get(k) is False for k in EC393_NEGATIVES) and
          type(doc.get('reason_code')) is str and
          re.fullmatch('[A-Z][A-Z0-9_]{2,175}',doc['reason_code']) is not None)
        if not valid:_fail('EC393_CHILD_DENIAL_SCHEMA_INVALID',status='unavailable')
    else:_fail('EC393_CHILD_EXIT_INVALID',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc

