def audit_historical_ec339_registered_witness(action:str,mode:str,*,pretty:bool=False,**inputs)->int:
    if (action,mode)!=('DeliveryAudit','AuditHistoricalEC339RegisteredWitness'):
        _fail('EC394_FIXED_READONLY_AUDIT_ACTION_MODE_REQUIRED',status='permission_denied')
    if not AIRGAP_EC339_REGISTERED_WITNESS.is_file() or AIRGAP_EC339_REGISTERED_WITNESS.is_symlink():
        _fail('EC394_ISOLATED_READONLY_RECEIVER_MISSING',status='unavailable')
    if set(inputs)!=set(EC394_ALL_SCALARS)|{k for k,_ in EC394_ALL_REPEATS}:
        _fail('EC394_EXACT_PARENT_AND_OUTSIDE_PINS_REQUIRED')
    sha_ok=lambda x:type(x) is str and re.fullmatch('[0-9a-f]{64}',x) is not None and x!='0'*64
    key_ok=lambda x:type(x) is str and re.fullmatch('[0-9a-f]{64}',x) is not None and x!='0'*64
    path_ok=lambda v:type(v) is str and os.path.isabs(v) and os.path.normpath(v)==v and len(v)<=4000 and not v.startswith('//') and chr(92) not in v and chr(0) not in v
    id_ok=lambda v:type(v) is str and re.fullmatch('[A-Za-z][A-Za-z0-9_.:-]{0,95}',v) is not None
    for k in EC394_ALL_SCALARS:
        v=inputs[k]
        if k.endswith('_file'):
            if not path_ok(v):_fail('EC394_NORMAL_ABSOLUTE_SOURCE_REQUIRED')
        elif k.endswith('_sha256'):
            if not sha_ok(v):_fail('EC394_OUTSIDE_PIN_SHA_INVALID')
        elif k.endswith('_public_hex'):
            if not key_ok(v):_fail('EC394_OUTSIDE_PUBLIC_KEY_PIN_INVALID')
        elif k.endswith('_utc'):
            if type(v) is not str or re.fullmatch(r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ',v) is None:
                _fail('EC394_CANONICAL_CUTOFF_OR_EVALUATION_UTC_REQUIRED')
        elif k.endswith('_observer_id') or k.startswith('claimed_'):
            if not id_ok(v):_fail('EC394_OBSERVER_OR_LINEAGE_ID_INVALID')
    if inputs['expected_outside_retained_ec392_primary_observer_id']==inputs[
       'expected_outside_retained_ec392_secondary_observer_id']:
        _fail('EC394_DUPLICATE_INHERITED_OBSERVERS',status='permission_denied')
    n=len(inputs['historical_directory_root_shas']) if type(inputs['historical_directory_root_shas']) is list else 0
    if not 1<=n<=3:_fail('EC394_ONE_TO_THREE_EPOCHS_REQUIRED')
    fixed_two={'institution_root_public_key_shas','witness_public_key_shas',
      'institution_claimed_ids','witness_claimed_ids','expected_source_status_head_shas',
      'expected_source_attestation_head_shas','expected_witness_head_shas'}
    for k,_ in EC394_ALL_REPEATS:
        seq=inputs[k]
        if k in fixed_two:low=high=2
        elif k=='historical_dual_handoff_shas':low=0;high=n-1
        elif k.startswith(('historical_','secondary_','minimum_authority_',
                           'minimum_historical_','minimum_secondary_')):low=high=n
        else:low=1;high=4
        if type(seq) is not list or not low<=len(seq)<=high:
            _fail('EC394_PARENT_OR_NEW_PER_EPOCH_LIST_LENGTH_INVALID')
        if k.endswith('_ids'):
            if any(not id_ok(x) for x in seq):_fail('EC394_SIGNER_ROLE_ID_INVALID')
        elif k.startswith('minimum_') or 'tree_size' in k or 'sequence' in k:
            limit=(4 if k in ('minimum_historical_ec339_pre_handoff_registered_site_counts',
                       'minimum_historical_ec339_pre_cutoff_log_anchored_receipt_counts',
                       'minimum_historical_ec339_crossview_timestamped_checkpoint_counts') else
                   2 if k in ('minimum_historical_ec339_pre_cutoff_witness_counts',
                       'minimum_secondary_ec391_prior_timestamped_head_counts',
                       'minimum_historical_ec339_prior_timestamped_head_counts',
                       'minimum_historical_ec339_independent_signed_checkpoint_counts') else
                   16 if k=='minimum_historical_ec339_external_witness_custody_pair_counts' else 2147483647)
            if any(type(x) is not int or not 0<=x<=limit for x in seq):
                _fail('EC394_EPOCH_COUNT_FLOOR_INVALID')
        elif any(not sha_ok(x) and not (x is None and k=='expected_source_attestation_head_shas')
                 for x in seq):_fail('EC394_OUTSIDE_RETAINED_EPOCH_SHA_INVALID')
    if any(len(set(inputs[k]))!=2 for k in ('institution_root_public_key_shas',
                                             'witness_public_key_shas')):
        _fail('EC394_INHERITED_SIGNER_KEY_REUSE')
    argv=[sys.executable,'-I','-B',str(AIRGAP_EC339_REGISTERED_WITNESS),
          'audit-historical-ec339-registered-witness']
    for k in EC394_ALL_SCALARS:argv.extend(['--'+k.replace('_','-'),str(inputs[k])])
    for k,flag in EC394_ALL_REPEATS:
        for x in inputs[k]:argv.extend([flag,'none' if x is None else str(x)])
    rc,doc=_command(argv,timeout=1500,max_output=1000000)
    base={'schema','command','status','exit_code','offline_unresolved_exit_code',
      'sender_origin_path_required_or_read',
      'ec339_to_ec337_full_independent_unmocked_external_acceptance_performed',
      *EC394_NEGATIVES}
    if rc==2:
        extra={'verified_live_ec393_report_sha256', 'verified_live_ec393_inventory_sha256',
          'historical_registered_witness_original_sha256',
          'receiver_verified_registered_witness_inventory_sha256',
          'cryptographically_timestamped_pre_handoff_registered_site_role_count',
          'cryptographically_timestamped_pre_cutoff_independent_witness_count',
          'visible_genuine_signed_log_fork_count','signed_key_status_snapshot_sha256',
          'furnished_signed_key_revocation_count','registered_witness_epoch_reviews',
          'visible_signed_log_fork_cases',
          'local_registered_key_and_independent_witness_consistency',*EC394_FLAGS}
        rows=doc.get('registered_witness_epoch_reviews') if type(doc) is dict else None
        cases=doc.get('visible_signed_log_fork_cases') if type(doc) is dict else None
        valid=(type(doc) is dict and set(doc)==base|extra and
           doc.get('schema')=='ces.ec394.receiver_registered_custody_and_independent_fork_witness_unresolved.v1' and
           doc.get('command')=='audit-historical-ec339-registered-witness' and
           doc.get('exit_code')==2 and doc.get('offline_unresolved_exit_code')==2 and
           doc.get('sender_origin_path_required_or_read') is False and
           doc.get('ec339_to_ec337_full_independent_unmocked_external_acceptance_performed') is False and
           all(doc.get(k) is False for k in EC394_NEGATIVES) and
           all(type(doc.get(k)) is bool for k in EC394_FLAGS) and
           all(doc[k] is True for k in EC394_FLAGS[-3:]) and
           type(doc.get('local_registered_key_and_independent_witness_consistency')) is bool and
           doc['local_registered_key_and_independent_witness_consistency']==(
               not any(doc[k] for k in EC394_FLAGS[:7])) and
           doc.get('status')==next((EC394_OUTCOMES[i] for i,k in enumerate(EC394_FLAGS)
                if doc[k]),EC394_OUTCOMES[-1])+'_unresolved' and
           all(sha_ok(doc.get(k)) for k in (
               'verified_live_ec393_report_sha256','verified_live_ec393_inventory_sha256',
               'historical_registered_witness_original_sha256',
               'receiver_verified_registered_witness_inventory_sha256')) and
           (doc.get('signed_key_status_snapshot_sha256') is None or
            sha_ok(doc.get('signed_key_status_snapshot_sha256'))) and
           type(doc.get('furnished_signed_key_revocation_count')) is int and
           0<=doc['furnished_signed_key_revocation_count']<=20 and
           type(rows) is list and len(rows)==n and type(cases) is list and len(cases)<=2*n and
           all(type(r) is dict and set(r)=={'epoch_index',
               'pre_handoff_registered_site_roles','pre_cutoff_independent_log_witnesses',
               'site_key_registration_inventory_sha256',
               'third_party_witness_inventory_sha256','visible_valid_signed_log_fork_count'} and
               type(r['epoch_index']) is int and r['epoch_index']==i and
               type(r['pre_handoff_registered_site_roles']) is int and
               0<=r['pre_handoff_registered_site_roles']<=4 and
               type(r['pre_cutoff_independent_log_witnesses']) is int and
               0<=r['pre_cutoff_independent_log_witnesses']<=2 and
               type(r['visible_valid_signed_log_fork_count']) is int and
               0<=r['visible_valid_signed_log_fork_count']<=2 and
               sha_ok(r['site_key_registration_inventory_sha256']) and
               sha_ok(r['third_party_witness_inventory_sha256'])
               for i,r in enumerate(rows)) and
           doc.get('cryptographically_timestamped_pre_handoff_registered_site_role_count')==sum(
               r['pre_handoff_registered_site_roles'] for r in rows) and
           doc.get('cryptographically_timestamped_pre_cutoff_independent_witness_count')==sum(
               r['pre_cutoff_independent_log_witnesses'] for r in rows) and
           doc.get('visible_genuine_signed_log_fork_count')==sum(
               r['visible_valid_signed_log_fork_count'] for r in rows))
        if not valid:_fail('EC394_CHILD_SIGNED_REGISTRATION_REPORT_INVALID',status='unavailable')
    elif rc in (3,4,5):
        valid=(type(doc) is dict and set(doc)==base|{'reason_code'} and
          doc.get('schema')=='ces.ec394.registered_witness_denial.v1' and
          doc.get('command')=='audit-historical-ec339-registered-witness' and
          doc.get('exit_code')==rc and STATUS_EXITS.get(doc.get('status'))==rc and
          doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec339_to_ec337_full_independent_unmocked_external_acceptance_performed') is False and
          all(doc.get(k) is False for k in EC394_NEGATIVES) and
          type(doc.get('reason_code')) is str and
          re.fullmatch('[A-Z][A-Z0-9_]{2,175}',doc['reason_code']) is not None)
        if not valid:_fail('EC394_CHILD_DENIAL_CONTRACT_INVALID',status='unavailable')
    else:_fail('EC394_CHILD_EXIT_INVALID',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc


