def audit_historical_ec339_official_certificate(action:str,mode:str,*,pretty:bool=False,**inputs)->int:
    if (action,mode)!=('DeliveryAudit','AuditHistoricalEC339OfficialCertificate'):
        _fail('EC399_FIXED_READONLY_ACTION_MODE_REQUIRED',status='permission_denied')
    if (not AIRGAP_EC339_OFFICIAL_CERTIFICATE.is_file() or
            AIRGAP_EC339_OFFICIAL_CERTIFICATE.is_symlink()):
        _fail('EC399_ISOLATED_RECEIVER_MISSING',status='unavailable')
    if set(inputs)!=set(EC399_ALL_SCALARS)|{k for k,_ in EC399_ALL_REPEATS}:
        _fail('EC399_INCOMPLETE_REAL_EC398_AND_NEW_CERTIFICATE_INPUTS')
    sha_ok=lambda x:type(x) is str and re.fullmatch('[0-9a-f]{64}',x) is not None and x!='0'*64
    n=len(inputs['historical_directory_root_shas']) if type(inputs['historical_directory_root_shas']) is list else 0
    if not 1<=n<=3:_fail('EC399_HISTORICAL_EPOCH_COUNT_ONE_TO_THREE_REQUIRED')
    for key in EC399_NEW_SCALARS+('expected_retained_historical_ec339_official_certificate_inventory_sha256',):
        v=inputs[key]
        if key.endswith('_file'):
            if (type(v) is not str or not os.path.isabs(v) or os.path.normpath(v)!=v
                    or len(v)>4000 or v.startswith('//') or '\\' in v or '\x00' in v):
                _fail('EC399_NORMALIZED_ABSOLUTE_BUNDLE_FILE_REQUIRED')
        elif key.endswith('_oid'):
            if type(v) is not str or len(v)>90 or re.fullmatch(r'[0-2](?:\.(?:0|[1-9][0-9]*)){2,14}',v) is None:
                _fail('EC399_OUTSIDE_CERTIFICATE_POLICY_OID_INVALID')
        elif not sha_ok(v):_fail('EC399_OUTSIDE_SHA_PIN_MALFORMED')
    for key,_ in EC399_NEW_REPEATS:
        vals=inputs[key]
        if type(vals) is not list or len(vals)!=n:
            _fail('EC399_OUTSIDE_CERTIFICATE_INVENTORIES_WRONG_EPOCH_COUNT')
        if key.startswith('minimum_'):
            if any(type(v) is not int or not 0<=v<=2 for v in vals):
                _fail('EC399_TWO_ROOT_PUBLISHER_MINIMUM_INVALID')
        elif any(not sha_ok(v) for v in vals):
            _fail('EC399_EPOCH_SIGNED_OR_CRL_SHA_INVALID')
    argv=[sys.executable,'-I','-B',str(AIRGAP_EC339_OFFICIAL_CERTIFICATE),
          'audit-historical-ec339-official-certificate']
    for key in EC399_ALL_SCALARS:
        argv.extend(['--'+key.replace('_','-'),str(inputs[key])])
    for key,flag in EC399_ALL_REPEATS:
        for v in inputs[key]:argv.extend([flag,'none' if v is None else str(v)])
    rc,doc=_command(argv,timeout=2700,max_output=1250000)
    common={'schema','command','status','exit_code','offline_unresolved_exit_code',
       'sender_origin_path_required_or_read',
       'ec339_to_ec337_full_independent_unmocked_external_acceptance_performed',
       *EC399_NEGATIVES}
    if rc==2:
        extra={'verified_live_ec398_report_sha256',
          'verified_live_ec398_inventory_sha256',
          'original_two_root_certificate_bundle_sha256',
          'receiver_verified_certificate_inventory_sha256',
          'verified_independent_x509_publisher_count',
          'visible_historically_revoked_certificate_count',
          'certificate_epoch_reviews',
          'bounded_local_gazette_certificate_crl_parent_consistency',*EC399_FLAGS}
        rows=doc.get('certificate_epoch_reviews') if type(doc) is dict else None
        fields={'epoch_index','locally_verified_x509_publisher_count',
          'signed_original_inventory_sha256','historical_current_crl_inventory_sha256',
          'visible_revoked_publisher_certificates'}
        valid=(type(doc) is dict and set(doc)==common|extra and
          doc.get('schema')=='ces.ec399.receiver_two_root_gazette_certificate_revocation_unresolved.v1' and
          doc.get('command')=='audit-historical-ec339-official-certificate' and
          doc.get('exit_code')==2 and doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec339_to_ec337_full_independent_unmocked_external_acceptance_performed') is False and
          all(doc.get(k) is False for k in EC399_NEGATIVES) and
          all(type(doc.get(k)) is bool for k in EC399_FLAGS) and
          all(doc[k] is True for k in EC399_FLAGS[-3:]) and
          doc.get('bounded_local_gazette_certificate_crl_parent_consistency') is
              (not any(doc[k] for k in EC399_FLAGS[:5])) and
          doc.get('status')==next((EC399_OUTCOMES[i] for i,k in enumerate(EC399_FLAGS)
                     if doc[k]),EC399_OUTCOMES[-1])+'_unresolved' and
          all(sha_ok(doc.get(k)) for k in (
             'verified_live_ec398_report_sha256','verified_live_ec398_inventory_sha256',
             'original_two_root_certificate_bundle_sha256',
             'receiver_verified_certificate_inventory_sha256')) and
          type(rows) is list and len(rows)==n and all(
             type(r) is dict and set(r)==fields and
             type(r['epoch_index']) is int and r['epoch_index']==i and
             all(type(r[k]) is int and 0<=r[k]<=2 for k in (
               'locally_verified_x509_publisher_count','visible_revoked_publisher_certificates')) and
             sha_ok(r['signed_original_inventory_sha256']) and
             sha_ok(r['historical_current_crl_inventory_sha256'])
             for i,r in enumerate(rows)) and
          type(doc.get('verified_independent_x509_publisher_count')) is int and
          type(doc.get('visible_historically_revoked_certificate_count')) is int and
          doc['verified_independent_x509_publisher_count']==sum(
              r['locally_verified_x509_publisher_count'] for r in rows) and
          doc['visible_historically_revoked_certificate_count']==sum(
              r['visible_revoked_publisher_certificates'] for r in rows))
        if not valid:_fail('EC399_CHILD_SIGNED_CERTIFICATE_REPORT_CONTRACT_INVALID',status='unavailable')
    elif rc in (3,4,5):
        valid=(type(doc) is dict and set(doc)==common|{'reason_code'} and
          doc.get('schema')=='ces.ec399.gazette_certificate_revocation_denial.v1' and
          doc.get('command')=='audit-historical-ec339-official-certificate' and
          doc.get('exit_code')==rc and STATUS_EXITS.get(doc.get('status'))==rc and
          doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec339_to_ec337_full_independent_unmocked_external_acceptance_performed') is False and
          all(doc.get(k) is False for k in EC399_NEGATIVES) and
          type(doc.get('reason_code')) is str and
          re.fullmatch('[A-Z][A-Z0-9_]{2,175}',doc['reason_code']) is not None)
        if not valid:_fail('EC399_CHILD_DENIAL_CONTRACT_INVALID',status='unavailable')
    else:_fail('EC399_CHILD_EXIT_INVALID',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc


