EC401_NEW_SCALARS=('historical_ec339_issuer_ocsp_bundle_file', 'expected_historical_ec339_issuer_ocsp_bundle_sha256', 'expected_outside_retained_ec401_first_a_historical_ocsp_sha256', 'expected_outside_retained_ec401_first_b_historical_ocsp_sha256')
EC401_NEW_REPEATS=(('historical_ec339_issuer_ocsp_epoch_inventory_shas', '--historical-ec339-issuer-ocsp-epoch-inventory-sha256'), ('minimum_historical_ec339_joint_ocsp_publisher_counts', '--minimum-historical-ec339-joint-ocsp-publisher-count'))
EC401_FLAGS=('inherited_real_ec400_cms_x509_crl_parent_disputed', 'outside_original_ocsp_epoch_inventory_or_count_pin_disagrees', 'signed_historical_or_evaluation_ocsp_original_missing', 'ocsp_good_and_contemporaneous_two_epoch_coverage_incomplete', 'ocsp_reveals_revocation_or_unknown_certificate_status', 'real_official_issuer_authorization_and_original_public_source_not_proven', 'global_ocsp_crl_census_and_independent_prior_public_access_not_proven', 'qualified_tsa_worm_unmocked_history_and_final_acceptance_not_proven')
EC401_OUTCOMES=('ec401_real_ec400_parent_original_or_cryptography_disputed', 'ec401_outside_ocsp_original_epoch_or_count_constraints_disagree', 'ec401_signed_ocsp_historical_or_current_original_unavailable', 'ec401_original_ocsp_good_contemporaneous_coverage_incomplete', 'ec401_genuine_ocsp_revoked_or_unknown_certificate', 'ec401_real_world_official_issuer_authorization_not_established', 'ec401_global_revocation_or_prior_public_source_not_established', 'ec401_qualified_tsa_worm_unmocked_history_final_acceptance_not_proven')
EC401_NEGATIVES=('ocsp_response_good_proves_a_real_official_government_or_court_ca', 'issuer_signed_ocsp_is_an_independently_qualified_legal_timestamp', 'a_furnished_responder_original_proves_pre_dispute_public_availability', 'signed_local_ocsp_and_crls_prove_complete_global_revocation_coverage', 'ocsp_response_can_repair_failed_parent_ec399_crl_or_cms_signatures', 'delegated_responder_accepted_without_direct_issuer_authorization', 'responder_certificate_revocation_globally_proven_by_nocheck', 'issuer_or_delegate_signed_in_the_receiver_or_retrieved_from_network', 'receiver_wrote_cas_worm_git_ci_powershell_or_external_provider_state', 'original_full_unmocked_history_native_ps7_or_user_acceptance_passed')
EC401_ALL_SCALARS=(*EC400_ALL_SCALARS,*EC401_NEW_SCALARS,
                   'expected_retained_historical_ec339_issuer_ocsp_inventory_sha256')
