def audit_historical_ec339_issuer_ocsp(action:str,mode:str,*,pretty:bool=False,**inputs)->int:
    if (action,mode)!=('DeliveryAudit','AuditHistoricalEC339IssuerOCSP'):
        _fail('EC401_FIXED_READONLY_ACTION_MODE_REQUIRED',status='permission_denied')
    if not AIRGAP_EC339_ISSUER_OCSP.is_file() or AIRGAP_EC339_ISSUER_OCSP.is_symlink():
        _fail('EC401_ISOLATED_OCSP_RECEIVER_MISSING',status='unavailable')
    if set(inputs)!=set(EC401_ALL_SCALARS)|{k for k,_ in EC401_ALL_REPEATS}:
        _fail('EC401_INCOMPLETE_EC400_PARENT_AND_OCSP_ARGUMENTS')
    sha_ok=lambda x:type(x) is str and re.fullmatch('[0-9a-f]{64}',x) is not None and x!='0'*64
    n=len(inputs['historical_directory_root_shas']) if type(inputs['historical_directory_root_shas']) is list else 0
    if not 1<=n<=3:_fail('EC401_ONE_TO_THREE_EPOCHS_REQUIRED')
    for key in (*EC401_NEW_SCALARS,
                'expected_retained_historical_ec339_issuer_ocsp_inventory_sha256'):
        val=inputs[key]
        if key.endswith('_file'):
            if (type(val) is not str or not os.path.isabs(val) or
                    os.path.normpath(val)!=val or len(val)>4000 or
                    val.startswith('//') or '\\' in val or '\x00' in val):
                _fail('EC401_NORMALIZED_ABSOLUTE_BUNDLE_FILE_REQUIRED')
        elif not sha_ok(val):_fail('EC401_EXTERNAL_OCSP_SHA_PIN_INVALID')
    if inputs[EC401_NEW_SCALARS[2]]==inputs[EC401_NEW_SCALARS[3]]:
        _fail('EC401_FIRST_A_B_OCSP_DIGESTS_MUST_DIFFER')
    for key,_ in EC401_NEW_REPEATS:
        values=inputs[key]
        if type(values) is not list or len(values)!=n:
            _fail('EC401_OCSP_EPOCH_EXTERNAL_CONSTRAINT_MISSING')
        if key.startswith('minimum_'):
            if any(type(v) is not int or not 0<=v<=2 for v in values):
                _fail('EC401_OCSP_PUBLISHER_MINIMUM_OUT_OF_RANGE')
        elif any(not sha_ok(v) for v in values):
            _fail('EC401_OCSP_EPOCH_SHA_INVALID')
    argv=[sys.executable,'-I','-B',str(AIRGAP_EC339_ISSUER_OCSP),
          'audit-historical-ec339-issuer-ocsp']
    for key in EC401_ALL_SCALARS:
        argv.extend(['--'+key.replace('_','-'),str(inputs[key])])
    for key,flag in EC401_ALL_REPEATS:
        for value in inputs[key]:argv.extend([flag,'none' if value is None else str(value)])
    rc,doc=_command(argv,timeout=2700,max_output=1250000)
    common={'schema','command','status','exit_code','offline_unresolved_exit_code',
       'sender_origin_path_required_or_read',
       'ec339_to_ec337_full_independent_unmocked_external_acceptance_performed',
       *EC401_NEGATIVES}
    if rc==2:
        extra={'verified_live_ec400_report_sha256','verified_live_ec400_inventory_sha256',
          'original_ocsp_bundle_sha256','receiver_verified_ocsp_inventory_sha256',
          'verified_joint_parent_cms_crl_and_local_good_ocsp_publishers',
          'ocsp_epoch_reviews',
          'bounded_local_issuer_ocsp_and_real_parent_consistency',*EC401_FLAGS}
        rows=doc.get('ocsp_epoch_reviews') if type(doc) is dict else None
        fields={'epoch_index','joint_verified_ocsp_publisher_count',
                'ocsp_original_inventory_sha256','authentic_parent_cms_joint_signer_count'}
        valid=(type(doc) is dict and set(doc)==common|extra and
          doc.get('schema')=='ces.ec401.issuer_signed_ocsp_evidence_unresolved.v1' and
          doc.get('command')=='audit-historical-ec339-issuer-ocsp' and
          doc.get('exit_code')==doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec339_to_ec337_full_independent_unmocked_external_acceptance_performed') is False and
          all(doc.get(k) is False for k in EC401_NEGATIVES) and
          all(type(doc.get(k)) is bool for k in EC401_FLAGS) and
          all(doc[k] is True for k in EC401_FLAGS[-3:]) and
          doc.get('bounded_local_issuer_ocsp_and_real_parent_consistency') is
             (not any(doc[k] for k in EC401_FLAGS[:5])) and
          doc.get('status')==next((EC401_OUTCOMES[i] for i,k in enumerate(EC401_FLAGS)
                                 if doc[k]),EC401_OUTCOMES[-1])+'_unresolved' and
          all(sha_ok(doc.get(k)) for k in (
             'verified_live_ec400_report_sha256','verified_live_ec400_inventory_sha256',
             'original_ocsp_bundle_sha256','receiver_verified_ocsp_inventory_sha256')) and
          type(rows) is list and len(rows)==n and all(
             type(r) is dict and set(r)==fields and
             type(r['epoch_index']) is int and r['epoch_index']==i and
             type(r['joint_verified_ocsp_publisher_count']) is int and
             0<=r['joint_verified_ocsp_publisher_count']<=2 and
             type(r['authentic_parent_cms_joint_signer_count']) is int and
             r['authentic_parent_cms_joint_signer_count'] in (0,2) and
             sha_ok(r['ocsp_original_inventory_sha256'])
             for i,r in enumerate(rows)) and
          type(doc.get('verified_joint_parent_cms_crl_and_local_good_ocsp_publishers')) is int and
          doc['verified_joint_parent_cms_crl_and_local_good_ocsp_publishers']==sum(
              r['joint_verified_ocsp_publisher_count'] for r in rows))
        if not valid:_fail('EC401_CHILD_SIGNED_OCSP_REPORT_CONTRACT_INVALID',status='unavailable')
    elif rc in (3,4,5):
        valid=(type(doc) is dict and set(doc)==common|{'reason_code'} and
          doc.get('schema')=='ces.ec401.issuer_signed_ocsp_denial.v1' and
          doc.get('command')=='audit-historical-ec339-issuer-ocsp' and
          doc.get('exit_code')==rc and STATUS_EXITS.get(doc.get('status'))==rc and
          doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec339_to_ec337_full_independent_unmocked_external_acceptance_performed') is False and
          all(doc.get(k) is False for k in EC401_NEGATIVES) and
          type(doc.get('reason_code')) is str and
          re.fullmatch('[A-Z][A-Z0-9_]{2,175}',doc['reason_code']) is not None)
        if not valid:_fail('EC401_CHILD_DENIAL_CONTRACT_INVALID',status='unavailable')
    else:_fail('EC401_CHILD_EXIT_INVALID',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc


