def audit_historical_ec339_original_xmldsig(action:str,mode:str,*,pretty:bool=False,**inputs)->int:
    if (action,mode)!=('DeliveryAudit','AuditHistoricalEC339OriginalXMLDSig'):
        _fail('EC403_ONLY_FIXED_READONLY_ACTION_MODE_ALLOWED',status='permission_denied')
    if (not AIRGAP_EC339_ORIGINAL_XMLDSIG.is_file() or
            AIRGAP_EC339_ORIGINAL_XMLDSIG.is_symlink()):
        _fail('EC403_ISOLATED_XMLSIG_RECEIVER_MISSING',status='unavailable')
    if set(inputs)!=set(EC403_ALL_SCALARS)|{key for key,_ in EC403_ALL_REPEATS}:
        _fail('EC403_INCOMPLETE_REAL_EC402_PARENT_AND_XML_ARGUMENTS')
    sha_ok=lambda x:type(x) is str and re.fullmatch('[0-9a-f]{64}',x) is not None and x!='0'*64
    n=len(inputs['historical_directory_root_shas']) if type(inputs['historical_directory_root_shas']) is list else 0
    if not 1<=n<=3:_fail('EC403_ONE_TO_THREE_PARENT_EPOCHS_REQUIRED')
    for key in (*EC403_NEW_SCALARS,
                'expected_retained_historical_ec339_original_xmldsig_inventory_sha256'):
        v=inputs[key]
        if key.endswith('_file'):
            if (type(v) is not str or not os.path.isabs(v) or
                os.path.normpath(v)!=v or len(v)>4000 or
                v.startswith('//') or '\\' in v or '\x00' in v):
                _fail('EC403_NORMALIZED_ABSOLUTE_XML_BUNDLE_PATH_REQUIRED')
        elif not sha_ok(v):
            _fail('EC403_INDEPENDENT_XML_BUNDLE_OR_ORIGINAL_SHA_INVALID')
    if inputs[EC403_NEW_SCALARS[2]]==inputs[EC403_NEW_SCALARS[3]]:
        _fail('EC403_FIRST_TWO_XML_ORIGINAL_SHAS_MUST_DIFFER')
    for key,_ in EC403_NEW_REPEATS:
        values=inputs[key]
        if type(values) is not list or len(values)!=n:
            _fail('EC403_EPOCH_SHA_OR_COUNT_INPUT_MISSING')
        if key.startswith('minimum_'):
            if any(type(v) is not int or not 0<=v<=2 for v in values):
                _fail('EC403_JOINT_XML_COUNT_OUT_OF_RANGE')
        elif any(not sha_ok(v) for v in values):
            _fail('EC403_XML_EPOCH_INDEPENDENT_SHA_INVALID')
    argv=[sys.executable,'-I','-B',str(AIRGAP_EC339_ORIGINAL_XMLDSIG),
          'audit-historical-ec339-original-xmldsig']
    for key in EC403_ALL_SCALARS:
        argv.extend(['--'+key.replace('_','-'),str(inputs[key])])
    for key,flag in EC403_ALL_REPEATS:
        for value in inputs[key]:
            argv.extend([flag,'none' if value is None else str(value)])
    rc,doc=_command(argv,timeout=2700,max_output=1500000)
    common={'schema','command','status','exit_code','offline_unresolved_exit_code',
       'sender_origin_path_required_or_read',
       'ec339_to_ec337_full_independent_unmocked_external_acceptance_performed',
       *EC403_NEGATIVES}
    if rc==2:
        extra={'verified_live_ec402_report_sha256',
          'verified_live_ec402_inventory_sha256','original_xmldsig_bundle_sha256',
          'receiver_verified_original_xmldsig_inventory_sha256',
          'verified_joint_parent_pdf_and_xmlsig_publishers',
          'original_xmldsig_epoch_reviews',
          'bounded_local_original_xmldsig_and_real_ec402_parent_consistency',
          *EC403_FLAGS}
        rows=doc.get('original_xmldsig_epoch_reviews') if type(doc) is dict else None
        fields={'epoch_index','actual_verified_xmlsig_count',
          'joint_verified_xmlsig_and_parent_pdf_count',
          'original_xmlsig_epoch_inventory_sha256',
          'real_ec402_parent_joint_pdf_ocsp_count'}
        valid=(type(doc) is dict and set(doc)==common|extra and
          doc.get('schema')=='ces.ec403.original_xmldsig_unresolved.v1' and
          doc.get('command')=='audit-historical-ec339-original-xmldsig' and
          doc.get('exit_code')==doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec339_to_ec337_full_independent_unmocked_external_acceptance_performed') is False and
          all(doc.get(k) is False for k in EC403_NEGATIVES) and
          all(type(doc.get(k)) is bool for k in EC403_FLAGS) and
          all(doc[k] is True for k in EC403_FLAGS[-3:]) and
          doc.get('bounded_local_original_xmldsig_and_real_ec402_parent_consistency') is
              (not any(doc[k] for k in EC403_FLAGS[:4])) and
          doc.get('status')==next((EC403_OUTCOMES[i] for i,k in enumerate(EC403_FLAGS)
                                  if doc[k]),EC403_OUTCOMES[-1])+'_unresolved' and
          all(sha_ok(doc.get(k)) for k in (
              'verified_live_ec402_report_sha256',
              'verified_live_ec402_inventory_sha256',
              'original_xmldsig_bundle_sha256',
              'receiver_verified_original_xmldsig_inventory_sha256')) and
          doc.get('original_xmldsig_bundle_sha256')==inputs[
              'expected_historical_ec339_original_xmldsig_bundle_sha256'] and
          type(rows) is list and len(rows)==n and all(
              type(r) is dict and set(r)==fields and
              type(r['epoch_index']) is int and r['epoch_index']==i and
              type(r['actual_verified_xmlsig_count']) is int and
              0<=r['actual_verified_xmlsig_count']<=2 and
              type(r['joint_verified_xmlsig_and_parent_pdf_count']) is int and
              0<=r['joint_verified_xmlsig_and_parent_pdf_count']<=r['actual_verified_xmlsig_count'] and
              type(r['real_ec402_parent_joint_pdf_ocsp_count']) is int and
              0<=r['real_ec402_parent_joint_pdf_ocsp_count']<=2 and
              sha_ok(r['original_xmlsig_epoch_inventory_sha256'])
              for i,r in enumerate(rows)) and
          type(doc.get('verified_joint_parent_pdf_and_xmlsig_publishers')) is int and
          doc['verified_joint_parent_pdf_and_xmlsig_publishers']==sum(
              r['joint_verified_xmlsig_and_parent_pdf_count'] for r in rows))
        if not valid:
            _fail('EC403_CHILD_ORIGINAL_XMLSIG_REPORT_CONTRACT_INVALID',status='unavailable')
    elif rc in (3,4,5):
        valid=(type(doc) is dict and set(doc)==common|{'reason_code'} and
          doc.get('schema')=='ces.ec403.original_xmldsig_denial.v1' and
          doc.get('command')=='audit-historical-ec339-original-xmldsig' and
          doc.get('exit_code')==rc and STATUS_EXITS.get(doc.get('status'))==rc and
          doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec339_to_ec337_full_independent_unmocked_external_acceptance_performed') is False and
          all(doc.get(k) is False for k in EC403_NEGATIVES) and
          type(doc.get('reason_code')) is str and
          re.fullmatch('[A-Z][A-Z0-9_]{2,175}',doc['reason_code']) is not None)
        if not valid:
            _fail('EC403_CHILD_XMLSIG_DENIAL_CONTRACT_INVALID',status='unavailable')
    else:
        _fail('EC403_CHILD_EXIT_INVALID',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc


