def audit_historical_ec339_custody_witness(action:str,mode:str,*,pretty:bool=False,**inputs)->int:
    if (action,mode)!=('DeliveryAudit','AuditHistoricalEC339CustodyWitness'):
        _fail('EC406_ONLY_FIXED_READONLY_ACTION_MODE_ALLOWED',status='permission_denied')
    if (not AIRGAP_EC339_CUSTODY_WITNESS.is_file() or
            AIRGAP_EC339_CUSTODY_WITNESS.is_symlink()):
        _fail('EC406_ISOLATED_SIGNED_CUSTODY_RECEIVER_MISSING',status='unavailable')
    if set(inputs)!=set(EC406_ALL_SCALARS)|{k for k,_ in EC406_ALL_REPEATS}:
        _fail('EC406_COMPLETE_REAL_EC405_AND_CUSTODY_WITNESS_ARGUMENTS_REQUIRED')
    sha_ok=lambda x:type(x) is str and re.fullmatch('[0-9a-f]{64}',x) is not None and x!='0'*64
    n=(len(inputs['historical_directory_root_shas'])
       if type(inputs['historical_directory_root_shas']) is list else 0)
    if not 1<=n<=3:
        _fail('EC406_ONE_TO_THREE_REAL_EC405_EPOCHS_REQUIRED')
    for k in (*EC406_NEW_SCALARS,
              'expected_retained_historical_ec339_custody_witness_inventory_sha256'):
        v=inputs[k]
        if k.endswith('_file'):
            if (type(v) is not str or not os.path.isabs(v) or
                os.path.normpath(v)!=v or len(v)>4000 or
                v.startswith('//') or '\\' in v or '\x00' in v):
                _fail('EC406_ABSOLUTE_NORMALIZED_ORIGINAL_BUNDLE_PATH_REQUIRED')
        elif k=='ec406_custody_evaluation_utc':
            if (type(v) is not str or re.fullmatch(
                r'[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z',v) is None):
                _fail('EC406_EVALUATION_UTC_CANONICAL_REQUIRED')
        elif not sha_ok(v):
            _fail('EC406_CUSTODY_WITNESS_ORIGINAL_SHA_INVALID')
    if len({inputs[k] for k in EC406_NEW_SCALARS[3:11]})!=8:
        _fail('EC406_FOUR_KEYS_AND_FOUR_FIRST_ORIGINALS_MUST_DIFFER')
    for k,_ in EC406_NEW_REPEATS:
        values=inputs[k]
        if type(values) is not list or len(values)!=n:
            _fail('EC406_EPOCH_SIGNED_INVENTORY_SHA_OR_FLOOR_REQUIRED')
        if k.startswith('minimum_'):
            if any(type(x) is not int or not 0<=x<=2 for x in values):
                _fail('EC406_MAX_TWO_SIGNED_ROLE_EPOCH_FLOOR')
        elif any(not sha_ok(x) for x in values):
            _fail('EC406_INVALID_SIGNED_EPOCH_INVENTORY_SHA')
    argv=[sys.executable,'-I','-B',str(AIRGAP_EC339_CUSTODY_WITNESS),
          'audit-historical-ec339-custody-witness']
    for k in EC406_ALL_SCALARS:
        argv.extend(['--'+k.replace('_','-'),str(inputs[k])])
    for k,flag in EC406_ALL_REPEATS:
        for v in inputs[k]:
            argv.extend([flag,'none' if v is None else str(v)])
    rc,doc=_command(argv,timeout=2700,max_output=1500000)
    common={'schema','command','status','exit_code','offline_unresolved_exit_code',
            'sender_origin_path_required_or_read',
            'ec339_to_ec337_full_independent_unmocked_external_acceptance_performed',
            *EC406_NEGATIVES}
    if rc==2:
        extra={'verified_live_ec405_report_sha256',
               'verified_live_ec405_inventory_sha256',
               'original_custody_witness_bundle_sha256',
               'receiver_verified_custody_witness_inventory_sha256',
               'verified_joint_custody_witness_and_real_parent_publishers',
               'custody_witness_epoch_reviews',
               'bounded_local_custody_witness_and_real_ec405_parent_consistency',
               *EC406_FLAGS}
        rows=doc.get('custody_witness_epoch_reviews') if type(doc) is dict else None
        fields={'epoch_index','verified_signed_accession_count',
                'verified_signed_witness_count','claimed_times_in_window_count',
                'joint_signed_custody_witness_and_parent_count',
                'custody_witness_epoch_inventory_sha256',
                'real_ec405_parent_joint_warc_timestamp_count'}
        valid=(type(doc) is dict and set(doc)==common|extra and
          doc.get('schema')=='ces.ec406.original_cross_witness_custody_unresolved.v1' and
          doc.get('command')=='audit-historical-ec339-custody-witness' and
          doc.get('exit_code')==doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec339_to_ec337_full_independent_unmocked_external_acceptance_performed') is False and
          all(doc.get(k) is False for k in EC406_NEGATIVES) and
          all(type(doc.get(k)) is bool for k in EC406_FLAGS) and
          all(doc[k] is True for k in EC406_FLAGS[-3:]) and
          doc.get('bounded_local_custody_witness_and_real_ec405_parent_consistency') is
              (not any(doc[k] for k in EC406_FLAGS[:5])) and
          doc.get('status')==next((EC406_OUTCOMES[i] for i,k in enumerate(EC406_FLAGS)
                                  if doc[k]),EC406_OUTCOMES[-1])+'_unresolved' and
          all(sha_ok(doc.get(k)) for k in (
              'verified_live_ec405_report_sha256',
              'verified_live_ec405_inventory_sha256',
              'original_custody_witness_bundle_sha256',
              'receiver_verified_custody_witness_inventory_sha256')) and
          doc.get('original_custody_witness_bundle_sha256')==inputs[
              'expected_historical_ec339_custody_witness_bundle_sha256'] and
          type(rows) is list and len(rows)==n and all(
              type(r) is dict and set(r)==fields and
              type(r['epoch_index']) is int and r['epoch_index']==i and
              all(type(r[k]) is int and 0<=r[k]<=2 for k in (
                  'verified_signed_accession_count','verified_signed_witness_count',
                  'claimed_times_in_window_count',
                  'joint_signed_custody_witness_and_parent_count',
                  'real_ec405_parent_joint_warc_timestamp_count')) and
              r['joint_signed_custody_witness_and_parent_count']<=r['claimed_times_in_window_count']<=r['verified_signed_witness_count']<=r['verified_signed_accession_count'] and
              r['joint_signed_custody_witness_and_parent_count']<=r['real_ec405_parent_joint_warc_timestamp_count'] and
              sha_ok(r['custody_witness_epoch_inventory_sha256'])
              for i,r in enumerate(rows)) and
          type(doc.get('verified_joint_custody_witness_and_real_parent_publishers')) is int and
          doc['verified_joint_custody_witness_and_real_parent_publishers']==sum(
              r['joint_signed_custody_witness_and_parent_count'] for r in rows))
        if not valid:_fail('EC406_CHILD_CUSTODY_WITNESS_RESULT_INVALID',status='unavailable')
    elif rc in (3,4,5):
        valid=(type(doc) is dict and set(doc)==common|{'reason_code'} and
          doc.get('schema')=='ces.ec406.original_cross_witness_custody_denial.v1' and
          doc.get('command')=='audit-historical-ec339-custody-witness' and
          doc.get('exit_code')==rc and STATUS_EXITS.get(doc.get('status'))==rc and
          doc.get('offline_unresolved_exit_code')==2 and
          doc.get('sender_origin_path_required_or_read') is False and
          doc.get('ec339_to_ec337_full_independent_unmocked_external_acceptance_performed') is False and
          all(doc.get(k) is False for k in EC406_NEGATIVES) and
          type(doc.get('reason_code')) is str and
          re.fullmatch('[A-Z][A-Z0-9_]{2,175}',doc['reason_code']) is not None)
        if not valid:_fail('EC406_CHILD_CUSTODY_WITNESS_DENIAL_INVALID',status='unavailable')
    else:
        _fail('EC406_CHILD_EXIT_CODE_INVALID',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc


