def audit_historical_ec339_institutional_cms(action: str, mode: str,
                                              *, pretty: bool=False, **inputs) -> int:
    if (action,mode)!=('DeliveryAudit','AuditHistoricalEC339InstitutionalCMS'):
        _fail('EC407_ONLY_FIXED_OFFLINE_READONLY_ACTION_MODE_ALLOWED',
              status='permission_denied')
