def audit_historical_ec339_institutional_ocsp(action: str, mode: str,
                                               *,pretty: bool=False, **inputs) -> int:
    if (action,mode)!=('DeliveryAudit','AuditHistoricalEC339InstitutionalOCSP'):
        _fail('EC408_ONLY_FIXED_OFFLINE_READONLY_OCSP_ACTION_MODE_ALLOWED',
              status='permission_denied')
    if (not AIRGAP_EC339_INSTITUTIONAL_OCSP.is_file() or
            AIRGAP_EC339_INSTITUTIONAL_OCSP.is_symlink()):
        _fail('EC408_ISOLATED_ORIGINAL_OCSP_RECEIVER_MISSING',status='unavailable')
    if set(inputs)!=set(EC408_ALL_SCALARS)|{key for key,_ in EC408_ALL_REPEATS}:
        _fail('EC408_FULL_EC407_AND_DUAL_ORIGINAL_OCSP_ARGUMENTS_REQUIRED')
