    for key,flag in EC411_ALL_REPEATS:
        for value in inputs[key]:
            argv.extend([flag,'none' if value is None else str(value)])
    rc,doc=_command(argv,timeout=3200,max_output=2000000)
    common={'schema','command','status','exit_code','offline_unresolved_exit_code',
            'sender_origin_path_required_or_read',
            'ec339_to_ec337_full_independent_unmocked_external_acceptance_performed',
            *EC411_NEGATIVES}
    if rc==2:
        other={'verified_live_ec410_report_sha256',
               'verified_live_ec410_inventory_sha256',
               'original_signed_lotl_bundle_sha256',
               'receiver_verified_xades_cert_v2_inventory_sha256',
               'verified_joint_signed_xades_v2_and_real_ec410_parent_publishers',
               'xades_cert_v2_epoch_reviews',
               'bounded_original_signed_xades_cert_v2_and_real_ec410_consistency',
               *EC411_FLAGS}
        fields={'epoch_index','verified_genuine_original_signed_xades_v2_pair',
                'joint_real_ec410_and_original_xades_v2_publisher_count',
                'xades_v2_epoch_inventory_sha256',
                'genuine_ec410_parent_joint_signed_lotl_publisher_count'}
        rows=doc.get('xades_cert_v2_epoch_reviews') if type(doc) is dict else None
        valid=(type(doc) is dict and set(doc)==common|other and
            doc.get('schema')=='ces.ec411.original_xades_cert_v2_unresolved.v1' and
            doc.get('command')=='audit-historical-ec339-xades-cert-v2' and
            doc.get('exit_code')==doc.get('offline_unresolved_exit_code')==2 and
            doc.get('sender_origin_path_required_or_read') is False and
            doc.get('ec339_to_ec337_full_independent_unmocked_external_acceptance_performed') is False and
            all(doc.get(k) is False for k in EC411_NEGATIVES) and
            all(type(doc.get(k)) is bool for k in EC411_FLAGS) and
            all(doc[k] is True for k in EC411_FLAGS[-3:]) and
            doc.get('bounded_original_signed_xades_cert_v2_and_real_ec410_consistency') is
                (not any(doc[k] for k in EC411_FLAGS[:4])) and
            doc.get('status')==next((EC411_OUTCOMES[i] for i,k in enumerate(EC411_FLAGS)
                                    if doc[k]),EC411_OUTCOMES[-1])+'_unresolved' and
            all(sha_ok(doc.get(k)) for k in (
                 'verified_live_ec410_report_sha256',
                 'verified_live_ec410_inventory_sha256',
                 'original_signed_lotl_bundle_sha256',
                 'receiver_verified_xades_cert_v2_inventory_sha256')) and
            doc.get('original_signed_lotl_bundle_sha256')==inputs[
                 'expected_historical_ec339_signed_lotl_bundle_sha256'] and
            doc.get('verified_live_ec410_inventory_sha256')==inputs[
                 'expected_retained_historical_ec339_signed_lotl_inventory_sha256'] and
            type(rows) is list and len(rows)==n and all(
                 type(r) is dict and set(r)==fields and
                 type(r['epoch_index']) is int and r['epoch_index']==i and
                 type(r['verified_genuine_original_signed_xades_v2_pair']) is int and
                 r['verified_genuine_original_signed_xades_v2_pair'] in (0,1) and
                 all(type(r[k]) is int and 0<=r[k]<=2 for k in (
                     'joint_real_ec410_and_original_xades_v2_publisher_count',
                     'genuine_ec410_parent_joint_signed_lotl_publisher_count')) and
                 (r['verified_genuine_original_signed_xades_v2_pair']==1 or
                  r['joint_real_ec410_and_original_xades_v2_publisher_count']==0) and
                 r['joint_real_ec410_and_original_xades_v2_publisher_count']<=
                    r['genuine_ec410_parent_joint_signed_lotl_publisher_count'] and
                 sha_ok(r['xades_v2_epoch_inventory_sha256'])
                 for i,r in enumerate(rows)) and
            type(doc.get('verified_joint_signed_xades_v2_and_real_ec410_parent_publishers')) is int and
            doc['verified_joint_signed_xades_v2_and_real_ec410_parent_publishers']==sum(
                 r['joint_real_ec410_and_original_xades_v2_publisher_count'] for r in rows))
        if not valid:
            _fail('EC411_CHILD_XADES_V2_REPORT_CONTRACT_INVALID',status='unavailable')
    elif rc in (3,4,5):
        valid=(type(doc) is dict and set(doc)==common|{'reason_code'} and
            doc.get('schema')=='ces.ec411.xades_cert_v2_denial.v1' and
            doc.get('command')=='audit-historical-ec339-xades-cert-v2' and
            doc.get('exit_code')==rc and STATUS_EXITS.get(doc.get('status'))==rc and
            doc.get('offline_unresolved_exit_code')==2 and
            doc.get('sender_origin_path_required_or_read') is False and
            doc.get('ec339_to_ec337_full_independent_unmocked_external_acceptance_performed') is False and
            all(doc.get(k) is False for k in EC411_NEGATIVES) and
            type(doc.get('reason_code')) is str and
            re.fullmatch('[A-Z][A-Z0-9_]{2,175}',doc['reason_code']) is not None)
        if not valid:
            _fail('EC411_CHILD_XADES_V2_DENIAL_CONTRACT_INVALID',status='unavailable')
    else:
        _fail('EC411_CHILD_XADES_V2_EXIT_INVALID',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc




