def audit_historical_ec339_lotl_crl(action: str, mode: str,
                                    *, pretty: bool=False, **inputs) -> int:
    if (action, mode) != ('DeliveryAudit', 'AuditHistoricalEC339LOTLCARevocation'):
        _fail('EC412_ONLY_FIXED_READONLY_LOTL_CA_REVOCATION_AUDIT_MODE',
              status='permission_denied')
    if (not AIRGAP_EC339_LOTL_CA_CRL.is_file() or
        AIRGAP_EC339_LOTL_CA_CRL.is_symlink()):
        _fail('EC412_ISOLATED_ORIGINAL_LOTL_CA_CRL_RECEIVER_NOT_AVAILABLE',
              status='unavailable')
    if set(inputs) != set(EC412_ALL_SCALARS) | {k for k,_ in EC412_ALL_REPEATS}:
        _fail('EC412_EXACT_PARENT_CRL_ORIGINAL_ARGUMENTS_REQUIRED')
    sha_ok=lambda x:type(x) is str and re.fullmatch('[0-9a-f]{64}',x) is not None and x!='0'*64
    n = (len(inputs['historical_directory_root_shas'])
         if type(inputs['historical_directory_root_shas']) is list else 0)
    if not 1<=n<=3:
        _fail('EC412_ONE_TO_THREE_PARENT_ORIGINAL_EPOCHS_REQUIRED')
    for key in (*EC412_NEW_SCALARS[1:],
                'expected_retained_historical_ec339_lotl_crl_inventory_sha256'):
        if not sha_ok(inputs[key]):
            _fail('EC412_OUTSIDE_FIRST_AND_RETAINED_CRLS_SHA_REQUIRED')
    if len({inputs[key] for key in EC412_NEW_SCALARS[2:]})!=4:
        _fail('EC412_FOUR_DISTINCT_FIRST_ORIGINAL_CRLS_REQUIRED')
    for key,_ in EC412_NEW_REPEATS:
        vals=inputs[key]
        if type(vals) is not list or len(vals)!=n:
            _fail('EC412_EPOCH_CRL_SHA_AND_PUBLISHER_FLOOR_REQUIRED')
        if key.startswith('minimum_'):
            if any(type(x) is not int or not 0<=x<=2 for x in vals):
                _fail('EC412_JOINT_CRL_PUBLISHER_FLOOR_INVALID')
        elif any(not sha_ok(x) for x in vals):
            _fail('EC412_ORIGINAL_CRL_EPOCH_SHA_INVALID')
    argv=[sys.executable,'-I','-B',str(AIRGAP_EC339_LOTL_CA_CRL),
          'audit-historical-ec339-lotl-crl']
    for key in EC412_ALL_SCALARS:
        argv.extend(['--'+key.replace('_','-'),str(inputs[key])])
    for key,flag in EC412_ALL_REPEATS:
        for value in inputs[key]:
            argv.extend([flag, 'none' if value is None else str(value)])
    rc,doc=_command(argv,timeout=3200,max_output=2000000)
    common={'schema','command','status','exit_code','offline_unresolved_exit_code',
            'sender_origin_path_required_or_read',
            'ec339_to_ec337_full_independent_unmocked_external_acceptance_performed',
            *EC412_NEGATIVES}
    if rc==2:
        other={'verified_live_ec411_report_sha256',
               'verified_live_ec411_inventory_sha256',
               'original_lotl_ca_crl_bundle_sha256',
               'receiver_verified_lotl_ca_crl_inventory_sha256',
               'verified_joint_crl_and_real_ec411_parent_publishers',
               'lotl_ca_crl_epoch_reviews',
               'bounded_original_ca_crl_and_real_ec411_parent_consistency',
               *EC412_FLAGS}
        fields={'epoch_index','verified_original_ca_crl_historical_evaluation_four_documents',
                'joint_genuine_crl_and_real_ec411_parent_publisher_count',
                'lotl_ca_crl_epoch_inventory_sha256',
                'genuine_ec411_parent_xades_v2_joint_publisher_count'}
        rows=doc.get('lotl_ca_crl_epoch_reviews') if type(doc) is dict else None
        valid=(type(doc) is dict and set(doc)==common|other and
            doc.get('schema')=='ces.ec412.original_lotl_ca_crl_unresolved.v1' and
            doc.get('command')=='audit-historical-ec339-lotl-crl' and
            doc.get('exit_code')==doc.get('offline_unresolved_exit_code')==2 and
            doc.get('sender_origin_path_required_or_read') is False and
            doc.get('ec339_to_ec337_full_independent_unmocked_external_acceptance_performed') is False and
            all(doc.get(k) is False for k in EC412_NEGATIVES) and
            all(type(doc.get(k)) is bool for k in EC412_FLAGS) and
            all(doc[k] is True for k in EC412_FLAGS[-3:]) and
            doc.get('bounded_original_ca_crl_and_real_ec411_parent_consistency')
                is (not any(doc[k] for k in EC412_FLAGS[:4])) and
            doc.get('status')==next((EC412_OUTCOMES[i] for i,k in enumerate(EC412_FLAGS)
                                    if doc[k]),EC412_OUTCOMES[-1])+'_unresolved' and
            all(sha_ok(doc.get(k)) for k in (
                'verified_live_ec411_report_sha256',
                'verified_live_ec411_inventory_sha256',
                'original_lotl_ca_crl_bundle_sha256',
                'receiver_verified_lotl_ca_crl_inventory_sha256')) and
            doc.get('original_lotl_ca_crl_bundle_sha256')==inputs[
                'expected_historical_ec339_lotl_crl_bundle_sha256'] and
            doc.get('verified_live_ec411_inventory_sha256')==inputs[
                'expected_retained_historical_ec339_xades_cert_v2_inventory_sha256'] and
            type(rows) is list and len(rows)==n and all(
                type(row) is dict and set(row)==fields and
                type(row['epoch_index']) is int and row['epoch_index']==i and
                type(row['verified_original_ca_crl_historical_evaluation_four_documents']) is int and
                row['verified_original_ca_crl_historical_evaluation_four_documents'] in (0,1) and
                all(type(row[k]) is int and 0<=row[k]<=2 for k in (
                    'joint_genuine_crl_and_real_ec411_parent_publisher_count',
                    'genuine_ec411_parent_xades_v2_joint_publisher_count')) and
                (row['verified_original_ca_crl_historical_evaluation_four_documents']==1 or
                 row['joint_genuine_crl_and_real_ec411_parent_publisher_count']==0) and
                row['joint_genuine_crl_and_real_ec411_parent_publisher_count']<=
                    row['genuine_ec411_parent_xades_v2_joint_publisher_count'] and
                sha_ok(row['lotl_ca_crl_epoch_inventory_sha256'])
                for i,row in enumerate(rows)) and
            type(doc.get('verified_joint_crl_and_real_ec411_parent_publishers')) is int and
            doc['verified_joint_crl_and_real_ec411_parent_publishers']==sum(
                row['joint_genuine_crl_and_real_ec411_parent_publisher_count']
                for row in rows))
        if not valid:
            _fail('EC412_CHILD_ORIGINAL_CRL_REPORT_CONTRACT_INVALID',
                  status='unavailable')
    elif rc in (3,4,5):
        valid=(type(doc) is dict and set(doc)==common|{'reason_code'} and
            doc.get('schema')=='ces.ec412.lotl_ca_crl_denial.v1' and
            doc.get('command')=='audit-historical-ec339-lotl-crl' and
            doc.get('exit_code')==rc and STATUS_EXITS.get(doc.get('status'))==rc and
            doc.get('offline_unresolved_exit_code')==2 and
            doc.get('sender_origin_path_required_or_read') is False and
            doc.get('ec339_to_ec337_full_independent_unmocked_external_acceptance_performed') is False and
            all(doc.get(k) is False for k in EC412_NEGATIVES) and
            type(doc.get('reason_code')) is str and
            re.fullmatch('[A-Z][A-Z0-9_]{2,175}',doc['reason_code']) is not None)
        if not valid:
            _fail('EC412_CHILD_ORIGINAL_CRL_DENIAL_CONTRACT_INVALID',
                  status='unavailable')
    else:
        _fail('EC412_CHILD_ORIGINAL_CRL_EXIT_INVALID',status='unavailable')
    _emit(doc,pretty=pretty)
    return rc


