def audit_historical_ec339_lotl_ocsp_publication(action: str, mode: str,
                                                  *, pretty: bool=False,
                                                  **inputs) -> int:
    if (action, mode) != (
        'DeliveryAudit', 'AuditHistoricalEC339LOTLOCSPPublication'):
        _fail('EC414_ONLY_FIXED_READONLY_LOTL_OCSP_PUBLICATION_AUDIT_MODE',
              status='permission_denied')
    if (not AIRGAP_EC339_LOTL_OCSP_PUBLICATION.is_file() or
        AIRGAP_EC339_LOTL_OCSP_PUBLICATION.is_symlink()):
        _fail('EC414_ISOLATED_ACTUAL_OCSP_PUBLICATION_RECEIVER_NOT_AVAILABLE',
              status='unavailable')
    if set(inputs) != set(EC414_ALL_SCALARS) | {k for k, _ in EC414_ALL_REPEATS}:
        _fail('EC414_EXACT_REAL_EC413_AND_PUBLICATION_ARGUMENTS_REQUIRED')
    good_sha = lambda x: (type(x) is str and
             re.fullmatch('[0-9a-f]{64}', x) is not None and x != '0'*64)
    n = (len(inputs['historical_directory_root_shas'])
         if type(inputs['historical_directory_root_shas']) is list else 0)
    if not 1 <= n <= 3:
        _fail('EC414_ONE_TO_THREE_REAL_PARENT_EPOCHS_REQUIRED')
    for key in (*EC414_NEW_SCALARS[1:],
                'expected_retained_historical_ec339_lotl_ocsp_publication_inventory_sha256'):
        if not good_sha(inputs[key]):
            _fail('EC414_FIRST_OR_RETAINED_ORIGINAL_SHA_PIN_REQUIRED')
    if len({inputs[k] for k in EC414_NEW_SCALARS[3:]}) != len(EC414_NEW_SCALARS[3:]):
        _fail('EC414_DISTINCT_KEYS_WARC_AND_RECEIPT_FIRST_ORIGINAL_PINS_REQUIRED')
    for key, _ in EC414_NEW_REPEATS:
        values = inputs[key]
        if type(values) is not list or len(values) != n:
            _fail('EC414_PER_EPOCH_SOURCE_INVENTORY_AND_FLOOR_COUNT_REQUIRED')
        if key.startswith('minimum_'):
            if any(type(v) is not int or not 0 <= v <= 2 for v in values):
                _fail('EC414_PER_EPOCH_PUBLICATION_FLOOR_OUT_OF_RANGE')
        elif any(not good_sha(v) for v in values):
            _fail('EC414_PER_EPOCH_PUBLICATION_SHA_PIN_INVALID')
    argv = [sys.executable, '-I', '-B', str(AIRGAP_EC339_LOTL_OCSP_PUBLICATION),
            'audit-historical-ec339-lotl-ocsp-publication']
    for key in EC414_ALL_SCALARS:
        argv.extend(['--' + key.replace('_','-'), str(inputs[key])])
    for key, flag in EC414_ALL_REPEATS:
        for value in inputs[key]:
            argv.extend([flag, 'none' if value is None else str(value)])
    rc, doc = _command(argv, timeout=3400, max_output=2_000_000)
    common = {'schema', 'command', 'status', 'exit_code',
              'offline_unresolved_exit_code',
              'sender_origin_path_required_or_read',
              'ec339_to_ec337_full_independent_unmocked_external_acceptance_performed',
              *EC414_NEGATIVES}
    if rc == 2:
        fields = {'epoch_index',
                  'verified_http_200_original_ocsp_warc_response_count',
                  'verified_signed_witness_claim_time_window_count',
                  'joint_original_publication_and_real_ec413_publisher_count',
                  'original_publication_epoch_inventory_sha256',
                  'real_ec413_original_ocsp_parent_joint_publisher_count'}
        rows = doc.get('ocsp_publication_epoch_reviews') if type(doc) is dict else None
        required = {'verified_live_ec413_report_sha256',
                    'verified_live_ec413_inventory_sha256',
                    'original_ocsp_publication_bundle_sha256',
                    'receiver_verified_ocsp_publication_inventory_sha256',
                    'verified_joint_publication_and_real_ec413_publishers',
                    'ocsp_publication_epoch_reviews',
                    'bounded_dual_witness_original_publication_and_real_ec413_parent_consistency',
                    *EC414_FLAGS}
        valid = (type(doc) is dict and set(doc) == common | required and
            doc.get('schema') == 'ces.ec414.original_ocsp_publication_witness_unresolved.v1' and
            doc.get('command') == 'audit-historical-ec339-lotl-ocsp-publication' and
            doc.get('exit_code') == doc.get('offline_unresolved_exit_code') == 2 and
            doc.get('sender_origin_path_required_or_read') is False and
            doc.get('ec339_to_ec337_full_independent_unmocked_external_acceptance_performed')
                is False and
            all(doc.get(k) is False for k in EC414_NEGATIVES) and
            all(type(doc.get(k)) is bool for k in EC414_FLAGS) and
            all(doc[k] is True for k in EC414_FLAGS[-3:]) and
            doc.get('bounded_dual_witness_original_publication_and_real_ec413_parent_consistency')
                is (not any(doc[k] for k in EC414_FLAGS[:5])) and
            doc.get('status') == next((EC414_OUTCOMES[i]
                for i, flag in enumerate(EC414_FLAGS) if doc[flag]),
                EC414_OUTCOMES[-1]) + '_unresolved' and
            all(good_sha(doc.get(k)) for k in (
                'verified_live_ec413_report_sha256',
                'verified_live_ec413_inventory_sha256',
                'original_ocsp_publication_bundle_sha256',
                'receiver_verified_ocsp_publication_inventory_sha256')) and
            doc.get('original_ocsp_publication_bundle_sha256') == inputs[
                'expected_historical_ec339_lotl_ocsp_publication_bundle_sha256'] and
            doc.get('verified_live_ec413_inventory_sha256') == inputs[
                'expected_retained_historical_ec339_lotl_ocsp_inventory_sha256'] and
            type(rows) is list and len(rows) == n and all(
                type(row) is dict and set(row) == fields and
                type(row['epoch_index']) is int and row['epoch_index'] == i and
                type(row['verified_http_200_original_ocsp_warc_response_count']) is int and
                row['verified_http_200_original_ocsp_warc_response_count'] in (0,2,4) and
                type(row['verified_signed_witness_claim_time_window_count']) is int and
                0 <= row['verified_signed_witness_claim_time_window_count'] <=
                    row['verified_http_200_original_ocsp_warc_response_count'] // 2 and
                type(row['joint_original_publication_and_real_ec413_publisher_count'])
                    is int and
                type(row['real_ec413_original_ocsp_parent_joint_publisher_count'])
                    is int and
                0 <= row['joint_original_publication_and_real_ec413_publisher_count'] <=
                    row['real_ec413_original_ocsp_parent_joint_publisher_count'] <= 2 and
                (row['verified_http_200_original_ocsp_warc_response_count'] == 4 and
                 row['verified_signed_witness_claim_time_window_count'] == 2 or
                 row['joint_original_publication_and_real_ec413_publisher_count'] == 0) and
                row['joint_original_publication_and_real_ec413_publisher_count'] in (0,2) and
                good_sha(row['original_publication_epoch_inventory_sha256'])
                for i, row in enumerate(rows)) and
            type(doc.get('verified_joint_publication_and_real_ec413_publishers')) is int and
            doc['verified_joint_publication_and_real_ec413_publishers'] == sum(
                row['joint_original_publication_and_real_ec413_publisher_count']
                for row in rows))
        if not valid:
            _fail('EC414_CHILD_ORIGINAL_PUBLICATION_REPORT_CONTRACT_INVALID',
                  status='unavailable')
    elif rc in (3,4,5):
        valid = (type(doc) is dict and set(doc) == common | {'reason_code'} and
            doc.get('schema') == 'ces.ec414.ocsp_publication_witness_denial.v1' and
            doc.get('command') == 'audit-historical-ec339-lotl-ocsp-publication' and
            doc.get('exit_code') == rc and STATUS_EXITS.get(doc.get('status')) == rc and
            doc.get('offline_unresolved_exit_code') == 2 and
            doc.get('sender_origin_path_required_or_read') is False and
            doc.get('ec339_to_ec337_full_independent_unmocked_external_acceptance_performed')
                is False and
            all(doc.get(k) is False for k in EC414_NEGATIVES) and
            type(doc.get('reason_code')) is str and
            re.fullmatch('[A-Z][A-Z0-9_]{2,175}',doc['reason_code']) is not None)
        if not valid:
            _fail('EC414_CHILD_ORIGINAL_PUBLICATION_DENIAL_CONTRACT_INVALID',
                  status='unavailable')
    else:
        _fail('EC414_CHILD_ORIGINAL_PUBLICATION_EXIT_INVALID',status='unavailable')
    _emit(doc, pretty=pretty)
    return rc


